/**
 * OpenAI 兼容 TTS（3.2-A）单元测试
 *
 * 验证 /audio/speech 请求构造、响应解析、错误处理。
 * mock 全局 fetch，不发起真实网络请求。
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'

// electron 运行时依赖 mock（tts.ts 使用 spawn 等）
vi.mock('electron', () => ({
  app: { getPath: () => '/tmp/qingyu-test' },
}))

import { openaiSpeak, OPENAI_VOICES } from '../tts'

beforeEach(() => {
  vi.stubGlobal('fetch', vi.fn())
})

afterEach(() => {
  vi.unstubAllGlobals()
  vi.restoreAllMocks()
})

describe('openaiSpeak', () => {
  it('请求构造正确（POST /audio/speech + Bearer + 参数）', async () => {
    const fetchMock = vi.fn().mockResolvedValue(new Response(new Uint8Array([1, 2, 3]), { status: 200 }))
    vi.stubGlobal('fetch', fetchMock)

    const base64 = await openaiSpeak(
      { baseUrl: 'https://api.openai.com/v1', apiKey: 'sk-123', model: 'tts-1', voice: 'nova', speed: 1 },
      '你好世界',
    )

    const [url, init] = fetchMock.mock.calls[0]
    expect(url).toBe('https://api.openai.com/v1/audio/speech')
    expect(init.method).toBe('POST')
    expect(init.headers.Authorization).toBe('Bearer sk-123')
    const body = JSON.parse(init.body)
    expect(body.model).toBe('tts-1')
    expect(body.input).toBe('你好世界')
    expect(body.voice).toBe('nova')
    expect(body.response_format).toBe('mp3')
    // base64([1,2,3]) = AQID
    expect(base64).toBe('AQID')
  })

  it('baseUrl 尾部斜杠兼容', async () => {
    const fetchMock = vi.fn().mockResolvedValue(new Response(new Uint8Array([1]), { status: 200 }))
    vi.stubGlobal('fetch', fetchMock)
    await openaiSpeak({ baseUrl: 'http://localhost:8080/v1/', apiKey: '', model: 'tts-1', voice: 'alloy' }, 'x')
    expect(fetchMock.mock.calls[0][0]).toBe('http://localhost:8080/v1/audio/speech')
  })

  it('无 apiKey 时省略 Authorization 头', async () => {
    const fetchMock = vi.fn().mockResolvedValue(new Response(new Uint8Array([1]), { status: 200 }))
    vi.stubGlobal('fetch', fetchMock)
    await openaiSpeak({ baseUrl: 'https://x/v1', apiKey: '', model: 'tts-1', voice: 'alloy' }, 'x')
    expect(fetchMock.mock.calls[0][1].headers.Authorization).toBeUndefined()
  })

  it('超长输入截断（4000 字符）', async () => {
    const fetchMock = vi.fn().mockResolvedValue(new Response(new Uint8Array([1]), { status: 200 }))
    vi.stubGlobal('fetch', fetchMock)
    await openaiSpeak({ baseUrl: 'https://x/v1', apiKey: '', model: 'tts-1', voice: 'alloy' }, 'x'.repeat(5000))
    const body = JSON.parse(fetchMock.mock.calls[0][1].body)
    expect(body.input.length).toBe(4000)
  })

  it('HTTP 错误抛错', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(new Response('invalid', { status: 401 })))
    await expect(openaiSpeak({ baseUrl: 'https://x/v1', apiKey: 'k', model: 'tts-1', voice: 'alloy' }, 'x')).rejects.toThrow('401')
  })
})

describe('OPENAI_VOICES', () => {
  it('包含常用音色', () => {
    const ids = OPENAI_VOICES.map((v) => v.id)
    expect(ids).toContain('alloy')
    expect(ids).toContain('nova')
    expect(ids).toContain('onyx')
    expect(ids.length).toBeGreaterThanOrEqual(6)
  })
})

describe('edgeSpeak（Edge TTS 引擎）', () => {
  it('合成 mp3 并返回 base64（临时文件清理 + proxy 透传）', async () => {
    // mock node-edge-tts：ttsPromise 写一个假 mp3 文件
    let writtenPath = ''
    let ctorOpts: any = null
    vi.doMock('node-edge-tts', () => ({
      EdgeTTS: class {
        constructor(opts: any) { ctorOpts = opts }
        async ttsPromise(_text: string, audioPath: string) {
          writtenPath = audioPath
          const { writeFileSync } = await import('node:fs')
          writeFileSync(audioPath, Buffer.from([0x66, 0xff, 0xf3]), 'utf-8')
        }
      },
    }))
    // 重新加载模块以应用 mock
    vi.resetModules()
    const { edgeSpeak } = await import('../tts')
    const base64 = await edgeSpeak('你好', 'zh-CN-XiaoxiaoNeural', { proxy: 'http://127.0.0.1:7890' })
    expect(base64).toBe(Buffer.from([0x66, 0xff, 0xf3]).toString('base64'))
    // 代理透传到 EdgeTTS 构造参数
    expect(ctorOpts.proxy).toBe('http://127.0.0.1:7890')
    // 临时文件已清理
    const { existsSync } = await import('node:fs')
    expect(existsSync(writtenPath)).toBe(false)
    vi.unmock('node-edge-tts')
    vi.resetModules()
  })

  it('空音频数据抛错', async () => {
    vi.doMock('node-edge-tts', () => ({
      EdgeTTS: class {
        async ttsPromise(_text: string, audioPath: string) {
          const { writeFileSync } = await import('node:fs')
          writeFileSync(audioPath, Buffer.alloc(0), 'utf-8')
        }
      },
    }))
    vi.resetModules()
    const { edgeSpeak } = await import('../tts')
    await expect(edgeSpeak('x', 'zh-CN-XiaoxiaoNeural')).rejects.toThrow('未生成音频数据')
    vi.unmock('node-edge-tts')
    vi.resetModules()
  })

  it('EDGE_VOICES 包含常用中文音色', async () => {
    vi.resetModules()
    const { EDGE_VOICES } = await import('../tts')
    const ids = EDGE_VOICES.map((v) => v.id)
    expect(ids).toContain('zh-CN-XiaoxiaoNeural')
    expect(ids).toContain('zh-CN-YunxiNeural')
  })
})

/**
 * 在线公告 IPC 接口
 *
 * - announcement:fetchList    获取公告列表
 * - announcement:fetchDetail  获取公告详情
 * - announcement:getServerUrl 获取公告服务器地址
 * - announcement:setServerUrl 设置公告服务器地址
 */

import type { IpcMain } from 'electron'
import { join } from 'node:path'
import { DIRS, readJson, writeJson } from '../services/storage'
import { createLogger } from '../services/logger'
import { isSafeUrl } from '../utils/pathGuard'
import type { Announcement } from '../../shared/types'

const log = createLogger('announcement-ipc')

/** 默认公告服务器地址 */
const DEFAULT_SERVER_URL = 'http://cjbtj.xyz'

/** 公告服务器 URL 存储文件 */
const ANNOUNCE_CONFIG_FILE = () => join(DIRS.config(), 'announce-config.json')

/** 公告缓存文件 */
const ANNOUNCE_CACHE_FILE = () => join(DIRS.config(), 'announcements-cache.json')

/** 读取服务器 URL */
function getServerUrl(): string {
  const config = readJson<{ serverUrl: string }>(ANNOUNCE_CONFIG_FILE())
  return config?.serverUrl || DEFAULT_SERVER_URL
}

/** 设置服务器 URL */
function setServerUrl(url: string): void {
  writeJson(ANNOUNCE_CONFIG_FILE(), { serverUrl: url })
}

/** 发起 HTTP GET 请求 */
function httpGet(url: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const mod = url.startsWith('https') ? require('node:https') : require('node:http')
    mod.get(url, { timeout: 10000 }, (res: any) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume()
        return httpGet(res.headers.location).then(resolve, reject)
      }
      let data = ''
      res.on('data', (chunk: string) => { data += chunk })
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve(data)
        } else {
          res.resume()
          reject(new Error(`HTTP ${res.statusCode}`))
        }
      })
    }).on('error', reject).on('timeout', function(this: any) { this.destroy(); reject(new Error('请求超时')) })
  })
}

/** 读取缓存 */
function readCache(): Announcement[] {
  return readJson<Announcement[]>(ANNOUNCE_CACHE_FILE()) ?? []
}

/** 写入缓存 */
function writeCache(items: Announcement[]): void {
  writeJson(ANNOUNCE_CACHE_FILE(), items)
}

/** 注册公告 IPC 处理器 */
export function registerAnnouncementIPC(ipcMain: IpcMain): void {
  // 获取公告列表
  ipcMain.handle('announcement:fetchList', async (_e, page = 1, pageSize = 20) => {
    const baseUrl = getServerUrl()
    const url = `${baseUrl}/api/announcements?page=${page}&pageSize=${pageSize}`

    try {
      const body = await httpGet(url)
      const data = JSON.parse(body)
      // 缓存列表（仅缓存 items，离线备用）
      if (data.items) {
        writeCache(data.items)
      }
      return data
    } catch (err: any) {
      log.warn('获取公告列表失败，使用缓存', { error: err.message })
      const cached = readCache()
      return { items: cached, total: cached.length, page, pageSize }
    }
  })

  // 获取公告详情
  ipcMain.handle('announcement:fetchDetail', async (_e, id: number) => {
    const baseUrl = getServerUrl()
    const url = `${baseUrl}/api/announcements/${id}`

    try {
      const body = await httpGet(url)
      return JSON.parse(body) as Announcement
    } catch (err: any) {
      log.warn('获取公告详情失败，使用缓存', { id, error: err.message })
      const cached = readCache()
      return cached.find((a) => a.id === id) ?? null
    }
  })

  // 获取服务器地址
  ipcMain.handle('announcement:getServerUrl', async () => {
    return getServerUrl()
  })

  // 设置服务器地址
  ipcMain.handle('announcement:setServerUrl', async (_e, url: string) => {
    if (!isSafeUrl(url)) {
      throw new Error('URL 不安全：拒绝私有 IP、localhost 或非 HTTP(S) 协议')
    }
    setServerUrl(url)
  })

  // 检查最新版本
  ipcMain.handle('app:checkVersion', async () => {
    const baseUrl = getServerUrl()
    const url = `${baseUrl}/api/version`

    try {
      const body = await httpGet(url)
      return JSON.parse(body) as { version: string; changelog: string; downloadUrl: string }
    } catch (err: any) {
      log.warn('检查版本失败', { error: err.message })
      return null
    }
  })

  log.info('公告 IPC 已注册')
}

import type { IpcMain } from 'electron'
import { createLogger } from '../services/logger'
import { generateImage, testImageGenConnection, type ImageGenOptions } from '../services/imageGen'
import { readJson, DIRS } from '../services/storage'
import { join } from 'node:path'
import type { Settings, ConnectionProfile } from '../../shared/types'

const log = createLogger('imageGenIPC')

/** 使用用户的 AI API 将中文 prompt 翻译为英文 */
async function translatePromptToEnglish(prompt: string, settings: Settings): Promise<string> {
  // 获取当前活动的连接 profile
  let profile: ConnectionProfile | undefined
  if (settings.activeProfileId) {
    profile = settings.connectionProfiles?.find(p => p.id === settings.activeProfileId)
  }
  if (!profile) {
    profile = settings.connectionProfiles?.[0]
  }
  if (!profile) {
    throw new Error('没有可用的 API 连接配置')
  }

  // 读取 API Key
  const { readJson: readCredJson } = await import('../services/storage')
  let apiKey = profile.apiKey || ''
  if (!apiKey && profile.id) {
    try {
      const creds = readCredJson<Record<string, string>>(join(DIRS.config(), 'credentials.json'))
      if (creds && creds[profile.id]) {
        apiKey = creds[profile.id]
      }
    } catch { /* ignore */ }
  }
  if (!apiKey) {
    throw new Error('API Key 未配置')
  }

  const baseUrl = profile.baseUrl.replace(/\/$/, '')
  const url = `${baseUrl}/chat/completions`

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: profile.model,
      messages: [
        {
          role: 'system',
          content: 'You are a translator. Translate the following Chinese image generation prompt into English tags separated by commas. Only output the English prompt, nothing else. Do NOT add explanations.',
        },
        { role: 'user', content: prompt },
      ],
      temperature: 0.3,
      max_tokens: 200,
    }),
    signal: AbortSignal.timeout(15000),
  })

  if (!response.ok) {
    throw new Error(`翻译 API 返回 ${response.status}`)
  }

  const data: any = await response.json()
  const translated = data?.choices?.[0]?.message?.content?.trim()
  if (!translated) {
    throw new Error('翻译 API 返回空结果')
  }

  return translated.replace(/<thought>[\s\S]*?<\/thought>/gi, '').trim()
}

export function registerImageGenIPC(ipcMain: IpcMain): void {
  ipcMain.handle('imageGen:generate', async (_e, prompt: string, options?: ImageGenOptions) => {
    try {
      // 从 settings.json 读取完整配置
      const settings = readJson<Settings>(join(DIRS.config(), 'settings.json'))
      if (!settings) {
        return { success: false, error: '设置读取失败' }
      }

      // 找到当前激活的生图模型
      const config = settings.imageGenModels?.find(
        (m) => m.id === settings.activeImageGenModelId && m.enabled,
      )
      if (!config) {
        return { success: false, error: '未配置启用的生图模型，请前往 设置 -> API -> 生图 配置' }
      }

      // 尺寸优先级：options.size > settings.imageGenSize > config.size
      const size = options?.size || settings.imageGenSize || config.size

      // SD WebUI：如果 prompt 包含中文，翻译为英文
      let finalPrompt = prompt
      if (config.provider === 'sd-webui' && /[\u4e00-\u9fff]/.test(prompt)) {
        try {
          const translated = await translatePromptToEnglish(prompt, settings)
          log.info('中文提示词已翻译为英文', {
            original: prompt.substring(0, 60),
            translated: translated.substring(0, 60),
          })
          finalPrompt = translated
        } catch (err: any) {
          log.warn('提示词翻译失败，使用原始提示词', { error: err?.message ?? String(err) })
          // 降级：继续使用原始 prompt
        }
      }

      log.info('生图调用', { provider: config.provider, prompt: finalPrompt.substring(0, 60), size })

      return await generateImage(config, finalPrompt, { ...options, size })
    } catch (err: any) {
      log.error('生图 IPC 异常', { error: err?.message ?? String(err) })
      return { success: false, error: err?.message ?? String(err) }
    }
  })

  ipcMain.handle('imageGen:testConnection', async (_e, config: { provider: string; baseUrl: string; apiKey: string }) => {
    log.info('测试连接', { provider: config.provider, baseUrl: config.baseUrl })
    return testImageGenConnection(config)
  })
}

import type { IpcMain, Dialog } from 'electron'
import { join } from 'node:path'
import { DIRS, writeJson, listJsonFilesAsync, removeFile } from '../services/storage'
import { createLogger } from '../services/logger'
import type { Lorebook } from '../../shared/types'
import { safeId } from '../utils/pathGuard'

const log = createLogger('lorebook')

export function registerLorebookIPC(ipcMain: IpcMain, dialog: Dialog): void {
  // 列表
  ipcMain.handle('lorebook:list', async () => {
    return await listJsonFilesAsync<Lorebook>(DIRS.lorebooks())
  })

  // 保存（条目内容变化时自动标记向量索引过期，语义检索会跳过过期条目）
  ipcMain.handle('lorebook:save', async (_e, lorebook: Lorebook) => {
    safeId(lorebook.id)
    const filePath = join(DIRS.lorebooks(), `${lorebook.id}.json`)
    const prev = existsSync(filePath) ? readJson<Lorebook>(filePath, 'lorebooks') : null
    writeJson(filePath, lorebook)
    // 有向量索引时，对比语义相关字段，标记变化的条目
    if (getVectorIndex(lorebook.id)) {
      const changedIds = diffSemanticEntries(prev?.entries ?? [], lorebook.entries)
      if (changedIds.length > 0) {
        markStaleEntries(lorebook.id, changedIds)
      }
    }
    log.info('世界书已保存', { id: lorebook.id, name: lorebook.name, entries: lorebook.entries.length })
  })

  // 删除
  ipcMain.handle('lorebook:delete', async (_e, id: string) => {
    safeId(id)
    removeFile(join(DIRS.lorebooks(), `${id}.json`))
    log.info('世界书已删除', { id })
  })

  // 导入
  ipcMain.handle('lorebook:importJson', async () => {
    const result = await dialog.showOpenDialog({
      title: '导入世界书',
      filters: [{ name: 'JSON 文件', extensions: ['json'] }],
      properties: ['openFile'],
    })
    if (result.canceled || result.filePaths.length === 0) return null

    const { readFileSync } = require('node:fs')
    const raw = readFileSync(result.filePaths[0], 'utf-8')

    // 格式校验
    let parsed: any
    try {
      parsed = JSON.parse(raw)
    } catch {
      throw new Error('文件格式错误：不是有效的 JSON 文件')
    }

    // 校验基本结构
    if (typeof parsed !== 'object' || parsed === null) {
      throw new Error('文件格式错误：JSON 顶层必须是对象')
    }

    // 兼容 SillyTavern 世界书格式
    const lorebook: Lorebook = {
      id: parsed.id ?? require('nanoid').nanoid(),
      name: parsed.name ?? '导入的世界书',
      description: parsed.description ?? '',
      entries: (Array.isArray(parsed.entries)
        ? parsed.entries
        : (typeof parsed.entries === 'object' && parsed.entries !== null ? Object.values(parsed.entries) : [])
      ).map((e: any, i: number) => {
        // 校验每个条目
        if (typeof e !== 'object' || e === null) return null
        return {
          id: e.uid?.toString() ?? require('nanoid').nanoid(),
          keywords: Array.isArray(e.key) ? e.key.filter((k: any) => typeof k === 'string') : (typeof e.key === 'string' ? e.key.split(',').map((s: string) => s.trim()).filter(Boolean) : []),
          content: typeof e.content === 'string' ? e.content : '',
          position: e.position === 0 || e.position === 'before' ? 'before_char'
            : e.position === 1 || e.position === 'after' ? 'after_char'
            : e.position === 2 || e.position === 'depth' || e.position === 'at_depth' ? 'at_depth'
            : 'at_end',
          depth: typeof e.depth === 'number' ? Math.max(0, e.depth) : 0,
          order: typeof e.order === 'number' ? e.order : i,
          probability: typeof e.probability === 'number' ? Math.max(0, Math.min(100, e.probability)) : 100,
          enabled: e.disable ? false : (typeof e.enabled === 'boolean' ? e.enabled : true),
        }
      }).filter(Boolean) as Lorebook['entries'],
      enabled: true,
      scanDepth: typeof parsed.scan_depth === 'number' ? Math.max(1, parsed.scan_depth) : 4,
    }

    if (lorebook.entries.length === 0) {
      throw new Error('世界书没有有效的条目')
    }

    writeJson(join(DIRS.lorebooks(), `${lorebook.id}.json`), lorebook, 'lorebooks')
    log.info('世界书已导入', { name: lorebook.name, entries: lorebook.entries.length })
    return lorebook
  })
}

/** 对比新旧条目，找出语义相关字段（内容/启用/匹配模式）变化的条目 id */
function diffSemanticEntries(prev: LoreEntry[], next: LoreEntry[]): string[] {
  const nextMap = new Map(next.map((e) => [e.id, e]))
  const changed = new Set<string>()
  for (const oldEntry of prev) {
    const newEntry = nextMap.get(oldEntry.id)
    if (!newEntry) {
      // 条目被删除：其向量自然失效
      changed.add(oldEntry.id)
      continue
    }
    if (
      oldEntry.content !== newEntry.content ||
      oldEntry.enabled !== newEntry.enabled ||
      (oldEntry.matchMode ?? 'both') !== (newEntry.matchMode ?? 'both')
    ) {
      changed.add(oldEntry.id)
    }
  }
  // 新增条目没有向量，无需标记
  return [...changed]
}

import type { IpcMain, Dialog } from 'electron'
import { join } from 'node:path'
import { DIRS, writeJson, readJson } from '../services/storage'
import { getDefaultSettings } from '../../shared/defaults'
import { saveCredential, getCredential } from '../services/safeStorage'
import { createLogger } from '../services/logger'
import { safeHandle } from '../utils/safeHandle'
import type { Settings } from '../../shared/types'

const log = createLogger('settings')

const SETTINGS_FILE = () => join(DIRS.config(), 'settings.json')

export function registerSettingsIPC(ipcMain: IpcMain, dialog: Dialog): void {
  // 读取设置
  safeHandle(ipcMain, 'settings:get', async () => {
    return readJson<Settings>(SETTINGS_FILE(), 'settings') ?? getDefaultSettings()
  })

  // 保存设置
  safeHandle(ipcMain, 'settings:save', async (_e, settings: Settings) => {
    writeJson(SETTINGS_FILE(), settings, 'settings')
    log.info('设置已保存', { activeProfileId: settings.activeProfileId || '(none)', theme: settings.theme })
  })

  // 保存凭据（加密）
  safeHandle(ipcMain, 'settings:saveCredential', async (_e, provider: string, key: string) => {
    saveCredential(provider, key)
    log.info('凭据已保存', { provider })
  })

  // 读取凭据
  safeHandle(ipcMain, 'settings:getCredential', async (_e, provider: string) => {
    return getCredential(provider)
  })

  // 导出备份
  safeHandle(ipcMain, 'settings:exportBackup', async () => {
    const result = await dialog.showSaveDialog({
      title: '导出备份',
      defaultPath: `qingyu-backup-${Date.now()}.json`,
      filters: [{ name: 'JSON 备份', extensions: ['json'] }],
    })
    if (result.canceled || !result.filePath) return

    const { readdirSync, existsSync } = require('node:fs')
    const backup: Record<string, unknown> = { version: 1, timestamp: Date.now() }

    // 备份设置
    backup.settings = readJson(SETTINGS_FILE(), 'settings')

    // 备份角色
    const charDir = DIRS.characters()
    if (existsSync(charDir)) {
      backup.characters = readdirSync(charDir)
        .filter((f: string) => f.endsWith('.json'))
        .map((f: string) => readJson(join(charDir, f)))
    }

    // 备份世界书
    const loreDir = DIRS.lorebooks()
    if (existsSync(loreDir)) {
      backup.lorebooks = readdirSync(loreDir)
        .filter((f: string) => f.endsWith('.json'))
        .map((f: string) => readJson(join(loreDir, f)))
    }

    // 备份预设
    const presetDir = DIRS.presets()
    if (existsSync(presetDir)) {
      backup.presets = readdirSync(presetDir)
        .filter((f: string) => f.endsWith('.json'))
        .map((f: string) => readJson(join(presetDir, f)))
    }

    const { writeFileSync } = require('node:fs')
    writeFileSync(result.filePath, JSON.stringify(backup, null, 2), 'utf-8')
    log.info('备份已导出', { path: result.filePath, chars: (backup.characters as any[])?.length ?? 0, lorebooks: (backup.lorebooks as any[])?.length ?? 0 })
  })

  // 导入备份
  safeHandle(ipcMain, 'settings:importBackup', async () => {
    const result = await dialog.showOpenDialog({
      title: '导入备份',
      filters: [{ name: 'JSON 备份', extensions: ['json'] }],
      properties: ['openFile'],
    })
    if (result.canceled || result.filePaths.length === 0) return

    const { readFileSync, mkdirSync } = require('node:fs')
    const backup = JSON.parse(readFileSync(result.filePaths[0], 'utf-8'))

    if (backup.settings) {
      writeJson(SETTINGS_FILE(), backup.settings)
    }
    if (backup.characters) {
      mkdirSync(DIRS.characters(), { recursive: true })
      for (const char of backup.characters) {
        writeJson(join(DIRS.characters(), `${char.id}.json`), char)
      }
    }
    if (backup.lorebooks) {
      mkdirSync(DIRS.lorebooks(), { recursive: true })
      for (const lore of backup.lorebooks) {
        writeJson(join(DIRS.lorebooks(), `${lore.id}.json`), lore)
      }
    }
    if (backup.presets) {
      mkdirSync(DIRS.presets(), { recursive: true })
      for (const preset of backup.presets) {
        writeJson(join(DIRS.presets(), `${preset.id}.json`), preset)
      }
    }
    log.info('备份已导入', { chars: backup.characters?.length ?? 0, lorebooks: backup.lorebooks?.length ?? 0, presets: backup.presets?.length ?? 0 })
  })
}

import type { IpcMain } from 'electron'
import { spawn, ChildProcessWithoutNullStreams } from 'node:child_process'
import { createLogger } from '../services/logger'

const log = createLogger('tts')

let psProcess: ChildProcessWithoutNullStreams | null = null
let speechState: 'idle' | 'speaking' | 'paused' = 'idle'
let initPromise: Promise<void> | null = null
/** 状态推送目标（最近一次调用 TTS 的窗口） */
let stateSender: Electron.WebContents | null = null

/** 推送 TTS 状态到渲染进程（系统语音完成事件等） */
function pushState(): void {
  if (stateSender && !stateSender.isDestroyed()) {
    stateSender.send('tts:state', speechState)
  }
}

/** H-06 修复：命令队列，串行化 TTS 命令 */
let commandQueue: Promise<void> = Promise.resolve()

/** PowerShell 脚本：持久进程，从 stdin 读取 JSON 命令 */
const PS_SCRIPT = `
Add-Type -AssemblyName System.Speech
$synth = New-Object System.Speech.Synthesis.SpeechSynthesizer
$synth.Rate = 0
$pendingPrompt = $null

function Handle-Command {
    param([string]$line)
    try {
        $cmd = $line | ConvertFrom-Json
        switch ($cmd.action) {
            'speak' {
                $synth.SpeakAsyncCancelAll()
                $pendingPrompt = $synth.SpeakAsync($cmd.text)
                Write-Output '{"status":"speaking"}'
            }
            'pause' {
                $synth.Pause()
                Write-Output '{"status":"paused"}'
            }
            'resume' {
                $synth.Resume()
                Write-Output '{"status":"speaking"}'
            }
            'stop' {
                $synth.SpeakAsyncCancelAll()
                $pendingPrompt = $null
                Write-Output '{"status":"idle"}'
            }
            'setVoice' {
                try { $synth.SelectVoice($cmd.voice) } catch {}
                Write-Output '{"status":"ok"}'
            }
            'setRate' {
                $synth.Rate = [int]$cmd.rate
                Write-Output '{"status":"ok"}'
            }
            'getState' {
                Write-Output ('{"status":"' + $script:speechState + '"}')
            }
            default {
                Write-Output '{"status":"unknown"}'
            }
        }
    } catch {
        Write-Output '{"status":"error","message":"$($_.Exception.Message)"}'
    }
    [Console]::Out.Flush()
}

# 监控语音完成事件
function OnSpeakCompleted {
    $script:speechState = 'idle'
    Write-Output '{"status":"completed"}'
    [Console]::Out.Flush()
}

# 注册事件
$null = Register-ObjectEvent -InputObject $synth -EventName SpeakCompleted -Action {
    $script:speechState = 'idle'
    Write-Output '{"status":"completed"}'
    [Console]::Out.Flush()
}

# 主循环：从 stdin 读取命令
while ($line = [Console]::In.ReadLine()) {
    if ($line -eq 'exit') { break }
    if ($line.Trim()) {
        $script:speechState = 'speaking'
        Handle-Command $line
    }
}

$synth.SpeakAsyncCancelAll()
$synth.Dispose()
`.trim()

/** 确保 PowerShell 进程已启动 */
async function ensureProcess(): Promise<void> {
  if (psProcess && !psProcess.killed) return
  if (initPromise) return initPromise

  initPromise = new Promise((resolve, reject) => {
    psProcess = spawn('powershell.exe', [
      '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass',
      '-Command', PS_SCRIPT,
    ], { stdio: ['pipe', 'pipe', 'pipe'] })

    let initialized = false

    // R-01 修复：init 监听器 resolve 后立即移除，防止累积泄漏
    const onInitData = () => {
      if (!initialized) {
        initialized = true
        psProcess?.stdout?.off('data', onInitData)
        resolve()
      }
    }
    psProcess.stdout?.on('data', onInitData)

    // 持久监听：消费系统语音的完成/错误事件（命令响应由 sendCommand 单独处理）
    psProcess.stdout?.on('data', (data) => {
      const text = data.toString().trim()
      if (!text) return
      try {
        const parsed = JSON.parse(text)
        if (parsed.status === 'completed' || parsed.status === 'error') {
          speechState = 'idle'
          pushState()
        }
      } catch { /* 忽略非 JSON 输出 */ }
    })

    psProcess.on('error', (err) => {
      initPromise = null
      reject(err)
    })

    psProcess.on('exit', () => {
      psProcess = null
      speechState = 'idle'
      initPromise = null
    })

    // 超时保护
    setTimeout(() => {
      if (!initialized) {
        initialized = true
        psProcess?.stdout?.off('data', onInitData)
        resolve() // 即使没收到输出也继续
      }
    }, 3000)
  })

  return initPromise
}

/** 发送命令到 PowerShell 进程（H-06 修复：通过队列串行化，避免竞态） */
function sendCommand(cmd: object): Promise<any> {
  const task = commandQueue.then(async () => {
    await ensureProcess()
    if (!psProcess || !psProcess.stdin || !psProcess.stdout) {
      throw new Error('PowerShell 进程未就绪')
    }

    const cmdStr = JSON.stringify(cmd)
    return new Promise<any>((resolve) => {
      const onData = (data: Buffer) => {
        const text = data.toString().trim()
        if (!text) return
        try {
          const result = JSON.parse(text)
          psProcess?.stdout?.off('data', onData)
          if (result.status === 'speaking') speechState = 'speaking'
          else if (result.status === 'paused') speechState = 'paused'
          else if (result.status === 'idle' || result.status === 'completed') speechState = 'idle'
          resolve(result)
        } catch {
          // 非 JSON 输出，忽略
        }
      }

      psProcess.stdout.on('data', onData)
      psProcess.stdin.write(cmdStr + '\n')

      // 超时
      setTimeout(() => {
        psProcess?.stdout?.off('data', onData)
        resolve({ status: 'timeout' })
      }, 10000)
    })
  })

  // 更新队列（捕获错误防止队列卡死）
  commandQueue = task.then(() => {}, () => {})
  return task
}

/** 获取系统语音列表 */
async function getVoices(): Promise<{ id: string; name: string; lang: string }[]> {
  return new Promise((resolve) => {
    const proc = spawn('powershell.exe', [
      '-NoProfile', '-NonInteractive', '-Command',
      `Add-Type -AssemblyName System.Speech;
       $synth = New-Object System.Speech.Synthesis.SpeechSynthesizer;
       $synth.GetInstalledVoices() | ForEach-Object { 
         $info = $_.VoiceInfo;
         Write-Output ($info.Id + '|' + $info.Name + '|' + $info.Culture.Name)
       }`,
    ], { stdio: ['pipe', 'pipe', 'pipe'] })

    let output = ''
    proc.stdout?.on('data', (data) => { output += data.toString() })
    proc.on('exit', () => {
      const voices = output.trim().split('\n')
        .filter((l) => l.trim())
        .map((line) => {
          const [id, name, lang] = line.trim().split('|')
          return { id: id || name, name: name || id, lang: lang || 'zh-CN' }
        })
      resolve(voices)
    })
    proc.on('error', () => resolve([]))
  })
}

/** 杀死 TTS PowerShell 进程（应用退出时调用） */
export function killTTS(): void {
  if (psProcess && !psProcess.killed) {
    try {
      psProcess.stdin.write('exit\n')
      psProcess.kill()
    } catch { /* ignore */ }
    psProcess = null
    speechState = 'idle'
    initPromise = null
  }
}

