app.whenReady().then(async () => {
  // 移除默认菜单栏（帮助、窗口等）
  Menu.setApplicationMenu(null)
  // 显式设置应用名称（控制左上角标题栏显示）
  app.setName('轻语')

  await ensureDataDir()

  // 注册 tavern:// 协议处理器：角色图片直接从磁盘按需加载，不经 base64/IPC
  const charDir = DIRS.characters()
  _ele.protocol.handle('tavern', (request) => {
    const url = new URL(request.url)
    if (url.hostname !== 'character') {
      return new Response('Not found', { status: 404 })
    }
    const parts = url.pathname.split('/').filter(Boolean)
    if (parts.length !== 2) return new Response('Bad request', { status: 400 })
    const [id, kind] = parts
    // 路径穿越防护：只允许字母、数字、下划线、短横线
    if (!/^[a-zA-Z0-9_-]+$/.test(id)) return new Response('Forbidden', { status: 403 })
    if (kind !== 'avatar' && kind !== 'cover') return new Response('Bad request', { status: 400 })

    const mimeTypes: Record<string, string> = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp' }
    const extensions = ['png', 'jpg', 'jpeg', 'gif', 'webp']
    // cover 请求先找 _cover 文件，找不到回退到 avatar 文件（与原 cover||avatar 逻辑一致）
    const suffixes = kind === 'cover' ? ['_cover', ''] : ['']
    for (const suffix of suffixes) {
      for (const ext of extensions) {
        const filePath = join(charDir, `${id}${suffix}.${ext}`)
        if (existsSync(filePath)) {
          return new Response(new Uint8Array(readFileSync(filePath)), { headers: { 'Content-Type': mimeTypes[ext] || 'application/octet-stream' } })
        }
      }
    }
    return new Response('Not found', { status: 404 })
  })

  initLogger(app.getPath('userData'))

  const appLogger = createLogger('main')
  appLogger.info('轻语启动', { version: app.getVersion(), isDev })

  // 拦截 ipcMain.handle，统一捕获所有 IPC 处理器异常并记录（不吞错误，仍向渲染进程抛出）
  const _originalHandle = ipcMain.handle.bind(ipcMain)
  ipcMain.handle = ((channel: string, handler: (event: Electron.IpcMainInvokeEvent, ...args: unknown[]) => unknown) => {
    return _originalHandle(channel, async (event, ...args) => {
      try {
        return await handler(event, ...args)
      } catch (err) {
        const ipcLogger = createLogger('ipc')
        const errMsg = err instanceof Error ? err.message : String(err)
        const errStack = err instanceof Error ? err.stack?.split('\n').slice(0, 5).join(' | ') : undefined
        ipcLogger.error(`IPC ${channel} 异常`, { error: errMsg, ...(errStack ? { stack: errStack } : {}) })
        throw err
      }
    })
  }) as typeof ipcMain.handle

  // 注册所有 IPC 处理器
  registerCharacterIPC(ipcMain, dialog)
  registerChatIPC(ipcMain)
  registerSettingsIPC(ipcMain, dialog)
  registerLorebookIPC(ipcMain, dialog)
  registerEmbeddingIPC(ipcMain)
  registerQuickReplyIPC(ipcMain, dialog)
  registerPresetIPC(ipcMain, dialog)
  registerAIIPC(ipcMain)
  registerTTSIPC(ipcMain)
  registerImageGenIPC(ipcMain)
  registerFileIPC(ipcMain, dialog, app)
  registerRegexIPC(ipcMain)
  registerPersonaIPC(ipcMain)
  registerUsageIPC(ipcMain)
  registerMcpIPC(ipcMain)
  registerGroupIPC(ipcMain)
  registerAnnouncementIPC(ipcMain)

  // 应用版本号
  ipcMain.handle('app:getVersion', () => app.getVersion())

  // 打开外部链接（仅允许 http/https）
  ipcMain.handle('app:openExternal', (_e, url: string) => {
    if (/^https?:\/\//.test(url)) {
      return shell.openExternal(url)
    }
    throw new Error('仅支持 http/https 链接')
  })

  // 自动启动配置为 autoStart 的 MCP server
  const logger = createLogger('main')
  mcpManager.autoStartAll().catch((err) => {
    logger.error('MCP 自动启动失败', { error: err.message })
  })

  // 日志 IPC
  ipcMain.handle('log:write', (_event, level: 'debug' | 'info' | 'warn' | 'error', mod: string, message: string, meta?: Record<string, unknown>) => {
    const logger = createLogger(mod)
    logger[level](message, meta)
  })
  ipcMain.handle('log:getRecent', (_event, limit?: number) => {
    return getRecentLogs(limit || 200)
  })

  createWindow()

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow()
  })
})

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit()
})

// L-04 修复：应用退出前关闭所有 MCP server + TTS 进程，等待 pending IPC 写入完成
let isQuitting = false
app.on('before-quit', async (event) => {
  if (isQuitting) return
  isQuitting = true
  event.preventDefault()
  killTTS()
  try {
    await Promise.race([
      mcpManager.shutdownAll(),
      new Promise((_, reject) => setTimeout(() => reject(new Error('shutdown timeout')), 3000)),
    ])
  } catch { /* ignore */ }
  // 等待 pending IPC 调用（如翻译 saveMessage）完成
  await new Promise(resolve => setTimeout(resolve, 500))
  app.exit(0)
})

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars */
import type { AIAdapter } from './types'
import { normalizeThoughtTags } from './types'
import { sanitizeApiKey } from '../../utils/pathGuard'

export const claudeAdapter: AIAdapter = {
  async chat(params, onChunk, signal, onUsage) {
    const { baseUrl, apiKey, model, messages, temperature, topP, maxTokens, stream } = params
    const url = `${baseUrl.replace(/\/$/, '')}/v1/messages`

    // Claude 要求 system 单独传
    const systemMsg = messages.find((m) => m.role === 'system')
    const chatMessages = messages.filter((m) => m.role !== 'system')

    const body: Record<string, unknown> = {
      model,
      max_tokens: maxTokens || 4096,
      temperature,
      top_p: topP,
      messages: chatMessages,
      stream,
    }
    if (systemMsg) body.system = systemMsg.content

    // C-03 修复：转换 OpenAI 格式 tools 为 Claude 格式
    if (params.tools && params.tools.length > 0) {
      body.tools = params.tools.map(t => ({
        name: t.function.name,
        description: t.function.description,
        input_schema: t.function.parameters,
      }))
      // tool_choice 转换
      if (params.toolChoice) {
        if (typeof params.toolChoice === 'string') {
          body.tool_choice = params.toolChoice === 'required' ? { type: 'any' } : { type: 'auto' }
        } else {
          body.tool_choice = { type: 'tool', name: params.toolChoice.function?.name || '' }
        }
      }
    }

    // Claude 3.7 / Claude 4 扩展思考支持
    const lowerModel = model.toLowerCase()
    if ((lowerModel.includes('claude-3-7') || lowerModel.includes('claude-4') ||
         lowerModel.includes('claude-3.7')) && !lowerModel.includes('haiku')) {
      // 思考预算为 max_tokens 的 1/3，最低 1024
      const thinkingBudget = Math.max(1024, Math.floor((maxTokens || 4096) / 3))
      body.thinking = { type: 'enabled', budget_tokens: thinkingBudget }
      // 启用思考时 temperature 必须为 1
      body.temperature = 1
    }

    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        // API 版本（可定期更新）
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true',
      },
      body: JSON.stringify(body),
      signal,
    })

    if (!response.ok) {
      const errText = await response.text()
      throw new Error(`Claude API 错误 ${response.status}: ${sanitizeApiKey(errText)}`)
    }

    if (!stream) {
      const data: any = await response.json()
      // Claude 返回 content 数组，可能有 thinking / text / tool_use 三种类型
      const parts = data.content ?? []
      let thinking = ''
      let text = ''
      const rawToolCalls: any[] = []
      for (const part of parts) {
        if (part.type === 'thinking') thinking += part.thinking
        else if (part.type === 'text') text += part.text
        else if (part.type === 'tool_use') {
          rawToolCalls.push({
            id: part.id,
            type: 'function',
            function: { name: part.name, arguments: JSON.stringify(part.input) },
          })
        }
      }
      const content = thinking ? `<thought>${thinking}</thought>\n\n${text}` : text
      onChunk(content)
      if (onUsage && data.usage) {
        onUsage({
          promptTokens: data.usage.input_tokens ?? 0,
          completionTokens: data.usage.output_tokens ?? 0,
          totalTokens: (data.usage.input_tokens ?? 0) + (data.usage.output_tokens ?? 0),
        })
      }
      // C-03 修复：如有 tool_use，附加标记供 toolLoop 解析
      if (rawToolCalls.length > 0) {
        return normalizeThoughtTags(content) + '[TOOL_CALL:' + JSON.stringify(rawToolCalls) + ']'
      }
      return normalizeThoughtTags(content)
    }

    const reader = response.body?.getReader()
    if (!reader) throw new Error('无法读取响应流')
    const decoder = new TextDecoder()
    let fullText = ''
    let buffer = ''
    let pendingThought = ''
    let claudeInputTokens = 0
    let claudeOutputTokens = 0
    // C-03 修复：收集流式 tool_use delta
    const streamedToolCalls = new Map<number, { id: string; type: string; function: { name: string; arguments: string } }>()

    try {
    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      buffer += decoder.decode(value, { stream: true })
      const lines = buffer.split('\n')
      buffer = lines.pop() ?? ''

      for (const line of lines) {
        const trimmed = line.trim()
        if (!trimmed.startsWith('data:')) continue
        const data = trimmed.slice(5).trim()
        if (!data) continue
        try {
          const parsed = JSON.parse(data)
          // message_start 事件含 input_tokens
          if (parsed.type === 'message_start' && parsed.message?.usage) {
            claudeInputTokens = parsed.message.usage.input_tokens ?? 0
          }
          // thinking / tool_use 块开始
          else if (parsed.type === 'content_block_start') {
            if (parsed.content_block?.type === 'thinking') {
              pendingThought = '<thought>'
            } else if (parsed.content_block?.type === 'tool_use') {
              const idx = parsed.index ?? 0
              streamedToolCalls.set(idx, {
                id: parsed.content_block.id || '',
                type: 'function',
                function: { name: parsed.content_block.name || '', arguments: '' },
              })
            }
          } else if (parsed.type === 'content_block_delta') {
            // thinking delta
            if (parsed.delta?.type === 'thinking_delta' && parsed.delta.thinking) {
              pendingThought += parsed.delta.thinking
            }
            // 文本 delta
            else if (parsed.delta?.type === 'text_delta' && parsed.delta.text) {
              if (pendingThought) {
                pendingThought += '</thought>\n\n'
                fullText += pendingThought
                onChunk(pendingThought)
                pendingThought = ''
              }
              fullText += parsed.delta.text
              onChunk(parsed.delta.text)
            }
            // C-03 修复：tool_use input_json delta
            else if (parsed.delta?.type === 'input_json_delta' && parsed.delta.partial_json) {
              const idx = parsed.index ?? 0
              const existing = streamedToolCalls.get(idx)
              if (existing) existing.function.arguments += parsed.delta.partial_json
            }
          } else if (parsed.type === 'content_block_stop' && pendingThought) {
            pendingThought += '</thought>\n\n'
            fullText += pendingThought
            onChunk(pendingThought)
            pendingThought = ''
          }
          // message_delta 事件含 output_tokens，是最后一个事件
          else if (parsed.type === 'message_delta' && parsed.usage) {
            claudeOutputTokens = parsed.usage.output_tokens ?? 0
            if (onUsage) {
              onUsage({
                promptTokens: claudeInputTokens,
                completionTokens: claudeOutputTokens,
                totalTokens: claudeInputTokens + claudeOutputTokens,
              })
            }
          }
        } catch {
          // 忽略
        }
      }
    }
    // 处理剩余 pending
    if (pendingThought) {
      pendingThought += '</thought>\n\n'
      fullText += pendingThought
      onChunk(pendingThought)
    }
    } finally {
      try { reader.releaseLock() } catch { /* ignore */ }
    }
    // C-03 修复：如有 tool_use，附加标记供 toolLoop 解析
    if (streamedToolCalls.size > 0) {
      const toolCallsArray = Array.from(streamedToolCalls.values())
      return normalizeThoughtTags(fullText) + '[TOOL_CALL:' + JSON.stringify(toolCallsArray) + ']'
    }
    return normalizeThoughtTags(fullText)
  },

  async listModels(baseUrl, apiKey) {
    const url = `${baseUrl.replace(/\/$/, '')}/v1/models`
    const response = await fetch(url, {
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
      },
    })
    if (!response.ok) throw new Error(`获取模型列表失败: ${response.status}`)
    const data: any = await response.json()
    return (data.data ?? []).map((m: { id: string }) => m.id)
  },

  async testConnection(baseUrl, apiKey) {
    try {
      await this.listModels(baseUrl, apiKey)
      return true
    } catch {
      return false
    }
  },
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars */
import type { AIAdapter } from './types'
import { normalizeThoughtTags } from './types'
import { sanitizeApiKey } from '../../utils/pathGuard'

export const openaiAdapter: AIAdapter = {
  async chat(params, onChunk, signal, onUsage) {
    const { baseUrl, apiKey, model, messages, temperature, topP, maxTokens,
            frequencyPenalty, presencePenalty, stream } = params
    const url = `${baseUrl.replace(/\/$/, '')}/chat/completions`

    const body: Record<string, unknown> = {
      model,
      messages,
      temperature,
      top_p: topP,
      max_tokens: maxTokens,
      frequency_penalty: frequencyPenalty,
      presence_penalty: presencePenalty,
      stream,
    }

    // C-03 修复：传递工具定义给 API
    if (params.tools && params.tools.length > 0) {
      body.tools = params.tools
      if (params.toolChoice) body.tool_choice = params.toolChoice
    }

    // L-01 修复：推理模型支持 — 用词边界正则避免误匹配（如 gpt-3.5-turbo-1106 含 "o1"）
    const lowerModel = model.toLowerCase()
    if (/\bo[134](?:-mini)?\b/.test(lowerModel) || lowerModel.includes('deepseek-r1')) {
      // OpenAI o 系列不支持 temperature/top_p 等参数
      delete body.temperature
      delete body.top_p
      delete body.frequency_penalty
      delete body.presence_penalty
      body.reasoning_effort = 'medium'
    }

    // 流式请求时请求 usage 信息
    if (stream) {
      body.stream_options = { include_usage: true }
    }

    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify(body),
      signal,
    })

    if (!response.ok) {
      const errText = await response.text()
      throw new Error(`OpenAI API 错误 ${response.status}: ${sanitizeApiKey(errText)}`)
    }

    if (!stream) {
      const data: any = await response.json()
      const content = data.choices?.[0]?.message?.content ?? ''
      // 处理推理模型的 reasoning_content（DeepSeek-R1 等）
      const reasoning = data.choices?.[0]?.message?.reasoning_content
      let fullContent = reasoning ? `<thought>${reasoning}</thought>\n\n${content}` : content
      // B-05 修复：归一化内容中可能含有的 <thinking> 标签
      fullContent = normalizeThoughtTags(fullContent)
      onChunk(fullContent)
      // 解析 usage
      if (onUsage && data.usage) {
        onUsage({
          promptTokens: data.usage.prompt_tokens ?? 0,
          completionTokens: data.usage.completion_tokens ?? 0,
          totalTokens: data.usage.total_tokens ?? 0,
        })
      }
      // C-03 修复：检测 tool_calls 并附加标记供 toolLoop 解析
      const toolCalls = data.choices?.[0]?.message?.tool_calls
      if (toolCalls && toolCalls.length > 0) {
        return fullContent + '[TOOL_CALL:' + JSON.stringify(toolCalls) + ']'
      }
      return fullContent
    }

    // 流式解析（修复 SSE 分隔符：使用更稳健的行解析）
    const reader = response.body?.getReader()
    if (!reader) throw new Error('无法读取响应流')
    const decoder = new TextDecoder()
    let fullText = ''
    let buffer = ''
    let pendingReasoning = ''
    // C-03 修复：收集流式 tool_calls delta
    const streamedToolCalls = new Map<number, { id: string; type: string; function: { name: string; arguments: string } }>()

    try {
    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      buffer += decoder.decode(value, { stream: true })
      // SSE 事件以 \n\n 分隔，但兼容只用 \n 的服务器
      // 按行解析，处理跨 chunk 的 data: 行
      const lines = buffer.split('\n')
      buffer = lines.pop() ?? ''

      for (const line of lines) {
        const trimmed = line.trim()
        if (!trimmed) continue
        if (!trimmed.startsWith('data:')) continue
        const data = trimmed.slice(5).trim()
        if (data === '[DONE]') continue
        try {
          const parsed = JSON.parse(data)
          // 解析 usage（最后 chunk）
          if (parsed.usage && onUsage) {
            onUsage({
              promptTokens: parsed.usage.prompt_tokens ?? 0,
              completionTokens: parsed.usage.completion_tokens ?? 0,
              totalTokens: parsed.usage.total_tokens ?? 0,
            })
          }
          const delta = parsed.choices?.[0]?.delta
          if (!delta) continue

          // 处理推理内容（DeepSeek-R1, Qwen-QwQ 等）
          if (delta.reasoning_content) {
            if (!pendingReasoning) {
              pendingReasoning = '<thought>'
            }
            pendingReasoning += delta.reasoning_content
          }

          // 正常内容
          if (delta.content) {
            // 如果之前有推理内容未闭合，先闭合
            if (pendingReasoning) {
              pendingReasoning += '</thought>\n\n'
              fullText += pendingReasoning
              onChunk(pendingReasoning)
              pendingReasoning = ''
            }
            fullText += delta.content
            onChunk(delta.content)
          }

          // C-03 修复：收集流式 tool_calls delta
          if (delta.tool_calls) {
            for (const tc of delta.tool_calls) {
              const idx = tc.index ?? 0
              if (!streamedToolCalls.has(idx)) {
                streamedToolCalls.set(idx, { id: tc.id || '', type: 'function', function: { name: '', arguments: '' } })
              }
              const existing = streamedToolCalls.get(idx)!
              if (tc.id) existing.id = tc.id
              if (tc.function?.name) existing.function.name += tc.function.name
              if (tc.function?.arguments) existing.function.arguments += tc.function.arguments
            }
          }
        } catch {
          // 忽略解析错误（可能是注释行或心跳）
        }
      }
    }

    // 处理流结束时仍 pending 的推理内容
    if (pendingReasoning) {
      pendingReasoning += '</thought>\n\n'
      fullText += pendingReasoning
      onChunk(pendingReasoning)
    }
    } finally {
      try { reader.releaseLock() } catch { /* ignore */ }
    }

    // C-03 修复：如有 tool_calls，附加标记供 toolLoop 解析
    if (streamedToolCalls.size > 0) {
      const toolCallsArray = Array.from(streamedToolCalls.values())
      return normalizeThoughtTags(fullText) + '[TOOL_CALL:' + JSON.stringify(toolCallsArray) + ']'
    }
    return normalizeThoughtTags(fullText)
  },

  async listModels(baseUrl, apiKey) {
    const url = `${baseUrl.replace(/\/$/, '')}/models`
    const response = await fetch(url, {
      headers: { Authorization: `Bearer ${apiKey}` },
    })
    if (!response.ok) throw new Error(`获取模型列表失败: ${response.status}`)
    const data: any = await response.json()
    return (data.data ?? []).map((m: { id: string }) => m.id)
  },

  async testConnection(baseUrl, apiKey) {
    try {
      await this.listModels(baseUrl, apiKey)
      return true
    } catch {
      return false
    }
  },
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars */
import type { ChatParams, ProviderType } from '../../../shared/types'

/** B-05 修复：归一化思考标签，将 <thinking> 转为 <thought>（兼容部分模型原生的 thinking 标签） */
export function normalizeThoughtTags(text: string): string {
  if (!text) return text
  return text.replace(/<thinking([\s>])/gi, '<thought$1').replace(/<\/thinking>/gi, '</thought>')
}

/** 默认请求超时时间（毫秒）- 5 分钟 */
export const DEFAULT_TIMEOUT_MS = 5 * 60 * 1000

/** 默认重试次数 */
export const DEFAULT_RETRY_COUNT = 1

/** 可重试的 HTTP 状态码 */
export const RETRYABLE_STATUS = new Set([408, 429, 500, 502, 503, 504])

export interface AIAdapter {
  chat(
    params: ChatParams,
    onChunk: (text: string) => void,
    signal: AbortSignal,
    onUsage?: (usage: { promptTokens: number; completionTokens: number; totalTokens: number }) => void,
  ): Promise<string>
  listModels(baseUrl: string, apiKey: string): Promise<string[]>
  testConnection(baseUrl: string, apiKey: string): Promise<boolean>
}

/** Token 用量信息 */
export interface TokenUsageInfo {
  promptTokens: number
  completionTokens: number
  totalTokens: number
}

// ===================== 工具函数 =====================

/** 合并用户 signal 与超时 signal */
export function withTimeout(signal: AbortSignal, timeoutMs: number): AbortSignal {
  // 如果用户 signal 已经 abort，直接返回
  if (signal.aborted) return signal
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(new Error('timeout')), timeoutMs)
  // 用户取消时同步取消
  signal.addEventListener('abort', () => {
    clearTimeout(timer)
    controller.abort(signal.reason)
  }, { once: true })
  // 超时后取消
  controller.signal.addEventListener('abort', () => {
    clearTimeout(timer)
  }, { once: true })
  return controller.signal
}

/** 判断错误是否可重试 */
export function isRetryableError(err: unknown): boolean {
  if (err instanceof Error) {
    const msg = err.message.toLowerCase()
    // 网络错误、超时、5xx、429 都可重试
    if (msg.includes('timeout') || msg.includes('aborted')) return true
    if (msg.includes('network') || msg.includes('fetch failed')) return true
    if (msg.includes('econnrefused') || msg.includes('econnreset')) return true
    for (const code of RETRYABLE_STATUS) {
      if (msg.includes(`${code}`)) return true
    }
  }
  return false
}

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, unlinkSync } from 'node:fs'
import { join } from 'node:path'
import http from 'node:http'
import https from 'node:https'
import { DIRS, writeJson, readJson, readJsonAsync } from './storage'
import type { Character, Lorebook, LoreEntry, RegexRule, QuickReply, QuickReplyStore } from '../../shared/types'
import { createLogger } from './logger'
import { nanoid } from 'nanoid'

const log = createLogger('charCard')

/** 全局 keep-alive Agent — 复用 TCP/TLS 连接，避免每次下载都重新握手 */
const httpKeepAliveAgent = new http.Agent({
  keepAlive: true,
  keepAliveMsecs: 30000,      // 空闲连接保留 30 秒
  maxSockets: 10,             // 每个 host 最多 10 个并发连接
  maxFreeSockets: 5,          // 空闲时保留 5 个
  timeout: 30000,             // socket 超时
})

const httpsKeepAliveAgent = new https.Agent({
  keepAlive: true,
  keepAliveMsecs: 30000,
  maxSockets: 10,
  maxFreeSockets: 5,
  timeout: 30000,
})

/** PNG 签名 */
const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])

/** 检测图片类型并返回正确的 MIME */
function detectMimeType(buffer: Buffer): string {
  // PNG
  if (buffer.length >= 8 && buffer.subarray(0, 8).equals(PNG_SIGNATURE)) {
    return 'image/png'
  }
  // JPEG: FF D8 FF
  if (buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
    return 'image/jpeg'
  }
  // GIF: 47 49 46 38
  if (buffer.length >= 6 && buffer.subarray(0, 4).toString('ascii') === 'GIF8') {
    return 'image/gif'
  }
  // WebP: 52 49 46 46 ... 57 45 42 50
  if (buffer.length >= 12 && buffer.subarray(0, 4).toString('ascii') === 'RIFF' && buffer.subarray(8, 12).toString('ascii') === 'WEBP') {
    return 'image/webp'
  }
  return 'image/png' // 默认
}

/** PNG tEXt chunk 读取 */
function readPngTextChunks(buffer: Buffer): Record<string, string> {
  const chunks: Record<string, string> = {}
  // PNG 签名校验：必须用 Buffer.equals，不能用 toString('ascii')
  // 因为 toString('ascii') 会把 0x89 截断为 0x09，导致签名永远不匹配
  if (buffer.length < 8 || !buffer.subarray(0, 8).equals(PNG_SIGNATURE)) {
    return chunks
  }
  let offset = 8
  while (offset < buffer.length) {
    const length = buffer.readUInt32BE(offset)
    const type = buffer.toString('ascii', offset + 4, offset + 8)
    const dataStart = offset + 8
    const data = buffer.subarray(dataStart, dataStart + length)
    if (type === 'tEXt') {
      const nullIdx = data.indexOf(0)
      if (nullIdx > 0) {
        const key = data.toString('ascii', 0, nullIdx)
        const value = data.toString('utf-8', nullIdx + 1)
        chunks[key] = value
      }
    } else if (type === 'iTXt') {
      // iTXt 格式: keyword\0  compression_flag(1)  compression_method(1)  language\0  translated\0  text
      const nullIdx = data.indexOf(0)
      if (nullIdx > 0) {
        const key = data.toString('ascii', 0, nullIdx)
        // 跳过 compression_flag(1) + compression_method(1)
        let pos = nullIdx + 3
        const langEnd = data.indexOf(0, pos)
        if (langEnd < 0) continue
        pos = langEnd + 1
        const transEnd = data.indexOf(0, pos)
        if (transEnd < 0) continue
        const textStart = transEnd + 1
        if (textStart < data.length) {
          const value = data.toString('utf-8', textStart)
          chunks[key] = value
        }
      }
    } else if (type === 'IEND') {
      break
    }
    offset = dataStart + length + 4
  }
  return chunks
}

/** 向 PNG 写入 tEXt chunk */
function writePngTextChunk(buffer: Buffer, key: string, value: string): Buffer {
  const keyBytes = Buffer.from(key, 'ascii')
  const valueBytes = Buffer.from(value, 'utf-8')
  const nullByte = Buffer.from([0])
  const chunkData = Buffer.concat([keyBytes, nullByte, valueBytes])
  const typeBytes = Buffer.from('tEXt', 'ascii')
  const lengthBytes = Buffer.alloc(4)
  lengthBytes.writeUInt32BE(chunkData.length, 0)

  const crcData = Buffer.concat([typeBytes, chunkData])
  const crc = crc32(crcData)
  const crcBytes = Buffer.alloc(4)
  crcBytes.writeUInt32BE(crc >>> 0, 0)

  const iendOffset = findIENDOffset(buffer)
  if (iendOffset < 0) return buffer
  const before = buffer.subarray(0, iendOffset)
  const after = buffer.subarray(iendOffset)
  return Buffer.concat([before, lengthBytes, typeBytes, chunkData, crcBytes, after])
}

function findIENDOffset(buffer: Buffer): number {
  for (let i = buffer.length - 12; i >= 8; i--) {
    if (buffer.toString('ascii', i + 4, i + 8) === 'IEND') {
      return i
    }
  }
  return -1
}

const crcTable: number[] = []
for (let n = 0; n < 256; n++) {
  let c = n
  for (let k = 0; k < 8; k++) {
    c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1
  }
  crcTable[n] = c
}

function crc32(buf: Buffer): number {
  let crc = 0xffffffff
  for (let i = 0; i < buf.length; i++) {
    crc = crcTable[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8)
  }
  return crc ^ 0xffffffff
}

/** 从 PNG 文件导入角色卡 */
export async function importCharacterFromPng(filePath: string, proxyUrl?: string): Promise<Character> {
  const buffer = readFileSync(filePath)
  const chunks = readPngTextChunks(buffer)
  // 优先读取 v2 的 chara 字段，fallback 到 v3 的 ccv3 字段
  const charaBase64 = chunks['chara'] || chunks['ccv3']
  if (!charaBase64) {
    throw new Error('该 PNG 文件不包含角色卡数据（未找到 chara 或 ccv3 字段）')
  }

  let charaJson: string
  try {
    charaJson = Buffer.from(charaBase64, 'base64').toString('utf-8')
  } catch {
    throw new Error('角色卡 base64 解码失败')
  }

  const parsed = JSON.parse(charaJson)
  // 头像直接用 PNG 文件的 base64
  const avatarBase64 = `data:image/png;base64,${buffer.toString('base64')}`
  const character = await normalizeCharacter(parsed, avatarBase64, proxyUrl)
  log.info('PNG 角色卡导入成功', { name: character.name, path: filePath.substring(0, 80) })
  return character
}

/** 从 JSON 文件导入角色卡 */
export async function importCharacterFromJson(filePath: string, proxyUrl?: string): Promise<Character> {
  const raw = readFileSync(filePath, 'utf-8')
  const parsed = JSON.parse(raw)

  // 检测 SillyTavern 世界书格式：有 entries + scan_depth 且无 spec/data 包装
  if (
    parsed.entries &&
    (Array.isArray(parsed.entries) ? parsed.entries.length > 0 : Object.keys(parsed.entries).length > 0) &&
    typeof parsed.scan_depth === 'number' &&
    !parsed.spec &&
    !parsed.data
  ) {
    const entryCount = Array.isArray(parsed.entries) ? parsed.entries.length : Object.keys(parsed.entries).length
    throw new Error(
      `这个文件是世界书（Lorebook），包含 ${entryCount} 条条目，不是角色卡。\n请在世界书页面使用"导入 JSON"功能导入。`
    )
  }

  const character = await normalizeCharacter(parsed, undefined, proxyUrl)
  log.info('JSON 角色卡导入成功', { name: character.name, path: filePath.substring(0, 80), hasAvatar: !!character.avatar })
  return character
}

/** 图片下载错误码 */
export type ImageDownloadCode = 'TIMEOUT' | 'HTTP_ERROR' | 'NETWORK_ERROR' | 'INVALID_URL' | 'INVALID_FORMAT' | 'SSRF_BLOCKED' | 'UNKNOWN'

/** 图片下载结果 */
export interface DownloadResult {
  success: boolean
  data?: string
  error?: string
  code?: ImageDownloadCode
  statusCode?: number
}

/** 下载超时时间（毫秒）- 大图片（如 2MB+）需要足够时间 */
const DOWNLOAD_TIMEOUT_MS = 30000

/** 解析代理 URL */
function parseProxyUrl(proxyUrl: string): { host: string; port: number } | null {
  try {
    const u = new URL(proxyUrl)
    if (!u.hostname || !u.port) return null
    return { host: u.hostname, port: parseInt(u.port, 10) }
  } catch {
    return null
  }
}

/** 单次下载尝试（内部函数），可通过代理或直连 */
function _downloadOne(url: string, proxy: { host: string; port: number } | null, maxRedirects: number): Promise<DownloadResult> {
  const trimmed = url.trim()
  const isHttps = trimmed.startsWith('https')
  const targetUrl = new URL(trimmed)

  return new Promise((resolve) => {
    let settled = false
    let req: any = null

    const safeResolve = (result: DownloadResult) => {
      if (settled) return
      settled = true
      clearTimeout(timeout)
      resolve(result)
    }

    const timeout = setTimeout(() => {
      log.warn('封面下载超时', { url: trimmed.substring(0, 100), timeoutMs: DOWNLOAD_TIMEOUT_MS, viaProxy: !!proxy })
      if (req) {
        try { req.destroy() } catch { /* ignore */ }
      }
      safeResolve({ success: false, error: '下载超时，请检查网络连接', code: 'TIMEOUT' })
    }, DOWNLOAD_TIMEOUT_MS)

    try {
      if (proxy) {
        // ===== 通过代理下载 =====
        const connectOpts: any = {
          host: proxy.host,
          port: proxy.port,
          method: 'CONNECT',
          path: `${targetUrl.hostname}:${targetUrl.port || (isHttps ? 443 : 80)}`,
          headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
          timeout: DOWNLOAD_TIMEOUT_MS,
        }

        log.debug('通过代理连接', { proxy: `${proxy.host}:${proxy.port}`, target: `${targetUrl.hostname}:${targetUrl.port || (isHttps ? 443 : 80)}` })

        req = http.request(connectOpts)
        req.on('connect', (_res: any, socket: any) => {
          if (_res.statusCode !== 200) {
            log.warn('代理 CONNECT 失败', { statusCode: _res.statusCode })
            safeResolve({ success: false, error: `代理连接失败: HTTP ${_res.statusCode}`, code: 'NETWORK_ERROR' })
            return
          }

          if (isHttps) {
            const httpsReq = https.request({
              host: targetUrl.hostname,
              port: targetUrl.port || 443,
              path: targetUrl.pathname + targetUrl.search,
              method: 'GET',
              headers: {
                'Host': targetUrl.hostname,
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept': 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8',
                'Accept-Language': 'en-US,en;q=0.9,zh-CN;q=0.8,zh;q=0.7',
              },
              socket,
              agent: false,
              timeout: DOWNLOAD_TIMEOUT_MS,
            }, handleResponse)
            httpsReq.on('error', (err: Error) => {
              if (settled) return
              log.warn('代理 HTTPS 请求失败', { error: err.message })
              safeResolve({ success: false, error: `代理请求失败: ${err.message}`, code: 'NETWORK_ERROR' })
            })
            httpsReq.end()
          } else {
            const httpReq = http.request({
              host: proxy.host,
              port: proxy.port,
              path: trimmed,
              method: 'GET',
              headers: {
                'Host': targetUrl.hostname,
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept': 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8',
                'Accept-Language': 'en-US,en;q=0.9,zh-CN;q=0.8,zh;q=0.7',
              },
              socket,
              agent: false,
              timeout: DOWNLOAD_TIMEOUT_MS,
            }, handleResponse)
            httpReq.on('error', (err: Error) => {
              if (settled) return
              log.warn('代理 HTTP 请求失败', { error: err.message })
              safeResolve({ success: false, error: `代理请求失败: ${err.message}`, code: 'NETWORK_ERROR' })
            })
            httpReq.end()
          }
        })
        req.on('error', (err: Error) => {
          if (settled) return
          log.warn('代理连接失败', { proxy: `${proxy.host}:${proxy.port}`, error: err.message })
          safeResolve({ success: false, error: `代理连接失败: ${err.message}`, code: 'NETWORK_ERROR' })
        })
        req.end()
      } else {
        // ===== 直连下载 =====
        const getter = isHttps ? https : http
        req = getter.get(trimmed, {
          headers: {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
            'Accept': 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8',
            'Accept-Language': 'en-US,en;q=0.9,zh-CN;q=0.8,zh;q=0.7',
          },
          timeout: DOWNLOAD_TIMEOUT_MS,
          agent: isHttps ? httpsKeepAliveAgent : httpKeepAliveAgent,
        }, handleResponse).on('error', (err: Error) => {
          if (settled) return
          log.warn('封面下载连接失败', { url: trimmed.substring(0, 100), error: err.message })
          safeResolve({ success: false, error: `连接失败: ${err.message}`, code: 'NETWORK_ERROR' })
        })
      }

      // 统一的响应处理函数
      function handleResponse(res: any) {
        if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
          log.debug('封面下载重定向', { from: trimmed.substring(0, 80), statusCode: res.statusCode })
          // 递归跟随重定向，保持代理选择
          _downloadOne(res.headers.location, proxy, maxRedirects - 1).then(safeResolve)
          return
        }
        if (res.statusCode !== 200) {
          const errorChunks: Buffer[] = []
          res.on('data', (chunk: Buffer) => { if (errorChunks.length < 1) errorChunks.push(chunk) })
          res.on('end', () => {
            const preview = errorChunks.length > 0
              ? errorChunks[0].subarray(0, 500).toString('utf-8').replace(/\s+/g, ' ').trim()
              : '(空响应)'
            log.warn('封面下载 HTTP 错误', { url: trimmed.substring(0, 100), statusCode: res.statusCode, bodyPreview: preview })
            safeResolve({ success: false, error: `服务器返回 HTTP ${res.statusCode}`, code: 'HTTP_ERROR', statusCode: res.statusCode })
          })
          return
        }
        const chunks: Buffer[] = []
        res.on('data', (chunk: Buffer) => chunks.push(chunk))
        res.on('end', () => {
          const buffer = Buffer.concat(chunks)
          if (buffer.length === 0) {
            log.warn('封面下载返回空数据', { url: trimmed.substring(0, 100) })
            safeResolve({ success: false, error: '下载的图片数据为空', code: 'NETWORK_ERROR' })
            return
          }
          const mime = detectMimeType(buffer)
          const dataUrl = `data:${mime};base64,${buffer.toString('base64')}`
          log.info('封面下载成功', { url: trimmed.substring(0, 100), size: buffer.length, mime, viaProxy: !!proxy })
          safeResolve({ success: true, data: dataUrl })
        })
        res.on('error', (err: Error) => {
          if (settled) return
          log.warn('封面下载流错误', { url: trimmed.substring(0, 100), error: err.message })
          safeResolve({ success: false, error: `网络传输中断: ${err.message}`, code: 'NETWORK_ERROR' })
        })
      }
    } catch (err: any) {
      log.error('封面下载异常', { url: trimmed.substring(0, 100), error: err?.message ?? String(err) })
      safeResolve({ success: false, error: `下载异常: ${err?.message ?? '未知错误'}`, code: 'UNKNOWN' })
    }
  })
}

/** 下载图片并转为 base64 data URL
 *  如果配置了代理，直连和代理同时竞速，谁先返回用谁 */
async function downloadImageAsBase64(url: string, proxyUrl?: string, maxRedirects: number = 5): Promise<DownloadResult> {
  // 前置 URL 校验
  if (!url || typeof url !== 'string') {
    log.warn('封面 URL 无效', { url: String(url) })
    return { success: false, error: '无效的图片 URL', code: 'INVALID_URL' }
  }
  const trimmed = url.trim()
  if (!trimmed.startsWith('http://') && !trimmed.startsWith('https://')) {
    log.warn('封面 URL 协议不支持', { url: trimmed.substring(0, 100) })
    return { success: false, error: 'URL 必须以 http:// 或 https:// 开头', code: 'INVALID_URL' }
  }

  // SSRF 防护：拒绝私有 IP、localhost、元数据端点
  try {
    const parsed = new URL(trimmed)
    const hostname = parsed.hostname.toLowerCase()
    if (hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '::1') {
      log.warn('SSRF 防护：拒绝 localhost', { hostname })
      return { success: false, error: '不允许访问本地地址', code: 'SSRF_BLOCKED' }
    }
    if (hostname.match(/^(10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.)/)) {
      log.warn('SSRF 防护：拒绝私有 IP', { hostname })
      return { success: false, error: '不允许访问内网地址', code: 'SSRF_BLOCKED' }
    }
    if (hostname === '169.254.169.254') {
      log.warn('SSRF 防护：拒绝云元数据端点', { hostname })
      return { success: false, error: '不允许访问元数据服务', code: 'SSRF_BLOCKED' }
    }
  } catch {
    log.warn('URL 解析失败', { url: trimmed.substring(0, 100) })
    return { success: false, error: '无法解析图片 URL', code: 'INVALID_URL' }
  }

  // 防止无限重定向
  if (maxRedirects <= 0) {
    log.warn('封面下载重定向次数超出限制', { url: trimmed.substring(0, 100) })
    return { success: false, error: '重定向次数过多，下载失败', code: 'NETWORK_ERROR' }
  }

  // 解析代理配置
  const proxy = proxyUrl ? parseProxyUrl(proxyUrl) : null

  // 无代理：直连
  if (!proxy) {
    return _downloadOne(trimmed, null, maxRedirects)
  }

  // 有代理：直连与代理竞速，谁先返回成功用谁
  log.info('封面下载竞速', { url: trimmed.substring(0, 100), proxy: `${proxy.host}:${proxy.port}` })
  try {
    return await Promise.any([
      _downloadOne(trimmed, null, maxRedirects),
      _downloadOne(trimmed, proxy, maxRedirects),
    ])
  } catch {
    // 全部失败
    log.warn('封面下载：直连和代理均失败', { url: trimmed.substring(0, 100) })
    return { success: false, error: '直连和代理均下载失败，请检查网络', code: 'NETWORK_ERROR' }
  }
}

/** 将各种格式归一化为 Character */
async function normalizeCharacter(parsed: any, avatarBase64?: string, proxyUrl?: string): Promise<Character> {
  const data = parsed.data ?? parsed
  const now = Date.now()

  // 确定头像来源：优先级 传入参数 > JSON 中的图片字段
  let finalAvatar = avatarBase64 ?? ''
  if (!finalAvatar) {
    // 检查 JSON 中的图片字段
    const imageUrl =
      data.cover ?? data.avatar ?? data.image ?? data.image_url ??
      data.thumbnail ?? data.portrait ??
      parsed.cover ?? parsed.avatar ?? parsed.image ?? parsed.image_url ??
      null

    if (imageUrl) {
      if (typeof imageUrl === 'string') {
        if (imageUrl.startsWith('data:image/')) {
          // 已经是 data URL
          finalAvatar = imageUrl
        } else if (imageUrl.startsWith('http://') || imageUrl.startsWith('https://')) {
          // URL -> 下载
          const result = await downloadImageAsBase64(imageUrl, proxyUrl)
          if (result.success && result.data) {
            finalAvatar = result.data
            log.info('角色卡封面下载成功', { name: data.name, url: imageUrl.substring(0, 100) })
          } else {
            log.warn('角色卡封面下载失败', {
              name: data.name,
              url: imageUrl.substring(0, 100),
              code: result.code ?? 'UNKNOWN',
              error: result.error ?? '',
              statusCode: result.statusCode ?? null,
            })
          }
        } else if (/^[A-Za-z0-9+/=]{100,}$/.test(imageUrl.trim())) {
          // 纯 base64（无 data:image 前缀），自动检测类型并补全
          try {
            const buffer = Buffer.from(imageUrl.trim(), 'base64')
            const mime = detectMimeType(buffer)
            finalAvatar = `data:${mime};base64,${imageUrl.trim()}`
          } catch {
            log.warn('角色卡封面 base64 解析失败', { name: data.name })
          }
        }
      }
    }
  }

  // V2/V3 兼容：完整提取所有字段
  let firstMes = data.first_mes ?? data.firstMessage ?? ''
  const altGreetings: string[] = []
  if (Array.isArray(data.alternate_greetings)) {
    for (const g of data.alternate_greetings) {
      if (typeof g === 'string' && g.trim()) altGreetings.push(g)
    }
  }
  if (!firstMes && altGreetings.length > 0) {
    firstMes = altGreetings[0]
  }

  // 群聊专用开场白
  const groupGreetings: string[] = []
  if (Array.isArray(data.group_only_greetings)) {
    for (const g of data.group_only_greetings) {
      if (typeof g === 'string' && g.trim()) groupGreetings.push(g)
    }
  }

  // 记录原始图片 URL（用于重新加载封面）
  const rawImageUrl = (!finalAvatar)
    ? (data.avatar ?? data.image ?? data.image_url ?? '')
    : ''
  const importImageUrl = (typeof rawImageUrl === 'string' && !rawImageUrl.startsWith('data:')
    && (rawImageUrl.startsWith('http://') || rawImageUrl.startsWith('https://')))
    ? rawImageUrl : undefined

  const character: Character = {
    id: nanoid(),
    name: data.name ?? parsed.name ?? '未命名角色',
    avatar: finalAvatar,
    cover: finalAvatar, // 封面与头像初始同源，后续可单独更换
    description: data.description ?? '',
    personality: data.personality ?? '',
    scenario: data.scenario ?? '',
    firstMessage: firstMes,
    exampleDialog: data.mes_example ?? data.exampleDialog ?? '',
    tags: data.tags ?? [],
    lorebookId: data.character_book?.id ?? null,
    creator: data.creator ?? '',
    createdAt: now,
    updatedAt: now,
    alternateGreetings: altGreetings,
    systemPrompt: data.system_prompt ?? '',
    postHistoryInstructions: data.post_history_instructions ?? '',
    creatorNotes: data.creator_notes ?? '',
    characterVersion: data.character_version ?? '',
    groupOnlyGreetings: groupGreetings,
    extensions: data.extensions ?? undefined,
    translatedContent: data.extensions?.translatedContent ?? undefined,
    _importImageUrl: importImageUrl,
  }

  // 自动提取内嵌世界书
  const charBook = data.character_book
  if (charBook && charBook.entries && Array.isArray(charBook.entries) && charBook.entries.length > 0) {
    try {
      const lorebookId = nanoid()
      const entries: LoreEntry[] = charBook.entries.map((e: any, i: number) => ({
        id: e.uid?.toString() ?? nanoid(),
        keywords: Array.isArray(e.key) ? e.key.filter(Boolean) : (e.key ? String(e.key).split(',').map((s: string) => s.trim()).filter(Boolean) : []),
        content: e.content ?? '',
        position: e.position === 'before' || e.position === 0 ? 'before_char'
          : e.position === 'after' || e.position === 1 ? 'after_char'
          : e.position === 'depth' || e.position === 'at_depth' || e.position === 2 ? 'at_depth'
          : 'at_end',
        depth: typeof e.depth === 'number' ? Math.max(0, e.depth) : 0,
        order: e.order ?? i,
        probability: e.probability ?? 100,
        enabled: e.disable ? false : (e.enabled !== undefined ? e.enabled : true),
      }))

      const lorebook: Lorebook = {
        id: lorebookId,
        name: charBook.name ?? `${character.name}的世界书`,
        description: charBook.description ?? '',
        entries,
        enabled: true,
        scanDepth: charBook.scan_depth ?? 4,
      }

      const lorebookDir = DIRS.lorebooks()
      mkdirSync(lorebookDir, { recursive: true })
      writeJson(join(lorebookDir, `${lorebookId}.json`), lorebook)
      character.lorebookId = lorebookId
    } catch {
      // 提取失败不阻断角色导入
    }
  }

  // 自动匹配世界书：若角色卡不含内嵌世界书，扫描已有世界书库匹配
  if (!character.lorebookId) {
    try {
      const lorebookDir = DIRS.lorebooks()
      if (existsSync(lorebookDir)) {
        const files = readdirSync(lorebookDir).filter(f => f.endsWith('.json'))
        if (files.length > 0) {
          const charText = [
            character.name,
            character.description,
            character.personality,
            character.scenario,
            ...(character.tags || []),
          ].filter(Boolean).join(' ').toLowerCase()

          let bestScore = 0
          let bestLorebookId: string | null = null

          for (const file of files) {
            const lb: Lorebook = JSON.parse(readFileSync(join(lorebookDir, file), 'utf-8'))
            if (!lb.enabled) continue

            const lbText = [
              lb.name,
              lb.description,
              ...lb.entries.flatMap(e => e.keywords),
            ].filter(Boolean).join(' ').toLowerCase()

            const lbWords = new Set(lbText.split(/\s+/).filter(w => w.length > 1))
            const charWords = new Set(charText.split(/\s+/).filter(w => w.length > 1))
            let score = 0
            for (const w of charWords) {
              if (lbWords.has(w)) score++
            }

            if (score > bestScore) {
              bestScore = score
              bestLorebookId = lb.id
            }
          }

          if (bestScore >= 2 && bestLorebookId) {
            character.lorebookId = bestLorebookId
          }
        }
      }
    } catch {
      // 匹配失败不阻断导入
    }
  }

  return character
}

/** 导出角色卡为 PNG */
export function exportCharacterToPng(character: Character, savePath: string): void {
  let pngBuffer: Buffer
  if (character.avatar.startsWith('data:image/png;base64,')) {
    pngBuffer = Buffer.from(character.avatar.split(',')[1], 'base64')
  } else if (character.avatar.startsWith('data:image/')) {
    // 非 PNG 图片，创建 1x1 透明 PNG 作为基底
    pngBuffer = Buffer.from(
      'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==',
      'base64'
    )
  } else {
    pngBuffer = Buffer.from(
      'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==',
      'base64'
    )
  }

  const charaJson = JSON.stringify({
    spec: 'chara_card_v2',
    spec_version: '2.0',
    data: {
      name: character.name,
      description: character.description,
      personality: character.personality,
      scenario: character.scenario,
      first_mes: character.firstMessage,
      alternate_greetings: character.alternateGreetings,
      mes_example: character.exampleDialog,
      system_prompt: character.systemPrompt || '',
      post_history_instructions: character.postHistoryInstructions || '',
      creator_notes: character.creatorNotes || '',
      character_version: character.characterVersion || '',
      group_only_greetings: character.groupOnlyGreetings || [],
      tags: character.tags,
      creator: character.creator,
      extensions: {
        ...(character.extensions || {}),
        ...(character.translatedContent ? { translatedContent: character.translatedContent } : {}),
      },
    },
  })
  const charaBase64 = Buffer.from(charaJson).toString('base64')

  const newBuffer = writePngTextChunk(pngBuffer, 'chara', charaBase64)
  writeFileSync(savePath, newBuffer)
}

