/** 保存角色头像（自动检测 MIME 类型） */
export function saveAvatar(characterId: string, base64Data: string): string {
  if (!base64Data) return ''
  const avatarDir = DIRS.characters()
  mkdirSync(avatarDir, { recursive: true })

  const base64 = base64Data.replace(/^data:image\/\w+;base64,/, '')
  const buffer = Buffer.from(base64, 'base64')
  const mime = detectMimeType(buffer)
  const ext = mime.split('/')[1] // png, jpeg, gif, webp
  const fileName = ext === 'jpeg' ? 'jpg' : ext

  const avatarPath = join(avatarDir, `${characterId}.${fileName}`)
  writeFileSync(avatarPath, buffer)
  return avatarPath
}

/** 读取角色头像 base64（自动检测 MIME 类型） */
export function readAvatar(characterId: string): string | null {
  const avatarDir = DIRS.characters()
  // 尝试所有可能的扩展名
  const extensions = ['png', 'jpg', 'jpeg', 'gif', 'webp']
  for (const ext of extensions) {
    const avatarPath = join(avatarDir, `${characterId}.${ext}`)
    if (existsSync(avatarPath)) {
      try {
        const buffer = readFileSync(avatarPath)
        const mime = detectMimeType(buffer)
        return `data:${mime};base64,${buffer.toString('base64')}`
      } catch {
        continue
      }
    }
  }
  return null
}

/** 保存封面 */
export function saveCover(characterId: string, base64Data: string): string {
  if (!base64Data) return ''
  const avatarDir = DIRS.characters()
  mkdirSync(avatarDir, { recursive: true })

  const base64 = base64Data.replace(/^data:image\/\w+;base64,/, '')
  const buffer = Buffer.from(base64, 'base64')
  const mime = detectMimeType(buffer)
  const ext = mime.split('/')[1]
  const fileName = ext === 'jpeg' ? 'jpg' : ext

  const coverPath = join(avatarDir, `${characterId}_cover.${fileName}`)
  writeFileSync(coverPath, buffer)
  return coverPath
}

/** 读取封面 base64 */
export function readCover(characterId: string): string | null {
  const avatarDir = DIRS.characters()
  const extensions = ['png', 'jpg', 'jpeg', 'gif', 'webp']
  for (const ext of extensions) {
    const coverPath = join(avatarDir, `${characterId}_cover.${ext}`)
    if (existsSync(coverPath)) {
      try {
        const buffer = readFileSync(coverPath)
        const mime = detectMimeType(buffer)
        return `data:${mime};base64,${buffer.toString('base64')}`
      } catch {
        continue
      }
    }
  }
  return null
}

/** 保存角色 */
export function saveCharacter(character: Character): void {
  const filePath = join(DIRS.characters(), `${character.id}.json`)
  mkdirSync(DIRS.characters(), { recursive: true })

  // 保存头像和封面到文件
  if (character.avatar.startsWith('data:')) {
    saveAvatar(character.id, character.avatar)
  }
  if (character.cover && character.cover.startsWith('data:')) {
    saveCover(character.id, character.cover)
  }

  // JSON 中不存 base64，只存空字符串（图片从文件读取）
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const { avatar: _avatar, cover: _cover, ...rest } = character
  writeJson(filePath, { ...rest, avatar: '', cover: '' })
}

/** 读取角色列表（仅元数据，图片通过 tavern:// 协议按需加载） */
export async function listCharacters(): Promise<Character[]> {
  const charDir = DIRS.characters()
  if (!existsSync(charDir)) return []

  const files = readdirSync(charDir).filter((f) => f.endsWith('.json'))

  // 并行读取所有角色 JSON（不含图片 base64，避免 IPC 传输大量数据）
  const results = await Promise.all(
    files.map((file) => readJsonAsync<Character>(join(charDir, file))),
  )

  const chars: Character[] = []
  for (const char of results) {
    if (char) {
      chars.push(char)
    }
  }

  // 按更新时间倒序
  return chars.sort((a, b) => b.updatedAt - a.updatedAt)
}

/** 读取单个角色 */
export function getCharacter(id: string): Character | null {
  const filePath = join(DIRS.characters(), `${id}.json`)
  const char = readJson<Character>(filePath)
  if (char) {
    const avatar = readAvatar(id)
    if (avatar) char.avatar = avatar
    const cover = readCover(id)
    if (cover) char.cover = cover
  }
  return char
}

/** 删除角色 */
export function deleteCharacter(id: string): void {
  const charDir = DIRS.characters()
  const jsonPath = join(charDir, `${id}.json`)
  if (existsSync(jsonPath)) unlinkSync(jsonPath)

  // 删除头像文件（所有扩展名）
  for (const ext of ['png', 'jpg', 'jpeg', 'gif', 'webp']) {
    const avatarPath = join(charDir, `${id}.${ext}`)
    if (existsSync(avatarPath)) {
      try { unlinkSync(avatarPath) } catch { /* 忽略 */ }
    }
    // 也删除封面文件
    const coverPath = join(charDir, `${id}_cover.${ext}`)
    if (existsSync(coverPath)) {
      try { unlinkSync(coverPath) } catch { /* 忽略 */ }
    }
  }
}

/** 重新从 URL 加载角色封面头像 */
export async function reloadAvatarFromUrl(characterId: string, url: string, proxyUrl?: string): Promise<{ success: boolean; avatar: string; error?: string; code?: string }> {
  log.info('重新加载封面', { characterId, url: url.substring(0, 100) })
  const result = await downloadImageAsBase64(url, proxyUrl)
  if (!result.success || !result.data) {
    log.warn('重新加载封面失败', { characterId, code: result.code ?? 'UNKNOWN', error: result.error ?? '' })
    return { success: false, avatar: '', error: result.error, code: result.code }
  }
  saveAvatar(characterId, result.data)
  saveCover(characterId, result.data) // 封面同步更新
  log.info('重新加载封面成功', { characterId })
  return { success: true, avatar: result.data }
}

// ===================== 角色卡前端扩展适配（regex_scripts / quick_replies） =====================

/** 官方 SillyTavern regex_scripts 条目 → 项目 RegexRule（不支持的返回 null） */
function convertRegexScript(script: unknown): RegexRule | null {
  if (!script || typeof script !== 'object') return null
  const s = script as Record<string, unknown>
  const pattern = typeof s.findRegex === 'string' ? s.findRegex : ''
  if (!pattern) return null
  const replacement = typeof s.replaceString === 'string' ? s.replaceString : ''

  // promptOnly：仅作用在 prompt 阶段，项目无此阶段 → 跳过
  if (s.promptOnly === true) return null

  // placement → scope（ST 默认 user_input + ai_output = both）
  const placement: unknown[] = Array.isArray(s.placement) ? s.placement : []
  const hasInput = placement.length === 0 || placement.includes('user_input')
  const hasOutput = placement.length === 0 || placement.includes('ai_output')
  const scope: RegexRule['scope'] = hasInput && hasOutput ? 'both' : hasInput ? 'input' : 'output'

  // markdownOnly：仅 output 有 markdown 阶段（input 规则实际不会生效 → 跳过）
  let stage: RegexRule['stage'] = 'text'
  if (s.markdownOnly === true) {
    if (!hasOutput) return null
    stage = 'markdown'
  }

  return {
    id: nanoid(),
    name: typeof s.scriptName === 'string' && s.scriptName.trim() ? s.scriptName : '角色卡正则',
    pattern,
    replacement,
    // ST 默认大小写不敏感
    flags: 'gi',
    enabled: s.disabled !== true,
    scope,
    group: '角色卡导入',
    stage,
  }
}

/** 官方 SillyTavern quick_replies 条目 → 项目 QuickReply（不支持的返回 null） */
function convertCardQuickReply(qr: unknown, index: number): QuickReply | null {
  if (!qr || typeof qr !== 'object') return null
  const q = qr as Record<string, unknown>
  const label = typeof q.label === 'string' && q.label.trim() ? q.label : '快捷回复'
  const message = typeof q.message === 'string' ? q.message : (typeof q.content === 'string' ? q.content : '')
  if (!message) return null
  const isCommand = q.messageType === 'command' || q.messageType === 'slash'
  const hotkey = typeof q.hotkey === 'number' && q.hotkey >= 1 && q.hotkey <= 9 ? q.hotkey : undefined
  return {
    id: typeof q.id === 'string' && q.id ? q.id : nanoid(),
    label,
    content: message,
    action: isCommand ? 'command' : 'text',
    command: isCommand ? message : undefined,
    sendWithAI: true,
    hotkey,
    order: index,
    enabled: true,
  }
}

export interface CardExtrasResult {
  regexCount: number
  quickReplyCount: number
  /** 因不支持而跳过的项描述 */
  skipped: string[]
}

/**
 * 角色卡前端扩展落地（幂等，可重复导入）：
 * - extensions.regex_scripts → 正则规则库（group「角色卡导入」）
 * - extensions.quick_replies → 角色级快捷回复
 * 失败不阻断角色导入。
 */
export function importCardFrontendExtensions(character: Character): CardExtrasResult {
  const result: CardExtrasResult = { regexCount: 0, quickReplyCount: 0, skipped: [] }
  const exts = character.extensions
  if (!exts || typeof exts !== 'object') return result

  // ---- 正则脚本 ----
  if (Array.isArray(exts.regex_scripts)) {
    const rulesPath = join(DIRS.config(), 'regex', 'rules.json')
    let existing: RegexRule[] = []
    try {
      if (existsSync(rulesPath)) existing = JSON.parse(readFileSync(rulesPath, 'utf-8')) as RegexRule[]
    } catch { /* 文件损坏则从空列表开始 */ }
    const existingKeys = new Set(existing.map(r => `${r.pattern}|${r.scope}|${r.stage ?? 'text'}`))
    for (const script of exts.regex_scripts) {
      const rule = convertRegexScript(script)
      if (!rule) {
        const s = script as Record<string, unknown> | null
        if (s && typeof s.scriptName === 'string') result.skipped.push(`正则「${s.scriptName}」`)
        continue
      }
      const key = `${rule.pattern}|${rule.scope}|${rule.stage}`
      if (existingKeys.has(key)) continue // 已导入过（幂等）
      existingKeys.add(key)
      existing.push(rule)
      result.regexCount++
    }
    if (result.regexCount > 0) {
      try {
        mkdirSync(join(DIRS.config(), 'regex'), { recursive: true })
        writeFileSync(rulesPath, JSON.stringify(existing, null, 2), 'utf-8')
      } catch (e) {
        log.error('角色卡正则落地失败', { error: (e as Error).message })
        result.regexCount = 0
      }
    }
  }

  // ---- 快捷回复 ----
  if (Array.isArray(exts.quick_replies)) {
    const storePath = join(DIRS.config(), 'quickReplies.json')
    let store: QuickReplyStore = { global: [], byCharacter: {} }
    try {
      const raw = readJson<QuickReplyStore>(storePath)
      if (raw && Array.isArray(raw.global)) store = { global: raw.global, byCharacter: raw.byCharacter ?? {} }
    } catch { /* 重置 */ }
    const charList = store.byCharacter[character.id] ?? []
    const existingIds = new Set(charList.map(q => q.id))
    for (let i = 0; i < exts.quick_replies.length; i++) {
      const q = convertCardQuickReply(exts.quick_replies[i], i)
      if (!q) continue
      if (existingIds.has(q.id)) continue // 幂等
      existingIds.add(q.id)
      charList.push(q)
      result.quickReplyCount++
    }
    if (result.quickReplyCount > 0) {
      store.byCharacter[character.id] = charList
      try {
        writeJson(storePath, store)
      } catch (e) {
        log.error('角色卡快捷回复落地失败', { error: (e as Error).message })
        result.quickReplyCount = 0
      }
    }
  }

  if (result.regexCount > 0 || result.quickReplyCount > 0 || result.skipped.length > 0) {
    log.info('角色卡前端扩展已导入', { name: character.name, ...result })
  }
  return result
}

/**
 * 文生图服务
 *
 * 支持两种 provider：
 * - sd-webui: Stable Diffusion WebUI (Automatic1111) REST API
 * - openai:   OpenAI DALL-E 3 Images API
 */

import { createLogger } from './logger'
import type { ImageGenModelConfig } from '../../shared/types'

const log = createLogger('imageGen')

/** 生图选项 */
export interface ImageGenOptions {
  negativePrompt?: string
  size?: string
  quality?: string
}

/** 生图结果 */
export interface ImageGenResult {
  success: boolean
  images?: string[]    // base64 data URL 数组
  error?: string
}

/** 主入口：根据 provider 分派到不同适配器 */
export async function generateImage(
  config: ImageGenModelConfig,
  prompt: string,
  options?: ImageGenOptions,
): Promise<ImageGenResult> {
  // 根据后端类型清洗提示词
  const cleanedPrompt = config.provider === 'sd-webui'
    ? sanitizeSdPrompt(prompt)
    : sanitizeOpenAiPrompt(prompt)

  log.info('生图请求', {
    provider: config.provider,
    prompt: cleanedPrompt.substring(0, 80),
    size: options?.size ?? config.size,
  })

  try {
    switch (config.provider) {
      case 'sd-webui':
        return await sdWebuiGenerate(config, cleanedPrompt, options)
      case 'openai':
        return await openaiGenerate(config, cleanedPrompt, options)
      default:
        return { success: false, error: `不支持的 provider: ${config.provider}` }
    }
  } catch (err: any) {
    log.error('生图失败', { provider: config.provider, error: err?.message ?? String(err) })
    return { success: false, error: err?.message ?? String(err) }
  }
}

/** 解析尺寸字符串 "512x512" -> [512, 512] */
function parseSize(size: string): [number, number] {
  const match = size.match(/^(\d+)\s*[x×]\s*(\d+)$/i)
  if (match) {
    return [parseInt(match[1], 10), parseInt(match[2], 10)]
  }
  return [512, 512] // 默认
}

/**
 * SD WebUI 提示词清洗（参考 SillyTavern processReply）
 *
 * SD 模型使用逗号分隔的标签（如 "1girl, red dress, outdoor"），
 * 需要：
 * 1. 移除引号（含中文引号）
 * 2. 换行替换为逗号
 * 3. NFD 规范化
 * 4. 移除非 SD 语法字符（保留 a-zA-Z0-9 及 .,:_(){}<>[]/'|#- 和中文）
 * 5. 按逗号分割、trim、过滤空值、重新 join
 */
function sanitizeSdPrompt(str: string): string {
  if (!str) return str
  let s = str
    .replaceAll('"', '')
    .replaceAll('"', '')
    .replaceAll('"', '')
    .replaceAll('\n', ', ')
  s = s.normalize('NFD')
  // 保留：字母数字、SD 语法符号、中文 CJK 字符
  s = s.replace(/[^a-zA-Z0-9.,:_(){}<>[\]/\-'|#\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af\s]+/g, ' ')
  s = s.split(',').map((x) => x.trim()).filter((x) => x).join(', ')
  return s
}

/**
 * OpenAI DALL-E 提示词轻度清洗
 *
 * DALL-E 支持自然语言描述，仅移除多余引号和换行，保留原始语义
 */
function sanitizeOpenAiPrompt(str: string): string {
  if (!str) return str
  return str
    .replaceAll('"', '')
    .replaceAll('"', '')
    .replaceAll('"', '')
    .replace(/\s+/g, ' ')
    .trim()
}

// ===================== SD WebUI (Automatic1111) 适配器 =====================

async function sdWebuiGenerate(
  config: ImageGenModelConfig,
  prompt: string,
  options?: ImageGenOptions,
): Promise<ImageGenResult> {
  const baseUrl = config.baseUrl.replace(/\/$/, '')
  const url = `${baseUrl}/sdapi/v1/txt2img`

  const sizeStr = options?.size || config.size || '512x512'
  const [width, height] = parseSize(sizeStr)

  const body = {
    prompt,
    negative_prompt: options?.negativePrompt || config.negativePrompt || '',
    steps: config.steps ?? 20,
    cfg_scale: config.cfgScale ?? 7,
    width,
    height,
    sampler_name: config.sampler || 'Euler a',
    batch_size: 1,
  }

  log.debug('SD WebUI 请求', { url, width, height, steps: body.steps })

  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const errText = await response.text()
    throw new Error(`SD WebUI API 错误 ${response.status}: ${errText.substring(0, 200)}`)
  }

  const data: any = await response.json()
  if (!data.images || !Array.isArray(data.images) || data.images.length === 0) {
    throw new Error('SD WebUI 返回的图片数据为空')
  }

  // SD WebUI 返回的 images 数组中每个元素是纯 base64（无 data: 前缀）
  const images = data.images.map((b64: string) => `data:image/png;base64,${b64}`)

  log.info('SD WebUI 生图成功', { count: images.length, size: sizeStr })

  return { success: true, images }
}

// ===================== OpenAI DALL-E 适配器 =====================

async function openaiGenerate(
  config: ImageGenModelConfig,
  prompt: string,
  options?: ImageGenOptions,
): Promise<ImageGenResult> {
  const baseUrl = config.baseUrl.replace(/\/$/, '')
  const url = `${baseUrl}/images/generations`

  const body = {
    model: config.model || 'dall-e-3',
    prompt,
    n: 1,
    size: options?.size || config.size || '1024x1024',
    quality: options?.quality || config.quality || 'standard',
    response_format: 'b64_json',
  }

  log.debug('OpenAI 生图请求', { url, model: body.model, size: body.size })

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${config.apiKey}`,
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const errText = await response.text()
    throw new Error(`OpenAI API 错误 ${response.status}: ${errText.substring(0, 200)}`)
  }

  const data: any = await response.json()
  if (!data.data || !Array.isArray(data.data) || data.data.length === 0) {
    throw new Error('OpenAI 返回的图片数据为空')
  }

  // OpenAI 返回 b64_json 字段
  const images = data.data
    .map((item: any) => item.b64_json)
    .filter((b64: string) => !!b64)
    .map((b64: string) => `data:image/png;base64,${b64}`)

  if (images.length === 0) {
    throw new Error('OpenAI 返回的图片数据格式异常')
  }

  log.info('OpenAI 生图成功', { count: images.length, size: body.size })

  return { success: true, images }
}

// ===================== 连接测试 =====================

export interface TestConnectionConfig {
  provider: string
  baseUrl: string
  apiKey: string
}

export interface TestConnectionResult {
  success: boolean
  message?: string
  error?: string
}

/**
 * 测试生图后端连接
 *
 * SD WebUI: GET /sdapi/v1/options 检查是否响应
 * OpenAI:   GET /models 检查 API key 是否有效
 */
export async function testImageGenConnection(config: TestConnectionConfig): Promise<TestConnectionResult> {
  const baseUrl = config.baseUrl.replace(/\/$/, '')

  try {
    if (config.provider === 'sd-webui') {
      // SD WebUI: 轮询 /sdapi/v1/options
      const url = `${baseUrl}/sdapi/v1/options`
      const response = await fetch(url, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' },
        signal: AbortSignal.timeout(10000),
      })

      if (!response.ok) {
        return { success: false, error: `HTTP ${response.status}: ${response.statusText}` }
      }

      const data: any = await response.json()
      const model = data?.sd_model_checkpoint || data?.sd_model_hash || '未知'
      return { success: true, message: `连接成功，当前模型: ${model}` }
    }

    if (config.provider === 'openai') {
      // OpenAI: GET /models 验证 API key
      const url = `${baseUrl}/models`
      const response = await fetch(url, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${config.apiKey}`,
        },
        signal: AbortSignal.timeout(10000),
      })

      if (!response.ok) {
        if (response.status === 401) {
          return { success: false, error: 'API Key 无效（401 Unauthorized）' }
        }
        const errText = await response.text()
        return { success: false, error: `HTTP ${response.status}: ${errText.substring(0, 100)}` }
      }

      const data: any = await response.json()
      const modelCount = data?.data?.length ?? 0
      return { success: true, message: `连接成功，可用模型 ${modelCount} 个` }
    }

    return { success: false, error: `不支持的 provider: ${config.provider}` }
  } catch (err: any) {
    if (err?.name === 'TimeoutError' || err?.name === 'AbortError') {
      return { success: false, error: '连接超时（10秒），请检查地址是否正确及服务是否已启动' }
    }
    if (err?.code === 'ECONNREFUSED') {
      return { success: false, error: '连接被拒绝，请确认服务已启动且端口正确' }
    }
    return { success: false, error: err?.message ?? String(err) }
  }
}

/**
 * 日志系统
 * 
 * - 双输出：console + 文件（{userData}/logs/qingyu.log）
 * - 四个级别：DEBUG / INFO / WARN / ERROR
 * - 自动轮转：单文件 > 1MB 自动 rotate，保留最近 5 个文件
 * 
 * 初始化：应用启动时调用 initLogger(userDataPath)
 * 使用：const log = createLogger('模块名')
 *       log.info('消息', { key: 'value' })
 */

import { appendFileSync, existsSync, mkdirSync, renameSync, statSync } from 'node:fs'
import { join } from 'node:path'

/** 日志级别 */
export enum LogLevel {
  DEBUG = 0,
  INFO = 1,
  WARN = 2,
  ERROR = 3,
}

/** 日志级别名称映射 */
const LEVEL_NAMES: Record<LogLevel, string> = {
  [LogLevel.DEBUG]: 'DEBUG',
  [LogLevel.INFO]: 'INFO ',
  [LogLevel.WARN]: 'WARN ',
  [LogLevel.ERROR]: 'ERROR',
}

/** 最大文件大小 (1MB) */
const MAX_FILE_SIZE = 1 * 1024 * 1024

/** 最大保留文件数 */
const MAX_LOG_FILES = 5

/** 日志文件基础名 */
const LOG_FILE_NAME = 'qingyu.log'

/** 全局日志目录路径 */
let logDir: string | null = null

/** P-8 修复：缓存日志文件大小，避免每条日志都 statSync */
let cachedLogSize = 0

/** 全局最低日志级别 */
let minLevel: LogLevel = LogLevel.DEBUG

/** 格式时间戳 */
function formatTime(): string {
  const now = new Date()
  const pad = (n: number) => String(n).padStart(2, '0')
  const ms = String(now.getMilliseconds()).padStart(3, '0')
  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ` +
    `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}.${ms}`
}

/** 格式化 key=value 元数据 */
function formatMeta(meta?: Record<string, any>): string {
  if (!meta || Object.keys(meta).length === 0) return ''
  const parts: string[] = []
  for (const [k, v] of Object.entries(meta)) {
    if (v === undefined || v === null) continue
    parts.push(`${k}=${String(v)}`)
  }
  return parts.length > 0 ? ' | ' + parts.join(' | ') : ''
}

// P-8 修复：缓存文件大小，仅超阈值时 statSync 校准 + 轮转
function rotateIfNeeded(): void {
  if (!logDir) return
  const logPath = join(logDir, LOG_FILE_NAME)
  if (!existsSync(logPath)) { cachedLogSize = 0; return }

  // 快速路径：缓存大小未超限，跳过 stat
  if (cachedLogSize < MAX_FILE_SIZE) return

  // 校准实际大小
  try {
    const stats = statSync(logPath)
    cachedLogSize = stats.size
    if (stats.size < MAX_FILE_SIZE) return
  } catch { return }

  // 轮转：qingyu.4.log → qingyu.5.log (删除), ... qingyu.log → qingyu.1.log
  for (let i = MAX_LOG_FILES - 1; i >= 0; i--) {
    const oldPath = join(logDir, i === 0 ? LOG_FILE_NAME : `${LOG_FILE_NAME.replace('.log', '')}.${i}.log`)
    const newPath = join(logDir, `${LOG_FILE_NAME.replace('.log', '')}.${i + 1}.log`)
    if (existsSync(oldPath)) {
      if (i >= MAX_LOG_FILES - 1) {
        // 删除最旧的
        try { require('node:fs').unlinkSync(oldPath) } catch { /* ignore */ }
      } else {
        try { renameSync(oldPath, newPath) } catch { /* ignore */ }
      }
    }
  }
  cachedLogSize = 0
}

/** 写入日志文件 */
function writeToFile(line: string): void {
  if (!logDir) return
  try {
    const logPath = join(logDir, LOG_FILE_NAME)
    rotateIfNeeded()
    const data = line + '\n'
    appendFileSync(logPath, data, 'utf-8')
    cachedLogSize += Buffer.byteLength(data, 'utf-8')
  } catch {
    // 文件写入失败，至少 console 已有输出
  }
}

/** 日志记录器 */
export class Logger {
  private module: string

  constructor(module: string) {
    this.module = module
  }

  debug(message: string, meta?: Record<string, any>): void {
    this.log(LogLevel.DEBUG, message, meta)
  }

  info(message: string, meta?: Record<string, any>): void {
    this.log(LogLevel.INFO, message, meta)
  }

  warn(message: string, meta?: Record<string, any>): void {
    this.log(LogLevel.WARN, message, meta)
  }

  error(message: string, meta?: Record<string, any>): void {
    this.log(LogLevel.ERROR, message, meta)
  }

  private log(level: LogLevel, message: string, meta?: Record<string, any>): void {
    if (level < minLevel) return

    const line = `[${formatTime()}] [${LEVEL_NAMES[level]}] [${this.module}] ${message}${formatMeta(meta)}`

    // 双输出
    if (level === LogLevel.ERROR) {
      console.error(line)
    } else if (level === LogLevel.WARN) {
      console.warn(line)
    } else {
      console.log(line)
    }
    writeToFile(line)
  }
}

/** 日志实例缓存 */
const loggerCache = new Map<string, Logger>()

/** 创建日志记录器 */
export function createLogger(module: string): Logger {
  const existing = loggerCache.get(module)
  if (existing) return existing
  const logger = new Logger(module)
  loggerCache.set(module, logger)
  return logger
}

/** 获取日志记录器（不创建） */
export function getLogger(module: string): Logger | undefined {
  return loggerCache.get(module)
}

/** 初始化日志系统 */
export function initLogger(userDataPath: string, level: LogLevel = LogLevel.DEBUG): void {
  minLevel = level
  logDir = join(userDataPath, 'logs')
  try {
    if (!existsSync(logDir)) {
      mkdirSync(logDir, { recursive: true })
    }
  } catch {
    logDir = null // 无法创建目录，只输出到 console
  }

  const log = createLogger('bootstrap')
  log.info('日志系统初始化完成', { path: logDir ?? '(console only)', level: LEVEL_NAMES[level].trim() })
}

/** 获取日志内容（供渲染进程查看） */
export function getRecentLogs(lineCount: number = 200): string {
  if (!logDir) return ''
  const logPath = join(logDir, LOG_FILE_NAME)
  if (!existsSync(logPath)) return ''

  try {
    const content = require('node:fs').readFileSync(logPath, 'utf-8')
    const lines = content.split('\n').filter(Boolean)
    return lines.slice(-lineCount).join('\n')
  } catch {
    return '(日志读取失败)'
  }
}

import type { WebContents } from 'electron'

/**
 * 安全地向渲染进程发送 IPC 消息
 * E-02 修复：防止窗口关闭后 webContents.send 抛出 "Object has been destroyed" 错误
 */
export function safeSend(webContents: WebContents, channel: string, ...args: any[]): boolean {
  if (webContents.isDestroyed()) return false
  try {
    webContents.send(channel, ...args)
    return true
  } catch {
    return false
  }
}

