import { isLocalProvider } from '../../utils/defaults'
import { logError } from '../../lib/logger'

// B-05：记住 textarea 手动调整后的大小（使用原生 DOM 事件，React 合成事件无法捕获浏览器 resize handle）
const TA_HEIGHTS_KEY = 'editor-ta-heights'
function loadTaHeights(): Record<string, number> {
  try { return JSON.parse(localStorage.getItem(TA_HEIGHTS_KEY) || '{}') } catch { return {} }
}
function saveTaHeight(id: string, h: number) {
  const heights = loadTaHeights()
  heights[id] = h
  localStorage.setItem(TA_HEIGHTS_KEY, JSON.stringify(heights))
}
/** 绑定 textarea ref：恢复记忆高度 + 监听原生 mouseup 保存高度 */
function useTaResize(id: string, defaultMinH: number) {
  const ref = useRef<HTMLTextAreaElement>(null)
  const saved = loadTaHeights()[id]

  // 挂载后恢复记忆高度
  useEffect(() => {
    const ta = ref.current
    if (ta && saved && saved > defaultMinH) {
      ta.style.height = `${saved}px`
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // 监听原生 mouseup（浏览器 resize handle 的 mouseup 不会触发 React 合成事件）
  useEffect(() => {
    const ta = ref.current
    if (!ta) return
    const onMouseUp = () => {
      saveTaHeight(id, ta.offsetHeight)
    }
    ta.addEventListener('mouseup', onMouseUp)
    return () => ta.removeEventListener('mouseup', onMouseUp)
  }, [id])

  const style: React.CSSProperties = {
    minHeight: `${saved && saved > defaultMinH ? saved : defaultMinH}px`,
  }
  return { ref, style }
}

/** B-05：预设绑定选择器 */
interface CharacterEditorProps {
  character: Character
  onSave: (character: Character) => void
  onClose: () => void
}

type TranslatableField = keyof Pick<Character, 'name' | 'description' | 'personality' | 'scenario' | 'firstMessage' | 'exampleDialog'>
const TRANSLATABLE_FIELDS: { key: TranslatableField; label: string }[] = [
  { key: 'name', label: '角色名' },
  { key: 'description', label: '角色描述' },
  { key: 'personality', label: '性格特征' },
  { key: 'scenario', label: '场景设定' },
  { key: 'firstMessage', label: '首条消息' },
  { key: 'exampleDialog', label: '对话示例' },
]

export function CharacterEditor({ character, onSave, onClose }: CharacterEditorProps) {
  const [form, setForm] = useState<Character>(character)
  const [tagInput, setTagInput] = useState('')
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [translating, setTranslating] = useState(false)
  const [translatingField, setTranslatingField] = useState<string | null>(null)
  const [translatedFields, setTranslatedFields] = useState<Set<string>>(new Set())
  const [translateError, setTranslateError] = useState<string | null>(null)
  const [coverReloading, setCoverReloading] = useState(false)
  const [coverError, setCoverError] = useState<string | null>(null)
  const [avatarError, setAvatarError] = useState(false)
  // H-09 修复：追踪活跃的翻译请求，组件卸载时取消
  const activeRequestIdsRef = useRef<Set<string>>(new Set())
  const { settings } = useSettingsStore()

  // B-05：textarea 高度记忆
  const taDesc = useTaResize('desc', 120)
  const taPersonality = useTaResize('personality', 80)
  const taScenario = useTaResize('scenario', 80)
  const taSysprompt = useTaResize('sysprompt', 80)
  const taFirstmsg = useTaResize('firstmsg', 120)
  const taPosthist = useTaResize('posthist', 60)
  const taExdialog = useTaResize('exdialog', 100)

  useEffect(() => {
    setForm(character)
  }, [character])

  // H-09 修复：组件卸载时取消所有活跃的翻译请求
  useEffect(() => {
    return () => {
      const ids = Array.from(activeRequestIdsRef.current)
      for (const id of ids) {
        window.api.ai.cancelChat(id).catch((e) => logError('CharacterEditor:cancelChat', e))
      }
      activeRequestIdsRef.current.clear()
    }
  }, [])

  const update = (partial: Partial<Character>) => {
    setForm((prev) => ({ ...prev, ...partial }))
  }

  const handleImageSelect = async () => {
    const path = await window.api.file.selectImage()
    if (path) {
      const base64 = await window.api.file.readImageAsBase64(path)
      update({ avatar: base64, _importImageUrl: undefined })
    }
  }

  const handleBackgroundSelect = async () => {
    const path = await window.api.file.selectImage()
    if (path) {
      const base64 = await window.api.file.readImageAsBase64(path)
      update({ chatBackground: base64 })
    }
  }

  const handleReloadCover = async () => {
    if (!form._importImageUrl) return
    setCoverReloading(true)
    setCoverError(null)
    try {
      const result = await window.api.character.reloadAvatar(form.id, form._importImageUrl)
      if (result.success && result.avatar) {
        // 同时更新 avatar 和 cover，确保保存时 cover 字段不为空
        update({ avatar: result.avatar, cover: result.avatar, _importImageUrl: undefined })
        setAvatarError(false)
        setCoverError(null)
      } else {
        // 根据错误码显示用户友好提示
        const code = result.code ?? 'UNKNOWN'
        const errorMap: Record<string, string> = {
          TIMEOUT: '封面加载超时，请检查网络连接后重试',
          HTTP_ERROR: `封面图片加载失败 (${result.error || '未知HTTP错误'})`,
          NETWORK_ERROR: '网络连接失败，请检查 URL 是否可访问',
          INVALID_URL: '无效的封面图片 URL',
          INVALID_FORMAT: '不支持的图片格式',
          UNKNOWN: '封面加载失败，请稍后重试',
        }
        setCoverError(errorMap[code] || result.error || '封面加载失败')
      }
    } catch {
      setCoverError('封面加载失败，请稍后重试')
    }
    setCoverReloading(false)
  }

  const handleAddTag = () => {
    const tag = tagInput.trim()
    if (tag && !form.tags.includes(tag)) {
      update({ tags: [...form.tags, tag] })
    }
    setTagInput('')
  }

  const handleRemoveTag = (tag: string) => {
    update({ tags: form.tags.filter((t) => t !== tag) })
  }

  const handleSave = () => {
    if (!form.name.trim()) {
      form.name = '未命名角色'
    }
    onSave(form)
  }

  const handleAiTranslate = async () => {
    setTranslating(true)
    setTranslateError(null)
    setTranslatedFields(new Set())

    const profile = useSettingsStore.getState().getActiveProfile()
    if (!profile || (!profile.apiKey && !isLocalProvider(profile.provider))) {
      setTranslateError('请先配置 API 连接')
      setTranslating(false)
      return
    }

    // 先翻译角色名，后续字段可引用中文名作为上下文
    let translatedName = form.name
    if (form.name && form.name.trim()) {
      try {
        const result = await translateText(form.name, '角色名', settings, profile, form.name)
        if (result) {
          translatedName = result
          const tc = { ...(form.translatedContent || {}) }
          tc.name = result
          update({ translatedContent: tc } as Partial<Character>)
          setTranslatedFields((prev) => new Set(prev).add('name'))
        }
      } catch {
        setTranslateError('翻译"角色名"时出现错误，已跳过')
      }
    }

    // 翻译其余字段，使用翻译后的名称作为上下文
    for (const { key, label } of TRANSLATABLE_FIELDS) {
      if (key === 'name') continue // 已翻译
      const text = form[key]
      if (!text || !text.trim()) continue

      try {
        const result = await translateText(text, label, settings, profile, translatedName)
        if (result) {
          // 首条消息直接替换原文（用于发送给 AI），其他字段存入 translatedContent 双语显示
          if (key === 'firstMessage') {
            update({ firstMessage: result })
          } else {
            const tc = { ...(form.translatedContent || {}) }
            tc[key] = result
            update({ translatedContent: tc } as Partial<Character>)
          }
          setTranslatedFields((prev) => new Set(prev).add(key))
        }
      } catch {
        setTranslateError(`翻译"${label}"时出现错误，已跳过`)
      }
    }

    setTranslating(false)
  }

  // 单字段独立翻译
  const handleTranslateField = async (fieldKey: TranslatableField) => {
    const text = form[fieldKey]
    if (!text || !text.trim()) return

    const profile = useSettingsStore.getState().getActiveProfile()
    if (!profile || (!profile.apiKey && !isLocalProvider(profile.provider))) {
      setTranslateError('请先配置 API 连接')
      return
    }

    const nameForContext = form.translatedContent?.name ?? undefined
    const fieldLabel = TRANSLATABLE_FIELDS.find(f => f.key === fieldKey)?.label ?? fieldKey

    setTranslatingField(fieldKey)
    try {
      const result = await translateText(text, fieldLabel, settings, profile, nameForContext)
      if (result) {
        // 首条消息直接替换原文（用于发送给 AI），其他字段存入 translatedContent 双语显示
        if (fieldKey === 'firstMessage') {
          update({ firstMessage: result })
        } else {
          const tc = { ...(form.translatedContent || {}) }
          tc[fieldKey] = result
          update({ translatedContent: tc } as Partial<Character>)
          setTranslatedFields(prev => new Set(prev).add(fieldKey))
        }
      }
    } catch {
      setTranslateError(`翻译"${fieldLabel}"失败`)
    }
    setTranslatingField(null)
  }

  // 翻译单条备选开场白
  const handleTranslateGreeting = async (index: number) => {
    const greetings = form.alternateGreetings || []
    const text = greetings[index]
    if (!text || !text.trim()) return

    const profile = useSettingsStore.getState().getActiveProfile()
    if (!profile || (!profile.apiKey && !isLocalProvider(profile.provider))) {
      setTranslateError('请先配置 API 连接')
      return
    }

    const nameForContext = form.translatedContent?.name ?? undefined
    setTranslatingField(`greeting-${index}`)
    try {
      const result = await translateText(text, '首条消息', settings, profile, nameForContext)
      if (result) {
        const updated = [...greetings]
        updated[index] = result
        update({ alternateGreetings: updated })
      }
    } catch {
      setTranslateError('翻译备选开场白失败')
    }
    setTranslatingField(null)
  }

  // H-09 修复：translateText 移入组件内部以追踪活跃请求
  const translateText = async (
    text: string,
    fieldLabel: string,
    settings: ReturnType<typeof useSettingsStore.getState>['settings'],
    profile: { provider: ProviderType; apiKey: string; baseUrl: string; model: string },
    characterName?: string,
  ): Promise<string> => {
    const requestId = `translate-card-${Date.now()}-${Math.random().toString(36).slice(2)}`
    activeRequestIdsRef.current.add(requestId)

    return new Promise((resolve) => {
      let result = ''

      const cleanup = () => {
        activeRequestIdsRef.current.delete(requestId)
        unbindChunk(); unbindDone(); unbindError()
      }

      const unbindChunk = window.api.ai.onChunk((data) => {
        if (data.requestId !== requestId) return
        result += data.text
      })
      const unbindDone = window.api.ai.onDone((doneId) => {
        if (doneId !== requestId) return
        cleanup()
        const cleaned = result.replace(/<thought>[\s\S]*?<\/thought>/gi, '').trim()
        resolve(cleaned || text)
      })
      const unbindError = window.api.ai.onError((data) => {
        if (data.requestId !== requestId) return
        cleanup()
        resolve('')
      })

      // 根据字段类型定制翻译提示
      const nameHint = characterName ? `\n- 角色名为「${characterName}」，其他字段中出现该名字时请一并翻译为中文` : ''
      const fieldHints: Record<string, string> = {
        '角色名': '- 这是角色名，请音译或意译为地道的中文名字',
        '角色描述': '- 这是角色外观/背景描写，使用自然流畅的中文叙述',
        '性格特征': '- 这是性格标签或描述，使用中文角色扮演圈常用表达（如"傲娇""腹黑"等），保留 {{char}} 等变量',
        '场景设定': '- 这是故事背景设定，使用中文同人/创作圈常见的叙述风格',
        '首条消息': '- 这是角色初次见面对话/开场独白，保持人物语气和口吻风格，对话中的人名一并翻译',
        '对话示例': '- 这是示例对话，角色名和对话中的人名一并翻译，保持口语化风格，*动作描写*保留原格式',
      }
      const fieldHint = fieldHints[fieldLabel] || ''

      window.api.ai.chat({
        requestId,
        messages: [
          {
            role: 'system',
            content: [
              '你是一位资深的 AI 角色扮演本地化翻译专家，专门将英文角色卡精准翻译为中文。',
              '',
              '## 核心翻译原则',
              '- 角色名：音译或意译为自然的中文名字，不使用直译',
              '- 描述/设定：使用地道的中文表达，保持原文叙述风格',
              '- 对话：保持角色的语气、口吻、情感色彩，中文表达要口语化自然',
              '- 性格特征：使用中文角色扮演圈常用标签（如"傲娇""天然呆""腹黑""元气"等）',
              '- 保留所有 Markdown 格式、HTML 标签、特殊标记（{{user}}、{{char}}、*动作描写* 等）不变',
              '- 只输出翻译结果，禁止添加解释、备注或额外内容',
              '- 禁止输出 <thought> 标签或任何格式标记，只输出纯翻译文本',
              nameHint,
              '',
              `## 当前字段: ${fieldLabel}`,
              fieldHint,
            ].filter(Boolean).join('\n'),
          },
          { role: 'user', content: text },
        ],
        provider: profile.provider,
        apiKey: profile.apiKey,
        baseUrl: profile.baseUrl,
        model: settings.activeModel || profile.model,
        temperature: 0.3,
        topP: 0.9,
        maxTokens: 4096,
        frequencyPenalty: 0,
        presencePenalty: 0,
        stream: true,
      }).catch(() => {
        cleanup()
        resolve('')
      })
    })
  }

  return (
    <Modal
      open
      onClose={onClose}
      title={character.name === '新角色' ? '创建角色' : '编辑角色'}
      width="lg"
      footer={
        <>
          <button className="btn-secondary" onClick={onClose}>取消</button>
          <button
            className="btn-secondary"
            onClick={handleAiTranslate}
            disabled={translating || translatingField !== null || !form.description}
            title={!form.description ? '请先填写角色描述' : '使用 AI 将角色卡翻译为中文'}
          >
            {translating ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                翻译中 ({translatedFields.size}/{TRANSLATABLE_FIELDS.filter(f => !!form[f.key]).length})
              </>
            ) : (
              <>
                <Languages className="w-4 h-4" />
                AI 翻译
              </>
            )}
          </button>
          <button className="btn-primary" onClick={handleSave}>保存</button>
        </>
      }
    >
      <div className="space-y-4">
        {/* 翻译错误提示 */}
        {translateError && (
          <div className="px-3 py-2 rounded bg-tavern-danger/10 border border-tavern-danger/30 text-sm text-tavern-danger">
            {translateError}
          </div>
        )}

        <IdentitySection
          form={form}
          update={update}
          tagInput={tagInput}
          setTagInput={setTagInput}
          handleAddTag={handleAddTag}
          handleRemoveTag={handleRemoveTag}
          handleImageSelect={handleImageSelect}
          handleReloadCover={handleReloadCover}
          coverReloading={coverReloading}
          coverError={coverError}
          avatarError={avatarError}
          setAvatarError={setAvatarError}
          taDesc={taDesc}
          taPersonality={taPersonality}
          translatedFields={translatedFields}
          translatingField={translatingField}
          handleTranslateField={handleTranslateField}
          handleTranslateGreeting={handleTranslateGreeting}
        />
        <AdvancedSection
          form={form}
          update={update}
          showAdvanced={showAdvanced}
          setShowAdvanced={setShowAdvanced}
          handleBackgroundSelect={handleBackgroundSelect}
          taScenario={taScenario}
          taSysprompt={taSysprompt}
          taFirstmsg={taFirstmsg}
          taPosthist={taPosthist}
          taExdialog={taExdialog}
          translatedFields={translatedFields}
          translatingField={translatingField}
          handleTranslateField={handleTranslateField}
          handleTranslateGreeting={handleTranslateGreeting}
        />
      </div>
    </Modal>
  )
}

import { useState, useEffect } from 'react'
import { X, Upload, Sun, Waves, Trees, Moon, Cloud, Flame, Image } from 'lucide-react'
import { useCharacterStore } from '../../store/useCharacterStore'
import { cn } from '../../lib/utils'

interface BackgroundPanelProps {
  open: boolean
  onClose: () => void
}

export const PRESET_GRADIENTS = [
  { key: 'sunset', label: '日落', icon: Sun, css: 'linear-gradient(135deg, #ff9a9e 0%, #fad0c4 50%, #fbc2eb 100%)' },
  { key: 'ocean', label: '海洋', icon: Waves, css: 'linear-gradient(135deg, #a18cd1 0%, #fbc2eb 50%, #8fd3f4 100%)' },
  { key: 'forest', label: '森林', icon: Trees, css: 'linear-gradient(135deg, #84fab0 0%, #8fd3f4 50%, #a8edea 100%)' },
  { key: 'midnight', label: '午夜', icon: Moon, css: 'linear-gradient(135deg, #2b2d42 0%, #8d99ae 50%, #edf2f4 100%)' },
  { key: 'cherry', label: '樱花', icon: Cloud, css: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 50%, #e8c3c8 100%)' },
  { key: 'ember', label: '余烬', icon: Flame, css: 'linear-gradient(135deg, #f7971e 0%, #ffd200 50%, #ffe259 100%)' },
] as const

export function BackgroundPanel({ open, onClose }: BackgroundPanelProps) {
  const { currentCharacter, saveCharacter } = useCharacterStore()
  const character = currentCharacter

  // hooks 必须在提前返回之前调用（React Hooks 规则）
  const params = character?.chatBackgroundParams ?? { opacity: 12, blur: 2, type: 'image' as const, posX: 50, posY: 50, scale: 100 }
  const useCover = params.useCover ?? false
  const [localOpacity, setLocalOpacity] = useState(params.opacity ?? 12)
  const [localBlur, setLocalBlur] = useState(params.blur ?? 2)

  // 面板打开时同步本地状态（切换角色 / 重新打开时重置为角色当前值）
  useEffect(() => {
    if (open && character) {
      const p = character.chatBackgroundParams ?? { opacity: 12, blur: 2, type: 'image' as const, posX: 50, posY: 50, scale: 100 }
      setLocalOpacity(p.opacity ?? 12)
      setLocalBlur(p.blur ?? 2)
    }
  }, [open, character?.id])

  if (!open || !character) return null

  const opacity = params.opacity ?? 12
  const blur = params.blur ?? 2
  const bgType = params.type ?? 'image'
  const activeGradient = params.gradient
  const posX = params.posX ?? 50
  const posY = params.posY ?? 50
  const scale = params.scale ?? 100

  const updateBg = async (partial: Partial<NonNullable<typeof character.chatBackgroundParams>> & { chatBackground?: string | undefined }) => {
    const updated: typeof character = {
      ...character,
      chatBackground: partial.chatBackground !== undefined ? partial.chatBackground : character.chatBackground,
      chatBackgroundParams: {
        opacity: partial.opacity ?? opacity,
        blur: partial.blur ?? blur,
        type: partial.type ?? bgType,
        gradient: partial.gradient !== undefined ? partial.gradient : activeGradient,
        posX: partial.posX ?? posX,
        posY: partial.posY ?? posY,
        scale: partial.scale ?? scale,
        useCover: partial.useCover !== undefined ? partial.useCover : useCover,
      },
    }
    await saveCharacter(updated)
  }

  const saveSliderValues = () => {
    updateBg({ opacity: localOpacity, blur: localBlur })
  }

  const handleSelectGradient = (key: string) => {
    updateBg({ type: 'gradient', gradient: key, useCover: false })
  }

  const handleUseCover = () => {
    if (useCover) {
      handleRemove()
    } else {
      // 封面本身是清晰的，启用时把模糊重置为 0，避免继承手动背景的高模糊值
      updateBg({ chatBackground: undefined, type: 'image', gradient: undefined, useCover: true, blur: 0 })
      setLocalBlur(0)
    }
  }

  const handleSelectImage = async () => {
    const path = await window.api.file.selectImage()
    if (path) {
      const base64 = await window.api.file.readImageAsBase64(path)
      updateBg({ chatBackground: base64, type: 'image', gradient: undefined, useCover: false })
    }
  }

  const handleRemove = () => {
    updateBg({ chatBackground: undefined, gradient: undefined, type: 'image', useCover: false })
  }

  const handleOpacityChange = (val: number) => {
    setLocalOpacity(val)
  }

  const handleBlurChange = (val: number) => {
    setLocalBlur(val)
  }

  return (
    <>
      {/* 遮罩 */}
      <div className="fixed inset-0 z-30" onClick={onClose} />
      {/* 面板 */}
      <div className="fixed right-0 top-0 bottom-0 w-80 z-40 bg-tavern-bg-card border-l border-tavern-border shadow-2xl overflow-y-auto">
        <div className="sticky top-0 z-10 flex items-center justify-between px-4 py-3 bg-tavern-bg-card/90 backdrop-blur border-b border-tavern-border-soft">
          <h3 className="text-sm font-semibold text-tavern-text">聊天背景</h3>
          <button className="btn-ghost p-1.5" onClick={onClose} title="关闭">
            <X className="w-4 h-4" />
          </button>
        </div>

        <div className="p-4 space-y-5">
          {/* 预设渐变 */}
          <div>
            <label className="label">预设渐变</label>
            <div className="grid grid-cols-3 gap-2">
              {PRESET_GRADIENTS.map((g) => (
                <button
                  key={g.key}
                  onClick={() => handleSelectGradient(g.key)}
                  className={cn(
                    'flex flex-col items-center gap-1 p-2 rounded-lg border-2 transition-all',
                    activeGradient === g.key
                      ? 'border-tavern-accent shadow-md scale-105'
                      : 'border-tavern-border-soft hover:border-tavern-border hover:shadow-sm'
                  )}
                >
                  <div className="w-full aspect-video rounded-md" style={{ background: g.css }} />
                  <span className="text-[10px] text-tavern-text-soft leading-none">{g.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* 使用角色头像/封面 */}
          <div>
            <label className="label">使用角色封面</label>
              <button
                onClick={handleUseCover}
                className={cn(
                  'w-full flex items-center justify-center gap-2 px-3 py-3 rounded-lg border-2 transition-colors text-sm',
                  useCover
                    ? 'border-tavern-accent bg-tavern-accent-soft/30 text-tavern-accent'
                    : 'border-dashed border-tavern-border-soft text-tavern-text-muted hover:border-tavern-border hover:shadow-sm'
                )}
              >
                <Image className="w-4 h-4" />
                {useCover ? '已启用（点击取消）' : '设为封面背景'}
              </button>
            </div>

          {/* 自定义图片 */}
          <div>
            <label className="label">自定义图片</label>
            <button
              onClick={handleSelectImage}
              className={cn(
                'w-full flex items-center justify-center gap-2 px-3 py-3 rounded-lg border-2 border-dashed transition-colors text-sm',
                'border-tavern-border-soft text-tavern-text-muted hover:border-tavern-accent hover:text-tavern-accent hover:bg-tavern-accent-soft/30'
              )}
            >
              <Upload className="w-4 h-4" />
              {character.chatBackground && bgType === 'image' ? '更换图片' : '选择本地图片'}
            </button>
            {character.chatBackground && bgType === 'image' && (
              <div className="mt-2 w-full h-16 rounded-lg overflow-hidden border border-tavern-border-soft">
                <img src={character.chatBackground} className="w-full h-full object-cover" alt="" />
              </div>
            )}
          </div>

          {/* 不透明度 */}
          <div>
            <label className="label">
              不透明度 <span className="text-xs text-tavern-text-muted ml-1">{localOpacity}%</span>
            </label>
            <input
              type="range"
              min="1"
              max="100"
              step="1"
              value={localOpacity}
              onChange={(e) => handleOpacityChange(Number(e.target.value))}
              onMouseUp={saveSliderValues}
              onTouchEnd={saveSliderValues}
              className="w-full accent-tavern-accent"
            />
            <div className="flex justify-between text-[10px] text-tavern-text-muted">
              <span>淡</span>
              <span>浓</span>
            </div>
          </div>

          {/* 模糊 */}
          <div>
            <label className="label">
              模糊程度 <span className="text-xs text-tavern-text-muted ml-1">{localBlur}px</span>
            </label>
            <input
              type="range"
              min="0"
              max="8"
              step="1"
              value={localBlur}
              onChange={(e) => handleBlurChange(Number(e.target.value))}
              onMouseUp={saveSliderValues}
              onTouchEnd={saveSliderValues}
              className="w-full accent-tavern-accent"
            />
            <div className="flex justify-between text-[10px] text-tavern-text-muted">
              <span>清晰</span>
              <span>模糊</span>
            </div>
          </div>

          {/* 图片位置 */}
          {(character.chatBackground || useCover) && bgType === 'image' && (
            <div>
              <label className="label">图片位置</label>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <span className="text-[10px] text-tavern-text-muted">水平: {posX}%</span>
                  <input
                    type="range"
                    min="0"
                    max="100"
                    step="1"
                    value={posX}
                    onChange={(e) => updateBg({ posX: Number(e.target.value) })}
                    className="w-full accent-tavern-accent"
                  />
                </div>
                <div>
                  <span className="text-[10px] text-tavern-text-muted">垂直: {posY}%</span>
                  <input
                    type="range"
                    min="0"
                    max="100"
                    step="1"
                    value={posY}
                    onChange={(e) => updateBg({ posY: Number(e.target.value) })}
                    className="w-full accent-tavern-accent"
                  />
                </div>
              </div>
            </div>
          )}

          {/* 图片缩放 (仅图片模式) */}
          {(character.chatBackground || useCover) && bgType === 'image' && (
            <div>
              <label className="label">
                缩放 <span className="text-xs text-tavern-text-muted ml-1">{scale}%</span>
              </label>
              <input
                type="range"
                min="50"
                max="200"
                step="5"
                value={scale}
                onChange={(e) => updateBg({ scale: Number(e.target.value) })}
                className="w-full accent-tavern-accent"
              />
              <div className="flex justify-between text-[10px] text-tavern-text-muted">
                <span>缩小</span>
                <span>放大</span>
              </div>
            </div>
          )}

          {/* 移除背景 */}
          {(character.chatBackground || useCover) && (
            <div className="pt-2 border-t border-tavern-border-soft">
              <button
                onClick={handleRemove}
                className="w-full btn-ghost text-sm text-tavern-danger py-2"
              >
                移除背景
              </button>
            </div>
          )}
        </div>
      </div>
    </>
  )
}

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { ChevronDown, ArrowDownToLine, Eye, Sliders, Images, Image, Download, Trash2, Users, UserCircle, X, Plus, Star } from 'lucide-react'
import { useChatStore } from '../../store/useChatStore'
import { useCharacterStore } from '../../store/useCharacterStore'
import { charAssetUrl } from '../../utils/asset'
import { useSettingsStore } from '../../store/useSettingsStore'
import { usePersonaStore } from '../../store/usePersonaStore'
import { Dropdown } from '../common/Dropdown'
import { SessionSwitcher } from '../common/SessionSwitcher'
import { CharacterAvatar } from '../character/CharacterAvatar'
import { getDisplayName } from '../../utils/variables'
import { MemoryPanel } from './MemoryPanel'
import { TokenUsage } from './TokenUsage'
import { cn } from '../../lib/utils'
import type { Character, Message } from '../../../shared/types'

interface ChatHeaderProps {
  currentCharacter: Character
  messages: Message[]
  isStreaming: boolean
  totalChars: number
  showQuickSettings: boolean
  showBgPanel: boolean
  onExport: () => void
  onClearConfirm: () => void
  onShowContextViewer: () => void
  onShowQuickSettings: () => void
  onShowBgPanel: () => void
  onShowGreetingPicker: () => void
  onCreateSession: () => void
}

export function ChatHeader({
  currentCharacter,
  messages,
  isStreaming,
  totalChars,
  showQuickSettings,
  showBgPanel,
  onExport,
  onClearConfirm,
  onShowContextViewer,
  onShowQuickSettings,
  onShowBgPanel,
  onCreateSession,
}: ChatHeaderProps) {
  const navigate = useNavigate()
  const { sessions, currentSessionId, switchSession, deleteSession, renameSession, toggleMemory, setMemoryMode, triggerMemorySummary, getStats } = useChatStore()
  const { characters, selectCharacter } = useCharacterStore()
  const { settings, updateSettings } = useSettingsStore()
  const { personas, getPersona } = usePersonaStore()

  const [showCharMenu, setShowCharMenu] = useState(false)
  const [showPersonaMenu, setShowPersonaMenu] = useState(false)
  const [showMemoryPanel, setShowMemoryPanel] = useState(false)
  const [memoryStats, setMemoryStats] = useState<{ totalMessages: number; totalChars: number; durationStr: string } | null>(null)
  const [memoryInterval, setMemoryInterval] = useState(10)
  const [showImgHistory, setShowImgHistory] = useState(false)
  const [imgNotify, setImgNotify] = useState<string | null>(null)

  // 切换当前会话的身份
  const handleSwitchPersona = async (personaId: string | null) => {
    if (!currentCharacter || !currentSessionId) return
    await window.api.chat.updateSession(currentCharacter.id, currentSessionId, { personaId })
    useChatStore.setState(s => ({
      sessions: s.sessions.map(sess =>
        sess.id === currentSessionId ? { ...sess, personaId: personaId ?? undefined } : sess
      ),
    }))
    const persona = personaId ? getPersona(personaId) : undefined
    if (persona) {
      updateSettings({
        activePersonaId: persona.id,
        userName: persona.name,
        userDescription: persona.description,
        userPersona: persona.persona,
      })
    } else {
      updateSettings({
        activePersonaId: null,
        userName: '用户',
        userDescription: '',
        userPersona: '',
      })
    }
    setShowPersonaMenu(false)
  }

  return (
    <header className="relative z-30 flex items-center justify-between px-4 h-14 border-b border-tavern-border-soft bg-tavern-bg-soft shrink-0">
      <div className="flex items-center gap-3">
        {/* 角色选择下拉 */}
        <Dropdown
          open={showCharMenu}
          onOpenChange={setShowCharMenu}
          panelClassName="w-64 max-h-80 overflow-y-auto"
          trigger={
            <button className="flex items-center gap-2 px-2 py-1 rounded-lg hover:bg-tavern-bg-hover transition-colors">
              <CharacterAvatar
                avatar={currentCharacter.avatar || charAssetUrl(currentCharacter.id, 'avatar', currentCharacter.updatedAt)}
                name={getDisplayName(currentCharacter)}
                size="md"
                fallbackClassName="bg-tavern-assistant/20 text-tavern-assistant"
              />
              <div className="text-left">
                <div className="text-sm font-medium text-tavern-text">{getDisplayName(currentCharacter)}</div>
                <div className="text-xs text-tavern-text-muted">
                  {isStreaming ? '生成中...' : '在线'}
                </div>
              </div>
              <ChevronDown className="w-4 h-4 text-tavern-text-muted" />
            </button>
          }
        >
          {characters.length === 0 ? (
            <div className="px-4 py-3 text-sm text-tavern-text-muted text-center">
              暂无角色，请先创建
            </div>
          ) : (
            characters.map((char) => (
              <button
                key={char.id}
                onClick={() => {
                  selectCharacter(char.id)
                  setShowCharMenu(false)
                }}
                className={cn(
                  'w-full flex items-center gap-2 px-3 py-2 hover:bg-tavern-bg-hover transition-colors text-left',
                  char.id === currentCharacter.id && 'bg-tavern-accent-soft'
                )}
              >
                <CharacterAvatar
                  avatar={char.avatar || charAssetUrl(char.id, 'avatar', char.updatedAt)}
                  name={getDisplayName(char)}
                  size="md"
                />
                <div className="flex-1 min-w-0">
                  <div className="text-sm text-tavern-text truncate">{getDisplayName(char)}</div>
                  {char.tags[0] && (
                    <div className="text-xs text-tavern-text-muted truncate">{char.tags[0]}</div>
                  )}
                </div>
              </button>
            ))
          )}
          <div className="border-t border-tavern-border-soft mt-1 pt-1">
            <button
              onClick={() => {
                navigate('/characters')
                setShowCharMenu(false)
              }}
              className="w-full flex items-center gap-2 px-3 py-2 hover:bg-tavern-bg-hover transition-colors text-sm text-tavern-accent"
            >
              <Users className="w-4 h-4" />
              管理角色
            </button>
          </div>
        </Dropdown>

        {/* 身份切换器 */}
        <span className="text-tavern-border-soft select-none">|</span>
        <Dropdown
          open={showPersonaMenu}
          onOpenChange={setShowPersonaMenu}
          panelClassName="w-48 max-h-60 overflow-y-auto"
          trigger={
            <button
              className="flex items-center gap-1.5 px-2 py-1 rounded-lg hover:bg-tavern-bg-hover transition-colors text-sm"
              title="切换身份"
            >
              {(() => {
                const session = sessions.find(s => s.id === currentSessionId)
                const persona = getPersona(session?.personaId)
                if (persona?.avatar) {
                  return <img src={persona.avatar} alt="" className="w-5 h-5 rounded-full object-cover" />
                }
                return <UserCircle className="w-4 h-4 text-tavern-text-muted" />
              })()}
              <span className="max-w-[80px] truncate text-tavern-text-soft">
                {(() => {
                  const s = sessions.find(s => s.id === currentSessionId)
                  const p = getPersona(s?.personaId)
                  return p?.name ?? '身份'
                })()}
              </span>
              <ChevronDown className="w-3 h-3 text-tavern-text-muted" />
            </button>
          }
        >
          {(() => {
            const currentSession = sessions.find(s => s.id === currentSessionId)
            const currentPersonaId = currentSession?.personaId
            return (
              <>
                <button
                  className={cn(
                    'w-full flex items-center gap-2 px-3 py-2 hover:bg-tavern-bg-hover transition-colors text-sm text-tavern-text',
                    !currentPersonaId && 'bg-tavern-accent-soft'
                  )}
                  onClick={() => handleSwitchPersona(null)}
                >
                  <UserCircle className="w-4 h-4 text-tavern-text-muted" />
                  不使用身份
                  {!currentPersonaId && <span className="ml-auto text-tavern-accent text-xs">✓</span>}
                </button>
                {personas.map((p) => (
                  <button
                    key={p.id}
                    className={cn(
                      'w-full flex items-center gap-2 px-3 py-2 hover:bg-tavern-bg-hover transition-colors text-sm text-tavern-text',
                      currentPersonaId === p.id && 'bg-tavern-accent-soft'
                    )}
                    onClick={() => handleSwitchPersona(p.id)}
                  >
                    {p.avatar ? (
                      <img src={p.avatar} alt="" className="w-5 h-5 rounded-full object-cover" />
                    ) : (
                      <UserCircle className="w-4 h-4 text-tavern-text-muted" />
                    )}
                    <span className="truncate">{p.name}</span>
                    {settings.defaultPersonaId === p.id && (
                      <span title="默认身份" className="shrink-0">
                        <Star className="w-3 h-3 text-tavern-warning" />
                      </span>
                    )}
                    {currentPersonaId === p.id && <span className="ml-auto text-tavern-accent text-xs">✓</span>}
                  </button>
                ))}
              </>
            )
          })()}
        </Dropdown>

        {/* 会话切换器 + 长记忆按钮 */}
        <SessionSwitcher
          sessions={sessions}
          currentSessionId={currentSessionId}
          showPersona
          getPersona={getPersona}
          onSwitch={(id) => switchSession(id, currentCharacter)}
          onRename={(id, title) => renameSession(currentCharacter.id, id, title)}
          onDelete={(id) => deleteSession(currentCharacter.id, id)}
          onCreate={() => onCreateSession()}
          extra={<>
            {/* 新建会话按钮（Chat 风格） */}
            <button
              onClick={() => onCreateSession()}
              className="p-2 rounded-lg text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors"
              title="新建会话"
            >
              <Plus className="w-4 h-4" />
            </button>
            <MemoryPanel
              open={showMemoryPanel}
              onToggle={async () => {
                if (!showMemoryPanel && currentCharacter && currentSessionId) {
                  const stats = await getStats(currentCharacter.id, currentSessionId)
                  if (stats) setMemoryStats(stats)
                  const curS = sessions.find(s => s.id === currentSessionId)
                  setMemoryInterval(curS?.autoMemoryInterval ?? 10)
                }
                setShowMemoryPanel(!showMemoryPanel)
              }}
              sessions={sessions}
              currentSessionId={currentSessionId}
              currentCharacterId={currentCharacter?.id ?? null}
              memoryInterval={memoryInterval}
              onMemoryIntervalChange={setMemoryInterval}
              onToggleMemory={(enabled) => {
                if (currentCharacter && currentSessionId) toggleMemory(currentCharacter.id, currentSessionId, enabled)
              }}
              onSetMemoryMode={(mode, interval) => {
                if (currentCharacter && currentSessionId) setMemoryMode(currentCharacter.id, currentSessionId, mode, interval)
              }}
              onTriggerSummary={() => {
                if (currentCharacter) triggerMemorySummary(currentCharacter)
              }}
              isStreaming={isStreaming}
              memoryStats={memoryStats}
            />
          </>}
        />
      </div>

      {/* 操作按钮 */}
      <div className="flex items-center gap-1">
        <span className="mr-2"><TokenUsage chars={totalChars} /></span>
        <button
          onClick={() => updateSettings({ autoScroll: !settings.autoScroll })}
          className={cn(
            'p-2 rounded-lg transition-colors',
            settings.autoScroll
              ? 'text-tavern-accent bg-tavern-accent-soft'
              : 'text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover'
          )}
          title={settings.autoScroll ? '自动滚动：开' : '自动滚动：关'}
        >
          <ArrowDownToLine className="w-5 h-5" />
        </button>
        <button
          onClick={onShowContextViewer}
          className="p-2 rounded-lg text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors"
          title="查看上下文"
        >
          <Eye className="w-5 h-5" />
        </button>
        <button
          onClick={onShowQuickSettings}
          className={cn(
            'p-2 rounded-lg transition-colors',
            showQuickSettings
              ? 'text-tavern-accent bg-tavern-accent-soft'
              : 'text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover'
          )}
          title="快捷设置"
        >
          <Sliders className="w-5 h-5" />
        </button>
        {/* 生图历史 */}
        <div className="relative">
          <button
            onClick={() => setShowImgHistory(v => !v)}
            className={cn(
              'p-2 rounded-lg transition-colors',
              showImgHistory
                ? 'text-tavern-accent bg-tavern-accent-soft'
                : 'text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover'
            )}
            title="生图历史"
          >
            <Images className="w-5 h-5" />
          </button>
          {showImgHistory && (
            <>
              <div className="fixed inset-0 z-40" onClick={() => setShowImgHistory(false)} />
              <div className="absolute top-full right-0 mt-1 w-80 max-h-96 rounded-lg border border-tavern-border bg-tavern-bg-soft shadow-xl z-50 overflow-hidden">
                <div className="px-3 py-2 border-b border-tavern-border-soft flex items-center justify-between">
                  <span className="text-sm font-medium text-tavern-text">生图历史</span>
                  <button onClick={() => setShowImgHistory(false)} className="p-1 rounded hover:bg-tavern-bg-hover">
                    <X className="w-4 h-4 text-tavern-text-muted" />
                  </button>
                </div>
                <div className="overflow-y-auto max-h-80 p-2">
                  {(() => {
                    const imgMsgs = messages.filter(m => m.images && m.images.length > 0)
                    if (imgMsgs.length === 0) {
                      return <div className="text-center py-8 text-sm text-tavern-text-muted">暂无生图记录</div>
                    }
                    return (
                      <div className="grid grid-cols-3 gap-1.5">
                        {imgMsgs.flatMap(m => m.images).slice(-30).reverse().map((img, i) => (
                          <button
                            key={i}
                            onClick={() => {
                              navigator.clipboard.writeText(img)
                              setImgNotify('图片已复制')
                              setTimeout(() => setImgNotify(null), 2000)
                              setShowImgHistory(false)
                            }}
                            className="aspect-square rounded-lg overflow-hidden bg-tavern-bg-hover hover:ring-2 hover:ring-tavern-accent transition-all"
                            title="点击复制图片"
                          >
                            <img src={img} className="w-full h-full object-cover" alt="" />
                          </button>
                        ))}
                      </div>
                    )
                  })()}
                </div>
              </div>
            </>
          )}
        </div>
        <button
          onClick={onShowBgPanel}
          className={cn(
            'p-2 rounded-lg transition-colors',
            showBgPanel
              ? 'text-tavern-accent bg-tavern-accent-soft'
              : 'text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover'
          )}
          title="聊天背景"
        >
          <Image className="w-5 h-5" />
        </button>
        <button
          onClick={onExport}
          className="p-2 rounded-lg text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors"
          title="导出对话"
        >
          <Download className="w-5 h-5" />
        </button>
        <button
          onClick={onClearConfirm}
          className="p-2 rounded-lg text-tavern-text-muted hover:text-tavern-danger hover:bg-tavern-bg-hover transition-colors"
          title="清空对话"
        >
          <Trash2 className="w-5 h-5" />
        </button>
      </div>
    </header>
  )
}

import { useState, useRef, useEffect, KeyboardEvent } from 'react'
import { Send, Square, ImagePlus, X, Sparkles, Loader2, Undo2, Wand2, Reply } from 'lucide-react'
import { cn } from '../../lib/utils'
import { useChatStore } from '../../store/useChatStore'
import { lorebookCache } from '../../utils/lorebook'
import { useSettingsStore } from '../../store/useSettingsStore'
import { useCharacterStore } from '../../store/useCharacterStore'
import { downloadFile } from '../../utils/download'
import { logError } from '../../lib/logger'
import { isLocalProvider } from '../../utils/defaults'
import { getDisplayName } from '../../utils/variables'
import { expandMacros, buildMacroContext } from '../../utils/macros'
import { getEffectiveQuickReplies } from '../../utils/quickReply'
import type { Character, Preset, Lorebook, ChatParams, QuickReply, QuickReplyStore, Message } from '../../../shared/types'
import { findCommand, listCommands, type CommandContext } from '../../commands/registry'
import { parseCommand } from '../../commands/parser'
import { registerBuiltinCommands } from '../../commands/builtin'
import { stripThought } from '../../utils/messagePostProcess'

// 初始化内置命令（只执行一次）
let commandsInitialized = false
function ensureCommandsInitialized() {
  if (!commandsInitialized) {
    registerBuiltinCommands()
    commandsInitialized = true
  }
}

interface ChatInputProps {
  character: Character
  disabled?: boolean
  /** 引用回复：被引用消息（P1-5） */
  replyTo?: Message | null
  onCancelReply?: () => void
}

/** 草稿存储 key（按角色 ID + 会话 ID 隔离） */
function draftKey(characterId: string, sessionId?: string | null) {
  return `chat-draft:${characterId}:${sessionId || 'default'}`
}

export function ChatInput({ character, disabled, replyTo, onCancelReply }: ChatInputProps) {
  // 初始化内置命令
  ensureCommandsInitialized()

  const [text, setText] = useState(() => {
    // 启动时恢复草稿
    try {
      return localStorage.getItem(draftKey(character.id, currentSessionId)) ?? ''
    } catch {
      return ''
    }
  })
  const [images, setImages] = useState<string[]>([])
  const [isAiProcessing, setIsAiProcessing] = useState(false)
  const [originalText, setOriginalText] = useState<string | null>(null)
  // 命令补全建议
  const [commandSuggestions, setCommandSuggestions] = useState<Array<{ name: string; description: string; usage: string }>>([])
  const [selectedSuggestionIdx, setSelectedSuggestionIdx] = useState(0)
  const [imageMenuOpen, setImageMenuOpen] = useState(false)
  // 短暂通知（命令执行反馈）
  const [notification, setNotification] = useState<string | null>(null)
  const notificationTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  // 快捷回复
  const [qrStore, setQrStore] = useState<QuickReplyStore>({ global: [], byCharacter: {} })
  const textareaRef = useRef<HTMLTextAreaElement>(null)
  // H-09 修复：追踪活跃的 AI 辅助请求，组件卸载时取消
  const activeRequestIdsRef = useRef<Set<string>>(new Set())
  const { sendMessage, isStreaming, stopStreaming, activePresetId, activeLorebookIds, currentSessionId } = useChatStore()
  const { settings, getActiveProfile } = useSettingsStore()
  const { characters, selectCharacter } = useCharacterStore()

  const activeProfile = getActiveProfile()
  const isConnected = activeProfile !== null && (isLocalProvider(activeProfile.provider) || !!activeProfile.apiKey)

  // 快捷回复按钮：角色/会话切换时刷新
  useEffect(() => {
    let canceled = false
    window.api.quickReply.listAll().then((s) => {
      if (!canceled) setQrStore(s)
    }).catch(() => { /* 忽略 */ })
    return () => { canceled = true }
  }, [character.id, currentSessionId])

  const effectiveReplies = getEffectiveQuickReplies(qrStore, character.id)

  /** 执行一条快捷回复（宏展开 + 动作分发） */
  const runQuickReply = async (qr: QuickReply) => {
    try {
      // 消费当前引用（快捷回复发送时清除引用条）
      if (replyTo) onCancelReply?.()
      if (qr.action === 'preset' && qr.presetId) {
        useChatStore.getState().setActivePreset(qr.presetId, character.id)
        showNotification('已切换预设')
        return
      }
      if (qr.action === 'command' && qr.command?.trim().startsWith('/')) {
        const parsed = parseCommand(qr.command.trim())
        const cmd = parsed && findCommand(parsed.name)
        if (cmd) {
          await cmd.execute(parsed.args, buildCommandContext())
          return
        }
      }
      // text：宏展开后发送
      const chatStore = useChatStore.getState()
      const macroCtx = buildMacroContext(chatStore.messages, {
        userName: settings.userName || '用户',
        charName: character.name,
        originalCharName: character.translatedContent?.name,
      })
      const content = expandMacros(qr.content, macroCtx).trim()
      if (!content) return
      if (qr.sendWithAI) {
        const [preset, lorebooks] = await loadActivePresetLorebook()
        await chatStore.sendMessage(content, [], character, preset, lorebooks)
      } else {
        await chatStore.addStandaloneMessage(content, [], character, 'user')
      }
    } catch (e) {
      showNotification(`快捷回复执行失败: ${(e as Error).message}`)
    }
  }

  // 显示通知（3 秒后自动消失）
  const showNotification = (msg: string) => {
    setNotification(msg)
    if (notificationTimerRef.current) clearTimeout(notificationTimerRef.current)
    notificationTimerRef.current = setTimeout(() => setNotification(null), 3000)
  }

  // 构建命令上下文
  const buildCommandContext = (): CommandContext => {
    const chatStore = useChatStore.getState()
    return {
      character,
      sendMessage: async (content, imgs) => {
        const [preset, lorebooks] = await loadActivePresetLorebook()
        await chatStore.sendMessage(content, imgs, character, preset, lorebooks)
      },
      addImageMessage: async (imgs, content) => {
        await chatStore.addStandaloneMessage(content ?? '', imgs, character, 'system')
      },
      clearChat: async () => {
        await chatStore.clearChat(character.id)
      },
      regenerateLastMessage: async () => {
        const messages = chatStore.messages
        const lastAssistant = [...messages].reverse().find(m => m.role === 'assistant')
        if (!lastAssistant) {
          showNotification('没有可重新生成的 AI 回复')
          return
        }
        const [preset, lorebooks] = await loadActivePresetLorebook()
        await chatStore.regenerateMessage(lastAssistant.id, character, preset, lorebooks)
      },
      continueLastMessage: async () => {
        const messages = chatStore.messages
        const lastMsg = messages[messages.length - 1]
        // continueMessage 要求目标是最后一条消息且为 assistant
        if (!lastMsg || lastMsg.role !== 'assistant') {
          showNotification('最后一条消息不是 AI 回复，无法续写')
          return
        }
        const [preset, lorebooks] = await loadActivePresetLorebook()
        await chatStore.continueMessage(lastMsg.id, character, preset, lorebooks)
      },
      triggerMemorySummary: async () => {
        const result = await chatStore.triggerMemorySummary(character)
        if (result) showNotification('长记忆总结已完成')
        else showNotification('长记忆总结失败或消息太少')
      },
      exportChat: async (format) => {
        const sid = chatStore.currentSessionId
        if (!sid) return
        const content = await window.api.chat.exportChat(character.id, sid, format)
        const mimeType = format === 'json' ? 'application/json' : 'text/markdown'
        const ext = format === 'json' ? 'json' : 'md'
        downloadFile(content, `${character.name}-对话.${ext}`, mimeType)
        showNotification(`已导出为 ${format.toUpperCase()} 格式`)
      },
      swipeMessage: async (direction) => {
        const messages = chatStore.messages
        const lastAssistant = [...messages].reverse().find(m => m.role === 'assistant')
        if (!lastAssistant) {
          showNotification('没有可切换的 AI 回复')
          return
        }
        await chatStore.swipeMessage(lastAssistant.id, direction, character)
      },
      notify: showNotification,
      switchCharacter: async (nameOrId) => {
        const target = characters.find(c => c.id === nameOrId || c.name === nameOrId)
        if (target) {
          selectCharacter(target.id)
          showNotification(`已切换到角色: ${target.name}`)
          return true
        }
        showNotification(`未找到角色: ${nameOrId}`)
        return false
      },
      switchPreset: async (nameOrId) => {
        try {
          const presets = await window.api.preset.list()
          const target = presets.find((p: any) => p.id === nameOrId || p.name === nameOrId)
          if (target) {
            chatStore.setActivePreset(target.id, character.id)
            showNotification(`已切换到预设: ${target.name}`)
            return true
          }
        } catch { /* ignore */ }
        showNotification(`未找到预设: ${nameOrId}`)
        return false
      },
      switchPersona: async (nameOrId) => {
        try {
          const personas = await window.api.persona.list()
          const target = personas.find((p: any) => p.id === nameOrId || p.name === nameOrId)
          if (target) {
            // 同步 persona 到 settings（与 ChatHeader.handleSwitchPersona 保持一致）
            useSettingsStore.getState().updateSettings({
              activePersonaId: target.id,
              userName: target.name,
              userDescription: target.description,
              userPersona: target.persona,
            })
            // 保存到当前会话
            if (chatStore.currentSessionId) {
              await window.api.chat.updateSession(character.id, chatStore.currentSessionId, { personaId: target.id })
              useChatStore.setState(s => ({
                sessions: s.sessions.map(sess =>
                  sess.id === chatStore.currentSessionId ? { ...sess, personaId: target.id } : sess
                ),
              }))
            }
            showNotification(`已切换到人设: ${target.name}`)
            return true
          }
        } catch { /* ignore */ }
        showNotification(`未找到人设: ${nameOrId}`)
        return false
      },
      toggleLorebook: async (nameOrId) => {
        try {
          const lorebooks = await window.api.lorebook.list()
          const target = lorebooks.find((lb: any) => lb.id === nameOrId || lb.name === nameOrId)
          if (target) {
            const curIds = chatStore.activeLorebookIds
            if (curIds.includes(target.id)) {
              chatStore.setActiveLorebooks(curIds.filter(id => id !== target.id), character.id)
              showNotification(`已关闭世界书: ${target.name}`)
            } else {
              chatStore.setActiveLorebooks([...curIds, target.id], character.id)
              showNotification(`已激活世界书: ${target.name}`)
            }
            return true
          }
        } catch { /* ignore */ }
        showNotification(`未找到世界书: ${nameOrId}`)
        return false
      },
      getTokenUsage: () => {
        const messages = chatStore.messages
        const total = messages.reduce((sum, m) => sum + (m.content?.length ?? 0), 0)
        return { total, max: 0 }
      },
      callAiHelper: async (systemPrompt, userContent, options) => {
        return callAiHelper({
          systemPrompt,
          userContent,
          temperature: options?.temperature,
          maxTokens: options?.maxTokens,
        })
      },
      getRecentMessages: (count) => {
        return chatStore.messages
          .filter(m => m.content && m.content.trim())
          .slice(-count)
          .map(m => ({
            role: m.role as 'user' | 'assistant',
            content: m.content,
            name: m.role === 'user' ? (settings.userName || '用户') : character.name,
          }))
      },
      userName: settings.userName || '用户',
    }
  }

  // 命令补全：检测 / 开头时显示建议
  useEffect(() => {
    if (!text.startsWith('/')) {
      setCommandSuggestions([])
      setSelectedSuggestionIdx(0)
      return
    }
    const parsed = parseCommand(text)
    if (!parsed) return
    // 命令名补全（输入 /cl 时提示 /clear）
    if (!text.includes(' ')) {
      const matches = listCommands()
        .filter(c => c.name.startsWith(parsed.name))
        .map(c => ({ name: c.name, description: c.description, usage: c.usage }))
      setCommandSuggestions(matches)
      setSelectedSuggestionIdx(0)
      return
    }
    // 参数补全（命令已确定）
    const cmd = findCommand(parsed.name)
    if (cmd?.args?.[0]?.complete) {
      const ctx = buildCommandContext()
      const lastArg = parsed.args[parsed.args.length - 1] ?? ''
      Promise.resolve(cmd.args[0].complete(lastArg, ctx)).then(options => {
        setCommandSuggestions(options.map(o => ({ name: o, description: '', usage: '' })))
        setSelectedSuggestionIdx(0)
      })
    } else {
      setCommandSuggestions([])
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text])

  // 切换角色/会话时重新加载草稿
  useEffect(() => {
    try {
      setText(localStorage.getItem(draftKey(character.id, currentSessionId)) ?? '')
    } catch {
      setText('')
    }
    setImages([])
    setOriginalText(null)
  }, [character.id, currentSessionId])

  // 自动保存草稿（防抖）
  useEffect(() => {
    if (!text) {
      try { localStorage.removeItem(draftKey(character.id, currentSessionId)) } catch { /* ignore */ }
      return
    }
    const timer = setTimeout(() => {
      try { localStorage.setItem(draftKey(character.id, currentSessionId), text) } catch { /* ignore */ }
    }, 300)
    return () => clearTimeout(timer)
  }, [text, character.id, currentSessionId])

  // P-10 修复：用 requestAnimationFrame 避免同步 reflow
  useEffect(() => {
    if (textareaRef.current) {
      requestAnimationFrame(() => {
        if (textareaRef.current) {
          textareaRef.current.style.height = 'auto'
          textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 200) + 'px'
        }
      })
    }
  }, [text])

  // H-09 修复：组件卸载时取消所有活跃的 AI 辅助请求并清理 IPC 监听器
  useEffect(() => {
    return () => {
      const ids = Array.from(activeRequestIdsRef.current)
      for (const id of ids) {
        window.api.ai.cancelChat(id).catch((e) => logError('ChatInput:cancelChat', e))
      }
      activeRequestIdsRef.current.clear()
    }
  }, [])

  /** 加载当前选中的预设和所有激活的世界书（同时更新缓存） */
  const loadActivePresetLorebook = async (): Promise<[Preset | null, Lorebook[]]> => {
    let preset: Preset | null = null
    if (activePresetId) {
      const presets = await window.api.preset.list()
      preset = presets.find(p => p.id === activePresetId) ?? null
    }
    let lorebooks: Lorebook[] = []
    if (activeLorebookIds.length > 0) {
      lorebooks = (await lorebookCache.refresh(activeLorebookIds)).filter(lb => lb.enabled)
    } else {
      lorebookCache.clear()
    }
    return [preset, lorebooks]
  }

  const handleSend = async () => {
    if (!text.trim() || isStreaming) return

    // 命令解析：以 / 开头优先尝试作为命令执行
    if (text.startsWith('/')) {
      const parsed = parseCommand(text)
      if (parsed) {
        const cmd = findCommand(parsed.name)
        if (cmd) {
          setText('')
          setImages([])
          setOriginalText(null)
          setCommandSuggestions([])
          try { localStorage.removeItem(draftKey(character.id, currentSessionId)) } catch { /* ignore */ }
          try {
            await cmd.execute(parsed.args, buildCommandContext())
          } catch (err) {
            showNotification(`命令执行失败: ${(err as Error).message}`)
          }
          return
        }
        // 未知命令：作为普通消息发送（让 AI 看到 /xxx）
      }
    }

    // 普通消息发送
    const content = text.trim()
    const imgs = [...images]
    setText('')
    setImages([])
    setOriginalText(null)
    // 清除草稿
    try { localStorage.removeItem(draftKey(character.id, currentSessionId)) } catch { /* ignore */ }
    const [preset, lorebooks] = await loadActivePresetLorebook()
    const replyId = replyTo?.id ?? undefined
    onCancelReply?.()
    await sendMessage(content, imgs, character, preset, lorebooks, replyId)
  }

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    // 命令补全：Tab 补全第一个建议
    if (e.key === 'Tab' && commandSuggestions.length > 0) {
      e.preventDefault()
      const suggestion = commandSuggestions[selectedSuggestionIdx]
      if (suggestion) {
        // 命令名补全：替换整个命令名
        if (!text.includes(' ')) {
          setText('/' + suggestion.name + ' ')
        } else {
          // 参数补全：替换最后一个参数
          const parts = text.split(' ')
          parts[parts.length - 1] = suggestion.name
          setText(parts.join(' ') + ' ')
        }
        setCommandSuggestions([])
      }
      return
    }
    // 上下方向键选择建议
    if (commandSuggestions.length > 0 && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
      e.preventDefault()
      const delta = e.key === 'ArrowDown' ? 1 : -1
      setSelectedSuggestionIdx(prev =>
        (prev + delta + commandSuggestions.length) % commandSuggestions.length
      )
      return
    }
    // Esc 关闭建议
    if (e.key === 'Escape' && commandSuggestions.length > 0) {
      e.preventDefault()
      setCommandSuggestions([])
      return
    }
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
    // 快捷回复快捷键：Ctrl+1..9
    if ((e.ctrlKey || e.metaKey) && !e.shiftKey && !e.altKey && /^[1-9]$/.test(e.key) && effectiveReplies.length > 0) {
      e.preventDefault()
      const hotkey = Number(e.key)
      const qr = effectiveReplies.find((q) => q.hotkey === hotkey)
      if (qr && !isStreaming) {
        runQuickReply(qr)
      }
    }
  }

  const handleImageSelect = async () => {
    try {
      const path = await window.api.file.selectImage()
      if (path) {
        const base64 = await window.api.file.readImageAsBase64(path)
        setImages((prev) => [...prev, base64])
      }
    } catch (err) {
      logError('ChatInput:selectImage', err)
    }
  }

  const removeImage = (index: number) => {
    setImages((prev) => prev.filter((_, i) => i !== index))
  }

  /**
   * 抽取的公共 AI 辅助调用方法（修复 handleAiContinue / handleAiPolish 重复代码）
   * @returns AI 生成的完整文本
   */
  const callAiHelper = async (opts: {
    systemPrompt: string
    userContent: string
    temperature?: number
    maxTokens?: number
    onChunk?: (delta: string, full: string) => void
  }): Promise<string> => {
    const p = getActiveProfile()
    if (!p) throw new Error('未配置 API 连接')
    const [preset] = await loadActivePresetLorebook()
    let result = ''
    const requestId = `ai-helper-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
    activeRequestIdsRef.current.add(requestId)

    return new Promise<string>((resolve, reject) => {
      const cleanup = () => {
        activeRequestIdsRef.current.delete(requestId)
        unbindChunk(); unbindDone(); unbindError()
      }
      const cleanResult = () => stripThought(result)
      const unbindChunk = window.api.ai.onChunk((data) => {
        if (data.requestId !== requestId) return
        result += data.text
        opts.onChunk?.(data.text, cleanResult())
      })
      const unbindDone = window.api.ai.onDone((doneId) => {
        if (doneId !== requestId) return
        cleanup()
        resolve(cleanResult())
      })
      const unbindError = window.api.ai.onError((data) => {
        if (data.requestId !== requestId) return
        cleanup()
        reject(new Error(data.error))
      })

      const params: ChatParams = {
        requestId,
        messages: [
          { role: 'system', content: opts.systemPrompt },
          { role: 'user', content: opts.userContent },
        ],
        provider: p.provider,
        apiKey: p.apiKey,
        baseUrl: p.baseUrl,
        model: settings.activeModel || p.model,
        temperature: opts.temperature ?? preset?.temperature ?? 0.5,
        topP: preset?.topP ?? 0.9,
        maxTokens: opts.maxTokens ?? 800,
        frequencyPenalty: preset?.frequencyPenalty ?? 0,
        presencePenalty: preset?.presencePenalty ?? 0,
        stream: false,
      }

      window.api.ai.chat(params).catch((err) => {
        cleanup()
        reject(err)
      })
    })
  }

  /** AI 续写 */
  const handleAiContinue = async () => {
    if (isAiProcessing) return
    setIsAiProcessing(true)
    const originalInput = text
    try {
      const store = useChatStore.getState()
      const recentMessages = store.messages.slice(-6)
      const hasInput = originalInput.trim().length > 0
      const userName = settings.userName || '用户'
      const charName = getDisplayName(character)

      // 后处理：确保输出是用户视角，剥离角色视角内容
      const ensureUserPerspective = (raw: string): string => {
        let output = raw.trim()
        // 如果输出以角色名开头（含冒号），说明 AI 以角色身份回复了，剥离角色部分
        const charPrefix = new RegExp(`^\\*?${charName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*[:：]\\s*`, 'i')
        if (charPrefix.test(output)) {
          // 找到用户发言部分（如果有的话）
          const userLine = new RegExp(`(?:^|\\n)\\*?${userName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*[:：]\\s*(.*)`, 'i')
          const match = output.match(userLine)
          if (match) {
            output = match[1].trim()
          } else {
            // 没有用户部分，丢弃全部（AI 以角色视角回复了）
            return ''
          }
        }
        return output
      }

      const systemPrompt = hasInput
        ? `你是一个角色扮演对话的用户视角续写助手。你的任务是以【用户 ${userName}】的身份和口吻，续写用户未完成的消息。\n\n严格要求：\n- 只输出 ${userName} 的话语，绝对不要输出 ${charName} 的话语\n- 不要以 ${charName} 的身份说话或行动\n- 不要包含角色名前缀，直接输出对话内容\n- 保持用户一贯的语气和风格`
        : `你是一个角色扮演对话的用户视角续写助手。你的任务是以【用户 ${userName}】的身份和口吻，生成一条合适的用户回复。\n\n严格要求：\n- 只输出 ${userName} 的话语，绝对不要输出 ${charName} 的话语\n- 不要以 ${charName} 的身份说话或行动\n- 不要包含角色名前缀，直接输出对话内容\n- 保持用户一贯的语气和风格`

      const contextMessages: { role: 'system' | 'user' | 'assistant'; content: string }[] = [
        { role: 'system', content: `${systemPrompt}\n\n当前角色：${charName}\n角色设定：${character.description || '无'}\n场景：${character.scenario || '无'}` },
      ]
      for (const msg of recentMessages) {
        contextMessages.push({
          role: msg.role === 'user' ? 'user' : 'assistant',
          content: msg.content,
        })
      }
      contextMessages.push({
        role: 'user',
        content: hasInput ? `请以 ${userName} 的身份续写以下未完成的消息（直接接在后面的部分）：\n${originalInput}` : `请以 ${userName} 的身份根据上下文生成一条回复`,
      })

      const result = await callAiHelper({
        systemPrompt: contextMessages[0].content,
        userContent: contextMessages[contextMessages.length - 1].content,
        temperature: 0.7,
        maxTokens: 300,
        onChunk: (_delta, full) => {
          setText(hasInput ? originalInput + ensureUserPerspective(full) : ensureUserPerspective(full))
        },
      })
      const cleaned = ensureUserPerspective(result)
      if (cleaned) {
        setText(hasInput ? originalInput + cleaned : cleaned)
      } else {
        setText(originalInput)
      }
    } catch (err) {
      logError('ChatInput:continue', err)
      setText(originalInput)
    } finally {
      setIsAiProcessing(false)
    }
  }

  /** 润色 */
  const handleAiPolish = async () => {
    if (isAiProcessing || !text.trim()) return
    setOriginalText(text)
    setIsAiProcessing(true)

    try {
      const result = await callAiHelper({
        systemPrompt: '你是一个文字润色助手。请润色以下文本，修正语法、改善表达、使其更加流畅自然，但保持原意和语气不变。只输出润色后的文本，不要添加任何解释或额外内容。',
        userContent: text,
        temperature: 0.3,
        maxTokens: 800,
        onChunk: (_delta, full) => {
          setText(full)
        },
      })
      if (!result) setText(originalText)
    } catch (err) {
      logError('ChatInput:polish', err)
      setText(originalText!)
      setOriginalText(null)
    } finally {
      setIsAiProcessing(false)
    }
  }

  return (
    <div className="border-t border-tavern-border-soft bg-tavern-bg-soft px-4 py-3">
      {/* 图片预览 */}
      {images.length > 0 && (
        <div className="flex gap-2 mb-2 flex-wrap">
          {images.map((img, i) => (
            <div key={i} className="relative group">
              <img src={img} alt="" className="w-20 h-20 rounded-lg object-cover border border-tavern-border" />
              <button
                onClick={() => removeImage(i)}
                className="absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full bg-tavern-danger text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <X className="w-3 h-3" />
              </button>
            </div>
          ))}
        </div>
      )}

      {/* 回退按钮 */}
      {originalText !== null && (
        <div className="flex items-center justify-between mb-2 px-1">
          <span className="text-xs text-tavern-text-muted flex items-center gap-1">
            <Sparkles className="w-3 h-3 text-tavern-accent" />
            已润色
          </span>
          <button
            onClick={() => {
              setText(originalText)
              setOriginalText(null)
            }}
            className="flex items-center gap-1 px-2 py-1 rounded text-xs text-tavern-text-soft bg-tavern-bg-card border border-tavern-border-soft hover:border-tavern-accent hover:text-tavern-accent transition-colors"
          >
            <Undo2 className="w-3 h-3" />
            回退原文
          </button>
        </div>
      )}

      {/* 引用回复预览条（P1-5） */}
      {replyTo && (
        <div className="mb-2 flex items-center gap-2 px-3 py-1.5 rounded-lg bg-tavern-bg-soft border border-tavern-border-soft">
          <Reply className="w-3.5 h-3.5 text-tavern-accent shrink-0" />
          <div className="min-w-0 flex-1 text-xs">
            <span className="text-tavern-accent font-medium">
              {replyTo.role === 'user' ? (settings.userName || '用户') : character.name}:
            </span>
            <span className="text-tavern-text-muted ml-1 truncate">
              {replyTo.content.slice(0, 60)}
              {replyTo.content.length > 60 ? '...' : ''}
            </span>
          </div>
          <button
            onClick={onCancelReply}
            className="p-0.5 rounded text-tavern-text-muted hover:text-tavern-danger transition-colors shrink-0"
            title="取消引用"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {/* 快捷回复按钮栏 */}
      {effectiveReplies.length > 0 && (
        <div className="flex items-center flex-wrap gap-1.5 mb-2 px-1">
          {effectiveReplies.map((qr) => (
            <button
              key={qr.id}
              onClick={() => runQuickReply(qr)}
              disabled={isStreaming}
              title={qr.action === 'text'
                ? (qr.sendWithAI ? '发送并触发 AI 回复' : '仅发送消息')
                : qr.action === 'preset' ? '切换预设' : '触发命令'}
              className="px-2.5 py-1 rounded-lg text-xs border border-tavern-border-soft bg-tavern-bg-card text-tavern-text-soft hover:text-tavern-accent hover:border-tavern-accent disabled:opacity-50 transition-colors flex items-center gap-1"
            >
              {qr.hotkey != null && (
                <span className="text-[10px] text-tavern-text-muted">Ctrl+{qr.hotkey}</span>
              )}
              <span className="truncate max-w-[10rem]">{qr.label}</span>
            </button>
          ))}
        </div>
      )}

      {/* 输入框 */}
      <div className="flex items-center gap-2">
        <button
          onClick={handleImageSelect}
          className="p-2 rounded-lg text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors shrink-0"
          title="添加图片"
        >
          <ImagePlus className="w-5 h-5" />
        </button>

        <div className="relative shrink-0">
          <button
            onClick={() => setImageMenuOpen(v => !v)}
            className="p-2 rounded-lg text-tavern-text-muted hover:text-tavern-accent hover:bg-tavern-bg-hover transition-colors"
            title="AI 生图"
          >
            <Wand2 className="w-5 h-5" />
          </button>

          {imageMenuOpen && (
            <>
              <div className="fixed inset-0 z-40" onClick={() => setImageMenuOpen(false)} />
              <div className="absolute bottom-full left-0 mb-2 w-48 rounded-lg border border-tavern-border bg-tavern-bg-soft shadow-lg z-50 overflow-hidden">
                {[
                  { label: '当前场景', desc: '自动分析对话上下文', cmd: '/imagine' },
                  { label: '角色肖像', desc: '角色全身外观', cmd: '/imagine --mode character' },
                  { label: '面部特写', desc: '角色面部细节', cmd: '/imagine --mode face' },
                  { label: '场景背景', desc: '当前场景环境', cmd: '/imagine --mode background' },
                  { label: '自定义描述...', desc: '手动输入提示词', cmd: '/imagine ' },
                ].map((item) => (
                  <button
                    key={item.label}
                    className="w-full px-3 py-2 text-left hover:bg-tavern-bg-hover transition-colors border-b border-tavern-border-soft last:border-0"
                    onClick={() => {
                      setText(item.cmd)
                      setImageMenuOpen(false)
                      setTimeout(() => textareaRef.current?.focus(), 0)
                    }}
                  >
                    <div className="text-sm text-tavern-text">{item.label}</div>
                    <div className="text-[11px] text-tavern-text-muted">{item.desc}</div>
                  </button>
                ))}
              </div>
            </>
          )}
        </div>

        <div className="flex-1 relative">
          {/* 命令补全下拉 */}
          {commandSuggestions.length > 0 && (
            <div className="absolute bottom-full left-0 mb-2 max-w-md max-h-60 overflow-y-auto rounded-lg border border-tavern-border bg-tavern-bg-soft shadow-lg z-50">
              {commandSuggestions.map((s, i) => (
                <button
                  key={s.name}
                  className={cn(
                    'w-full px-3 py-2 text-left text-sm hover:bg-tavern-bg-hover flex items-center gap-2',
                    i === selectedSuggestionIdx && 'bg-tavern-bg-hover'
                  )}
                  onClick={() => {
                    if (!text.includes(' ')) {
                      setText('/' + s.name + ' ')
                    } else {
                      const parts = text.split(' ')
                      parts[parts.length - 1] = s.name
                      setText(parts.join(' ') + ' ')
                    }
                    setCommandSuggestions([])
                    textareaRef.current?.focus()
                  }}
                >
                  <span className="font-mono text-tavern-accent">
                    {text.includes(' ') ? s.name : '/' + s.name}
                  </span>
                  {s.description && (
                    <span className="text-xs text-tavern-text-muted truncate">{s.description}</span>
                  )}
                </button>
              ))}
              <div className="px-3 py-1 text-[10px] text-tavern-text-muted border-t border-tavern-border-soft">
                Tab 补全 · ↑↓ 选择 · Esc 关闭
              </div>
            </div>
          )}
          {/* 通知提示 */}
          {notification && (
            <div className="absolute bottom-full left-0 mb-2 px-3 py-1.5 rounded-lg bg-tavern-accent text-white text-xs shadow-lg z-50 animate-fade-in">
              {notification}
            </div>
          )}
          <textarea
            ref={textareaRef}
            autoFocus
            value={text}
            onChange={(e) => {
              setText(e.target.value)
              if (originalText !== null && e.target.value !== originalText) {
                setOriginalText(null)
              }
            }}
            onKeyDown={handleKeyDown}
            placeholder={
              !isConnected
                ? '请先在设置中配置 API 连接...'
                : isStreaming
                ? '正在生成回复...'
                : '输入消息，Enter 发送，Shift+Enter 换行'
            }
            disabled={disabled || isStreaming}
            rows={1}
            className="textarea w-full resize-none py-2.5 pr-3 leading-relaxed"
            style={{ minHeight: '42px', maxHeight: '200px' }}
          />
        </div>

        {/* AI 辅助按钮 */}
        {!isStreaming && (
          <div className="flex items-center gap-1 shrink-0">
            <button
              onClick={handleAiContinue}
              disabled={isAiProcessing}
              className={cn(
                'px-2.5 py-1.5 rounded-lg text-xs border transition-colors flex items-center gap-1',
                isAiProcessing
                  ? 'border-tavern-border-soft bg-tavern-bg-card text-tavern-text-muted cursor-not-allowed'
                  : 'border-tavern-border-soft bg-tavern-bg-card text-tavern-text-soft hover:text-tavern-accent hover:border-tavern-accent'
              )}
              title="AI 根据上下文续写输入文字"
            >
              {isAiProcessing ? (
                <Loader2 className="w-3 h-3 animate-spin" />
              ) : (
                <Sparkles className="w-3 h-3" />
              )}
              续写
            </button>
            {text.trim().length > 0 && (
              <button
                onClick={handleAiPolish}
                disabled={isAiProcessing}
                className={cn(
                  'px-2.5 py-1.5 rounded-lg text-xs border transition-colors flex items-center gap-1',
                  isAiProcessing
                    ? 'border-tavern-border-soft bg-tavern-bg-card text-tavern-text-muted cursor-not-allowed'
                    : 'border-tavern-border-soft bg-tavern-bg-card text-tavern-text-soft hover:text-tavern-accent hover:border-tavern-accent'
                )}
                title="AI 润色输入文字"
              >
                {isAiProcessing ? (
                  <Loader2 className="w-3 h-3 animate-spin" />
                ) : (
                  <Sparkles className="w-3 h-3" />
                )}
                润色
              </button>
            )}
          </div>
        )}

        {isStreaming ? (
          <button
            onClick={stopStreaming}
            className="p-2.5 rounded-lg bg-tavern-danger text-white hover:opacity-90 transition-opacity shrink-0"
            title="停止生成"
          >
            <Square className="w-5 h-5" fill="currentColor" />
          </button>
        ) : (
          <button
            onClick={handleSend}
            disabled={!text.trim() || !isConnected}
            className={cn(
              'p-2.5 rounded-lg transition-all shrink-0',
              text.trim() && isConnected
                ? 'btn-primary'
                : 'bg-tavern-bg-card text-tavern-text-muted cursor-not-allowed'
            )}
            title="发送"
          >
            <Send className="w-5 h-5" />
          </button>
        )}
      </div>
    </div>
  )
}

import { useState, useRef, useEffect } from 'react'
import { useCharacterStore } from '../../store/useCharacterStore'
import { useGroupChatStore } from '../../store/useGroupChatStore'
import { cn } from '../../lib/utils'
import { charAssetUrl } from '../../utils/asset'
import {
  Send,
  Square,
  Repeat,
  Zap,
  AtSign,
  Image as ImageIcon,
  ChevronDown,
  X as XIcon,
  Reply,
  UserRound,
} from 'lucide-react'
import type { GroupChat, GroupMessage } from '../../../shared/types'

interface GroupChatInputProps {
  group: GroupChat
  replyTo?: GroupMessage | null
  onCancelReply?: () => void
}

const MODE_LABELS: Record<GroupChat['chatMode'], string> = {
  mention: '@点名',
  polling: '轮询',
  free: '自由',
}

export function GroupChatInput({ group, replyTo, onCancelReply }: GroupChatInputProps) {
  const [content, setContent] = useState('')
  const [showMention, setShowMention] = useState(false)
  const [showModeMenu, setShowModeMenu] = useState(false)
  const [targetCharId, setTargetCharId] = useState<string | null>(null)
  const [mentionFilter, setMentionFilter] = useState('')
  const [selectedImages, setSelectedImages] = useState<string[]>([])
  /** 自由发言模式：发言人切换（null = 用户，否则以指定角色身份插入消息） */
  const [freeSpeakerId, setFreeSpeakerId] = useState<string | null>(null)
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  const { characters } = useCharacterStore()
  const { sendMessage, isStreaming, stopStreaming } = useGroupChatStore()

  const members = group.memberIds
    .map(id => characters.find(c => c.id === id))
    .filter(Boolean) as NonNullable<typeof characters[number]>[]

  const targetChar = targetCharId ? members.find(m => m.id === targetCharId) : null

  // @mention 检测
  useEffect(() => {
    if (group.chatMode !== 'mention') return

    const lastAt = content.lastIndexOf('@')
    if (lastAt >= 0) {
      const afterAt = content.slice(lastAt + 1)
      // 不自动弹下拉框，仅在用户继续输入后过滤
      if (afterAt.length === 0 && !showMention) return
      setMentionFilter(afterAt)
      setShowMention(true)
    } else {
      setShowMention(false)
    }
  }, [content, group.chatMode])

  const filteredMembers = members.filter(m =>
    m.name.toLowerCase().includes(mentionFilter.toLowerCase())
  )

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const selectMention = (charId: string, _name: string) => {
    setTargetCharId(charId)
    // 移除 @name 部分
    const lastAt = content.lastIndexOf('@')
    if (lastAt >= 0) {
      const before = content.slice(0, lastAt)
      setContent(before.trimEnd())
    }
    setShowMention(false)
  }

  const handleSend = async () => {
    if (!content.trim() || isStreaming) return
    const trimmed = content.trim()
    const images = [...selectedImages]
    const replyToId = replyTo?.id ?? null

    // 自由发言视角切换：以指定角色身份插入消息（不触发 AI 回复）
    if (group.chatMode === 'free' && freeSpeakerId) {
      setContent('')
      setSelectedImages([])
      resetTextareaHeight()
      onCancelReply?.()
      await useGroupChatStore.getState().insertCharacterMessage(freeSpeakerId, trimmed)
      return
    }

    if (group.chatMode === 'mention' && !targetCharId) {
      // 未点名则默认第一个成员
      const firstMember = members[0]
      if (!firstMember) {
        return
      }
      setContent('')
      setSelectedImages([])
      setTargetCharId(null)
      resetTextareaHeight()
      onCancelReply?.()
      await sendMessage(trimmed, images, firstMember.id, replyToId)
    } else {
      setContent('')
      setSelectedImages([])
      setTargetCharId(null)
      resetTextareaHeight()
      onCancelReply?.()
      await sendMessage(trimmed, images, targetCharId ?? undefined, replyToId)
    }
  }

  const resetTextareaHeight = () => {
    const el = textareaRef.current
    if (el) {
      el.style.height = 'auto'
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }

  const handleSelectImage = async () => {
    const path = await window.api.file.selectImage()
    if (path) {
      const base64 = await window.api.file.readImageAsBase64(path)
      if (base64) {
        setSelectedImages(prev => [...prev, base64])
      }
    }
  }

  const changeMode = async (mode: GroupChat['chatMode']) => {
    const store = useGroupChatStore.getState()
    await store.saveGroup({ ...group, chatMode: mode })
    setShowModeMenu(false)
    setTargetCharId(null)
  }

  return (
    <div className="border-t border-tavern-border-soft bg-tavern-bg-soft/80 backdrop-blur p-3">
      {/* 模式指示栏 */}
      <div className="flex items-center gap-2 mb-2 px-1">
        {/* 模式切换 */}
        <div className="relative">
          <button
            onClick={() => setShowModeMenu(!showModeMenu)}
            className="flex items-center gap-1 px-2 py-0.5 text-xs rounded bg-tavern-bg-hover text-tavern-text-muted hover:text-tavern-text transition-colors"
          >
            {group.chatMode === 'polling' && group.autoMode ? (
              <Repeat className="w-3 h-3 text-tavern-success" />
            ) : group.chatMode === 'mention' ? (
              <AtSign className="w-3 h-3" />
            ) : (
              <Zap className="w-3 h-3" />
            )}
            {MODE_LABELS[group.chatMode]}
            <ChevronDown className="w-3 h-3" />
          </button>

          {showModeMenu && (
            <>
              <div className="fixed inset-0 z-20" onClick={() => setShowModeMenu(false)} />
              <div className="absolute bottom-full left-0 mb-1 w-36 bg-tavern-bg-card border border-tavern-border rounded-lg shadow-xl z-30 py-1">
                {(Object.entries(MODE_LABELS) as [GroupChat['chatMode'], string][]).map(([key, label]) => (
                  <button
                    key={key}
                    onClick={() => changeMode(key)}
                    className={cn(
                      'w-full text-left px-3 py-1.5 text-xs hover:bg-tavern-bg-hover transition-colors',
                      key === group.chatMode && 'text-tavern-accent font-medium'
                    )}
                  >
                    {label}
                  </button>
                ))}
              </div>
            </>
          )}
        </div>

        {/* polling 模式额外控件 */}
        {group.chatMode === 'polling' && (
          <button
            onClick={() => {
              useGroupChatStore.getState().saveGroup({ ...group, autoMode: !group.autoMode })
            }}
            className={cn(
              'px-2 py-0.5 text-xs rounded transition-colors',
              group.autoMode
                ? 'bg-tavern-success/10 text-tavern-success'
                : 'bg-tavern-bg-hover text-tavern-text-muted hover:text-tavern-text'
            )}
          >
            {group.autoMode ? <Repeat className="w-3 h-3 inline mr-0.5" /> : null}
            自动 {group.autoMode ? 'ON' : 'OFF'}
          </button>
        )}

        {/* 当前目标角色 */}
        {group.chatMode === 'mention' && targetChar && (
          <span className="text-xs text-tavern-accent bg-tavern-accent-soft px-1.5 py-0.5 rounded">
            @{targetChar.name}
          </span>
        )}

        {/* 轮数指示 */}
        {group.chatMode === 'polling' && group.autoMode && (
          <span className="text-[10px] text-tavern-text-muted ml-auto">
            每轮 {group.maxRounds} 次
          </span>
        )}

        {/* 成员快捷点名 */}
        {group.chatMode === 'mention' && (
          <div className="flex items-center gap-1 ml-auto">
            {members.slice(0, 4).map(m => (
              <button
                key={m.id}
                onClick={() => {
                  setTargetCharId(m.id)
                  setShowMention(false)
                }}
                className={cn(
                  'w-6 h-6 rounded-full flex items-center justify-center text-[10px] border transition-colors',
                  targetCharId === m.id
                    ? 'border-tavern-accent bg-tavern-accent-soft text-tavern-accent'
                    : 'border-tavern-border-soft text-tavern-text-muted hover:border-tavern-border'
                )}
                title={m.name}
              >
                {m.name[0]}
              </button>
            ))}
            {members.length > 4 && (
              <button
                onClick={() => setShowMention(true)}
                className="w-6 h-6 rounded-full bg-tavern-bg-hover text-[10px] text-tavern-text-muted hover:text-tavern-text"
              >
                +{members.length - 4}
              </button>
            )}
          </div>
        )}

        {/* 自由发言视角切换：以用户或指定角色身份发言 */}
        {group.chatMode === 'free' && (
          <div className="flex items-center gap-1 ml-auto">
            <button
              onClick={() => setFreeSpeakerId(null)}
              className={cn(
                'w-6 h-6 rounded-full flex items-center justify-center border transition-colors',
                freeSpeakerId === null
                  ? 'border-tavern-accent bg-tavern-accent-soft text-tavern-accent'
                  : 'border-tavern-border-soft text-tavern-text-muted hover:border-tavern-border'
              )}
              title="以用户身份发言（默认）"
            >
              <UserRound className="w-3 h-3" />
            </button>
            {members.map(m => (
              <button
                key={m.id}
                onClick={() => setFreeSpeakerId(m.id)}
                className={cn(
                  'w-6 h-6 rounded-full flex items-center justify-center text-[10px] border transition-colors',
                  freeSpeakerId === m.id
                    ? 'border-tavern-accent bg-tavern-accent-soft text-tavern-accent'
                    : 'border-tavern-border-soft text-tavern-text-muted hover:border-tavern-border'
                )}
                title={`以「${m.name}」身份发言`}
              >
                {m.name[0]}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* @mention 下拉 */}
      {showMention && filteredMembers.length > 0 && (
        <div className="mb-2 bg-tavern-bg-card border border-tavern-border rounded-lg shadow-lg max-h-32 overflow-y-auto">
          {filteredMembers.map(m => (
            <button
              key={m.id}
              onClick={() => selectMention(m.id, m.name)}
              className={cn(
                'w-full flex items-center gap-2 px-3 py-1.5 text-sm hover:bg-tavern-bg-hover transition-colors text-left',
                targetCharId === m.id && 'bg-tavern-accent-soft text-tavern-accent'
              )}
            >
              {(m.avatar || charAssetUrl(m.id, 'avatar', m.updatedAt)) ? (
                <img src={m.avatar || charAssetUrl(m.id, 'avatar', m.updatedAt)} className="w-5 h-5 rounded-full object-cover" alt="" />
              ) : (
                <div className="w-5 h-5 rounded-full bg-tavern-bg-hover flex items-center justify-center text-[10px] font-bold">
                  {m.name[0]}
                </div>
              )}
              <span>{m.name}</span>
            </button>
          ))}
        </div>
      )}

      {/* 引用回复预览条 */}
      {replyTo && (
        <div className="mb-2 flex items-center gap-2 px-3 py-1.5 rounded-lg bg-tavern-bg-soft border border-tavern-border-soft">
          <Reply className="w-3.5 h-3.5 text-tavern-accent shrink-0" />
          <div className="min-w-0 flex-1 text-xs">
            <span className="text-tavern-accent font-medium">
              {replyTo.characterId === '__user__'
                ? '用户'
                : (characters.find(c => c.id === replyTo.characterId)?.name ?? '未知')
            }:
            </span>
            <span className="text-tavern-text-muted ml-1 truncate">
              {replyTo.content.slice(0, 60)}
              {replyTo.content.length > 60 ? '...' : ''}
            </span>
          </div>
          <button
            onClick={onCancelReply}
            className="p-0.5 rounded text-tavern-text-muted hover:text-tavern-danger transition-colors shrink-0"
            title="取消引用"
          >
            <XIcon className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {/* 已选图片预览 */}
      {selectedImages.length > 0 && (
        <div className="flex gap-1.5 mb-2 flex-wrap">
          {selectedImages.map((img, i) => (
            <div key={i} className="relative">
              <img src={img} alt="" className="w-12 h-12 rounded-lg object-cover border border-tavern-border-soft" />
              <button
                onClick={() => setSelectedImages(prev => prev.filter((_, idx) => idx !== i))}
                className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-tavern-danger text-white flex items-center justify-center text-[8px]"
              >
                ×
              </button>
            </div>
          ))}
        </div>
      )}

      {/* 输入区 */}
      <div className="flex gap-2">
        <div className="flex-1 relative">
          <textarea
            ref={textareaRef}
            value={content}
            onChange={e => setContent(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={
              group.chatMode === 'mention'
                ? '输入消息，使用 @ 点名角色...'
                : '输入消息，所有角色将依次/自由回复...'
            }
            rows={1}
            className="w-full resize-none rounded-xl border border-tavern-border-soft bg-tavern-bg px-3 py-2.5 pr-10 text-sm text-tavern-text placeholder-tavern-text-muted/60 focus:outline-none focus:border-tavern-accent focus:ring-1 focus:ring-tavern-accent/30 transition-colors"
            style={{ minHeight: '42px', maxHeight: '120px' }}
            onInput={(e) => {
              // P-10 修复：用 requestAnimationFrame 避免同步 reflow
              const el = e.currentTarget
              requestAnimationFrame(() => {
                el.style.height = 'auto'
                el.style.height = Math.min(el.scrollHeight, 120) + 'px'
              })
            }}
          />
          <button
            onClick={handleSelectImage}
            className="absolute right-2 bottom-2 p-1 rounded text-tavern-text-muted hover:text-tavern-text transition-colors"
            title="上传图片"
          >
            <ImageIcon className="w-4 h-4" />
          </button>
        </div>

        {isStreaming ? (
          <button
            onClick={stopStreaming}
            className="shrink-0 w-10 h-10 rounded-xl bg-tavern-danger/20 text-tavern-danger hover:bg-tavern-danger/30 transition-colors flex items-center justify-center"
          >
            <Square className="w-4 h-4" />
          </button>
        ) : (
          <button
            onClick={handleSend}
            disabled={!content.trim()}
            className={cn(
              'shrink-0 w-10 h-10 rounded-xl flex items-center justify-center transition-colors',
              content.trim()
                ? 'bg-tavern-accent text-white hover:bg-tavern-accent/90'
                : 'bg-tavern-bg-hover text-tavern-text-muted cursor-not-allowed'
            )}
          >
            <Send className="w-4 h-4" />
          </button>
        )}
      </div>
    </div>
  )
}

import React, { useState, useRef, useEffect, useMemo } from 'react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import rehypeHighlight from 'rehype-highlight'
import rehypeRaw from 'rehype-raw'
import { charAssetUrl } from '../../utils/asset'
import { Edit2, Check, X, RotateCcw, Trash2, Copy, Volume2, VolumeX, Play, Pause, User, Bot, Languages, GitBranch, Loader2, ChevronLeft, ChevronRight, Image as ImageIcon, RefreshCw, ChevronsDown, Reply } from 'lucide-react'
import type { Message, Character } from '../../../shared/types'
import { useChatStore } from '../../store/useChatStore'
import { useSettingsStore } from '../../store/useSettingsStore'
import { usePersonaStore } from '../../store/usePersonaStore'
import { cn } from '../../lib/utils'
import { formatTime } from '../../utils/format'
import { countChars, formatCharCount } from '../../utils/charCounter'
import { remarkRoleplay } from '../../utils/remark-roleplay'
import { extractThought, stripThought, stripThoughtTags } from '../../utils/messagePostProcess'
import { getDisplayName } from '../../utils/variables'

interface MessageBubbleProps {
  message: Message
  character: Character | null
  isLast: boolean
  /** 被引用消息（P1-5 引用回复） */
  repliedMessage?: Message | null
  /** 触发引用该消息 */
  onReply?: () => void
}

import { MarkdownImage } from '../common/MarkdownImage'

const markdownComponents = { img: MarkdownImage }

// B-05：已播放过入场动画的消息 ID，避免虚拟滚动时反复播放
const animatedIds = new Set<string>()

export const MessageBubble = React.memo(function MessageBubble({ message, character, isLast, repliedMessage, onReply }: MessageBubbleProps) {
  const shouldAnimate = !animatedIds.has(message.id)
  // 首帧渲染后立即标记为已动画
  if (shouldAnimate) {
    animatedIds.add(message.id)
  }
  const [editing, setEditing] = useState(false)
  const [editContent, setEditContent] = useState(message.content)
  const [ttsState, setTtsState] = useState<'idle' | 'speaking' | 'paused'>('idle')
  const [imgErrors, setImgErrors] = useState<Set<number>>(new Set())
  const [avatarError, setAvatarError] = useState(false)
  const [zoomImage, setZoomImage] = useState<string | null>(null)
  const [regenerating, setRegenerating] = useState(false)
  const [continuing, setContinuing] = useState(false)
  /** OpenAI/Edge TTS 音频播放器（渲染进程播放 mp3） */
  const audioRef = useRef<HTMLAudioElement | null>(null)
  const textareaRef = useRef<HTMLTextAreaElement>(null)
  const editMessage = useChatStore(s => s.editMessage)
  const deleteMessage = useChatStore(s => s.deleteMessage)
  const regenerateMessage = useChatStore(s => s.regenerateMessage)
  const continueMessage = useChatStore(s => s.continueMessage)
  const swipeMessage = useChatStore(s => s.swipeMessage)
  const isStreaming = useChatStore(s => s.isStreaming)
  const translatingMessages = useChatStore(s => s.translatingMessages)
  const showTranslationIds = useChatStore(s => s.showTranslationIds)
  const translateMessage = useChatStore(s => s.translateMessage)
  const updateMessageImages = useChatStore(s => s.updateMessageImages)
  const { settings, getActiveTTS } = useSettingsStore()
  const [thoughtExpanded, setThoughtExpanded] = useState(settings.autoExpandThought ?? false)
  const { getPersona } = usePersonaStore()
  const persona = getPersona(settings.activePersonaId)
  const ttsConfig = getActiveTTS()

  // 系统语音完成事件：订阅主进程推送，播放结束自动复位（openai/edge 由 audio onended 处理）
  useEffect(() => {
    if (ttsConfig?.provider !== 'system') return
    const unsubscribe = window.api.tts.onState((state) => {
      if (state === 'idle') setTtsState('idle')
    })
    return unsubscribe
  }, [ttsConfig?.provider])

  // 全局翻译状态
  const transState = translatingMessages[message.id]
  const showTranslation = showTranslationIds.has(message.id)
  const isTranslating = transState?.status === 'translating'

  // P-3 修复：用 useMemo 缓存 thought 解析，避免每次渲染都执行正则循环
  const { thought, originalDisplay } = useMemo(() => {
    const { thought: t, content } = extractThought(message.content || '')
    return { thought: t, originalDisplay: content }
  }, [message.content])
  const isUser = message.role === 'user'
  const isSystem = message.role === 'system'
  const isStreamingThis = isStreaming && isLast && !isUser

  // 决定显示的文本
  const displayContent = useMemo(() => {
    if (showTranslation && transState?.content) {
      const cleaned = stripThought(transState.content)
      return cleaned || originalDisplay || ''
    }
    return originalDisplay || ''
  }, [showTranslation, transState?.content, originalDisplay])

  // B-05：纯图片消息，气泡不应撑满整行
  const hasOnlyImages = message.images?.length > 0 && !displayContent && !(thought && !isSystem)

  useEffect(() => {
    if (editing && textareaRef.current) {
      textareaRef.current.focus()
      textareaRef.current.style.height = 'auto'
      textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px'
    }
  }, [editing])

  const handleSaveEdit = async () => {
    if (character) {
      await editMessage(message.id, editContent, character)
    }
    setEditing(false)
  }

  const handleCopy = () => {
    navigator.clipboard.writeText(message.content)
  }

  const handleSpeak = async () => {
    if (!message.content) return
    // TTS 朗读前预处理：默认剥离内心想法（<thought> 块）；开启"朗读内心想法"时仅去掉标签、保留内容
    const speakText = settings.ttsReadThought
      ? stripThoughtTags(message.content)
      : stripThought(message.content)
    if (!speakText.trim()) return
    if (!ttsConfig) return    // OpenAI / Edge TTS：渲染进程直接控制音频播放（主进程返回 mp3 base64）
    if (ttsConfig.provider === 'openai' || ttsConfig.provider === 'edge') {
      if (ttsState === 'speaking') {
        audioRef.current?.pause()
        setTtsState('paused')
        return
      }
      if (ttsState === 'paused') {
        await audioRef.current?.play()
        setTtsState('speaking')
        return
      }
      const res = await window.api.tts.speak(
        speakText,
        ttsConfig.provider === 'edge'
          ? {
              provider: 'edge',
              voice: ttsConfig.voice || 'zh-CN-XiaoxiaoNeural',
              rate: 1,
              // 代理按 TTS 配置（留空直连；代理失败主进程自动回退直连）
              proxy: ttsConfig.proxy || undefined,
            }
          : {
              provider: 'openai',
              voice: ttsConfig.voice || 'alloy',
              rate: 1,
              model: ttsConfig.model,
              apiKey: ttsConfig.apiKey,
              baseUrl: ttsConfig.baseUrl,
            },
      )
      if (res.success && res.audioBase64) {
        const audio = new Audio(`data:audio/mp3;base64,${res.audioBase64}`)
        audio.onended = () => setTtsState('idle')
        audio.onerror = () => setTtsState('idle')
        audioRef.current = audio
        setTtsState('speaking')
        await audio.play().catch(() => setTtsState('idle'))
      } else {
        setTtsState('idle')
      }
      return
    }

    if (ttsState === 'speaking') {
      await window.api.tts.pause()
      setTtsState('paused')
    } else if (ttsState === 'paused') {
      await window.api.tts.resume()
      setTtsState('speaking')
    } else {
      await window.api.tts.speak(speakText, {
        provider: ttsConfig.provider,
        voice: ttsConfig.voice,
        rate: 1,
      })
      setTtsState('speaking')
    }
  }

  const handleStopSpeak = async () => {
    audioRef.current?.pause()
    audioRef.current = null
    await window.api.tts.stop()
    setTtsState('idle')
  }

  const handleTranslate = () => {
    if (!message.content || isTranslating) return
    // 如果已有翻译结果，切换显示
    if (transState?.status === 'done') {
      // 如果还没显示翻译，先切换为显示
      if (!showTranslation) {
        useChatStore.getState().toggleTranslation(message.id)
      } else {
        // 已显示翻译，切换回原文
        useChatStore.getState().toggleTranslation(message.id)
      }
      return
    }
    // 发起翻译
    translateMessage(message.id, message.content)
    // 翻译开始后自动显示
    useChatStore.getState().toggleTranslation(message.id)
  }

  const handleBranch = async () => {
    if (!character) return
    // 创建新会话作为分支
    const branchSession = await window.api.chat.createSession(character.id, `分支: ${message.content.slice(0, 20)}...`)
    if (!branchSession) return
    const { messages } = useChatStore.getState()
    const branchIdx = messages.findIndex((m) => m.id === message.id)
    if (branchIdx < 0) return
    const branchMsgs = messages.slice(0, branchIdx + 1)
    for (const msg of branchMsgs) {
      const branchMsg = { ...msg, id: `${msg.id}_b`, sessionId: branchSession.id, characterId: character.id }
      await window.api.chat.saveMessage(branchMsg)
    }
    // 刷新会话列表
    const sessions = await window.api.chat.listSessions(character.id)
    useChatStore.setState({ sessions, currentSessionId: branchSession.id })
    // 切换到新分支
    const branchMessages = await window.api.chat.listMessages(character.id, branchSession.id)
    useChatStore.setState({ messages: branchMessages })
  }

  // Markdown 内嵌图片：加载失败时通过父容器委托放大预览
  const handleMarkdownClick = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement
    if (target.tagName === 'IMG' && (target as HTMLImageElement).src) {
      setZoomImage((target as HTMLImageElement).src)
    }
  }

  if (editing) {
    return (
      <div className="px-4 py-2 animate-fade-in">
        <div className="mx-auto" style={{ maxWidth: `${settings.messageWidth ?? 768}px` }}>
          <textarea
            ref={textareaRef}
            value={editContent}
            onChange={(e) => {
              setEditContent(e.target.value)
              e.target.style.height = 'auto'
              e.target.style.height = e.target.scrollHeight + 'px'
            }}
            className="textarea w-full min-h-[80px] font-mono text-sm"
          />
          <div className="flex justify-end gap-2 mt-2">
            <button className="btn-ghost" onClick={() => { setEditing(false); setEditContent(message.content) }}>
              <X className="w-4 h-4" /> 取消
            </button>
            <button className="btn-primary" onClick={handleSaveEdit}>
              <Check className="w-4 h-4" /> 保存
            </button>
          </div>
        </div>
      </div>
    )
  }

  // B-05：纯图片系统消息（生图结果）用独立居中布局，不需要头像和气泡
  if (isSystem && hasOnlyImages) {
    return (
      <>
        <div className={cn('px-4', shouldAnimate && 'animate-fade-in-up')} style={{ marginBottom: `${settings.messageSpacing}px` }}>
          <div className="flex justify-center">
            <div className="flex flex-wrap gap-2 justify-center">
              {message.images.map((img, i) => (
                imgErrors.has(i) ? (
                  <button
                    key={i}
                    onClick={() => setImgErrors(prev => { const next = new Set(prev); next.delete(i); return next })}
                    className="w-24 h-24 rounded-lg bg-tavern-bg-hover flex flex-col items-center justify-center text-tavern-text-muted text-xs gap-1 cursor-pointer hover:bg-tavern-bg-hover/80 transition-colors"
                    title="点击重新加载"
                  >
                    <RefreshCw className="w-3.5 h-3.5" />
                    <span>加载失败</span>
                  </button>
                ) : (
                  <img
                    key={i}
                    src={img}
                    alt=""
                    className="max-w-48 max-h-48 rounded-lg object-cover cursor-pointer hover:opacity-80 transition-opacity"
                    onClick={() => setZoomImage(img)}
                    onError={() => setImgErrors((prev) => new Set(prev).add(i))}
                  />
                )
              ))}
            </div>
          </div>
        </div>
        {/* 图片查看器 */}
        {zoomImage && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm cursor-zoom-out animate-fade-in" onClick={() => setZoomImage(null)}>
            <img src={zoomImage} alt="" className="max-w-[90vw] max-h-[90vh] object-contain rounded-lg shadow-2xl" />
            <button className="absolute top-4 right-4 p-2 rounded-full bg-black/50 text-white hover:bg-black/70 transition-colors" onClick={(e) => { e.stopPropagation(); setZoomImage(null) }}><X className="w-6 h-6" /></button>
          </div>
        )}
        {/* 操作栏 */}
        {!isStreaming && (
          <div className="flex items-center justify-center gap-1 mt-1 opacity-0 group-hover:opacity-100 transition-opacity">
            <button className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors" onClick={() => setEditing(true)} title="编辑"><Edit2 className="w-3.5 h-3.5" /></button>
            <button className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors" onClick={handleCopy} title="复制"><Copy className="w-3.5 h-3.5" /></button>
            {onReply && (
              <button className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-accent hover:bg-tavern-bg-hover transition-colors" onClick={onReply} title="引用回复"><Reply className="w-3.5 h-3.5" /></button>
            )}
            <button className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-accent hover:bg-tavern-bg-hover transition-colors disabled:opacity-50" disabled={regenerating} onClick={async () => { setRegenerating(true); try { const result = await window.api.imageGen.generate(message.content); if (result.success && result.images?.length) { await updateMessageImages(message.id, result.images) } } catch { /* 忽略 */ } setRegenerating(false) }} title="重新生图">
              {regenerating ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RefreshCw className="w-3.5 h-3.5" />}
            </button>
            <button className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-danger hover:bg-tavern-bg-hover transition-colors" onClick={() => character && deleteMessage(message.id, character)} title="删除"><Trash2 className="w-3.5 h-3.5" /></button>
          </div>
        )}
      </>
    )
  }

  return (
    <>
    <div className={cn('px-4 group', shouldAnimate && 'animate-fade-in-up')} style={{ marginBottom: `${settings.messageSpacing}px` }}>
      <div className={cn('mx-auto flex gap-4', isUser && 'flex-row-reverse')} style={hasOnlyImages ? { maxWidth: `${settings.messageWidth ?? 768}px` } : { maxWidth: `${settings.messageWidth ?? 768}px`, width: '100%' }}>
        {/* 头像 */}
        <div
          className={cn(
            'w-10 h-10 rounded-full flex items-center justify-center shrink-0',
            isUser
              ? 'bg-gradient-to-br from-tavern-user/30 to-tavern-user/10 text-tavern-user ring-2 ring-tavern-user/20'
              : isSystem
                ? 'bg-gradient-to-br from-tavern-accent/30 to-tavern-accent/10 text-tavern-accent ring-2 ring-tavern-accent/20'
                : 'bg-gradient-to-br from-tavern-assistant/30 to-tavern-assistant/10 text-tavern-assistant ring-2 ring-tavern-assistant/20'
          )}
        >
          {isUser ? (
            persona?.avatar && !avatarError ? (
              <img src={persona.avatar} alt="" className="w-full h-full rounded-full object-cover" onError={() => setAvatarError(true)} />
            ) : (
              <User className="w-5 h-5" />
            )
          ) : isSystem ? (
            <ImageIcon className="w-5 h-5" />
          ) : !avatarError && character ? (
            <img src={character.avatar || charAssetUrl(character.id, 'avatar', character.updatedAt)} alt="" className="w-full h-full rounded-full object-cover" onError={() => setAvatarError(true)} />
          ) : (
            <Bot className="w-5 h-5" />
          )}
        </div>

        {/* 消息内容 */}
        <div className={cn(isUser && 'flex flex-col items-end', hasOnlyImages ? 'w-fit' : 'flex-1 min-w-0')}>
          {/* 名字和时间 */}
          <div className={cn('flex items-center gap-2 mb-1 text-xs text-tavern-text-muted', isUser && 'flex-row-reverse')}>
            <span className="font-medium text-tavern-text-soft">
              {isUser ? settings.userName : isSystem ? '系统' : getDisplayName(character) || 'AI'}
            </span>
            <span>{formatTime(message.timestamp)}</span>
            {settings.showTokenCount && message.content && (
              <span className="px-1.5 py-0.5 rounded bg-tavern-bg-hover text-tavern-text-muted/70 text-[10px]" title={message.charUsage ? `输入: ${message.charUsage.inputChars} 字符 · 输出: ${message.charUsage.outputChars} 字符` : ''}>
                {message.charUsage ? formatCharCount(message.charUsage.totalChars) : formatCharCount(countChars(message.content).total)}
              </span>
            )}
            {/* Swipe 多候选切换指示器 */}
            {!isUser && !isSystem && message.swipes && message.swipes.length > 1 && (
              <div className="flex items-center gap-0.5 px-1.5 py-0.5 rounded bg-tavern-bg-hover">
                <button
                  className="p-0.5 rounded hover:text-tavern-text hover:bg-tavern-bg disabled:opacity-30"
                  onClick={(e) => {
                    e.stopPropagation()
                    if (character) swipeMessage(message.id, -1, character)
                  }}
                  disabled={isStreaming}
                  title="上一个候选"
                >
                  <ChevronLeft className="w-3 h-3" />
                </button>
                <span className="tabular-nums text-[10px] min-w-[28px] text-center">
                  {(message.swipeIndex ?? 0) + 1}/{message.swipes.length}
                </span>
                <button
                  className="p-0.5 rounded hover:text-tavern-text hover:bg-tavern-bg disabled:opacity-30"
                  onClick={(e) => {
                    e.stopPropagation()
                    if (character) swipeMessage(message.id, 1, character)
                  }}
                  disabled={isStreaming}
                  title="下一个候选"
                >
                  <ChevronRight className="w-3 h-3" />
                </button>
              </div>
            )}
          </div>

          {/* 气泡 */}
          <div
            className={cn(
              'msg-bubble max-w-full',
              hasOnlyImages ? 'p-2' : 'px-5 py-3.5',
              settings.bubbleStyle === 'round' && 'rounded-2xl',
              settings.bubbleStyle === 'standard' && 'rounded-lg',
              settings.bubbleStyle === 'sharp' && 'rounded-sm',
              isUser
                ? 'bg-gradient-to-bl from-amber-100 to-orange-50 border border-amber-200/60 rounded-br-sm shadow-md dark:from-amber-900/70 dark:to-orange-900/70 dark:border-amber-700/60 text-amber-950 dark:text-amber-50 bubble-user'
                : 'bg-tavern-bg-card border border-tavern-border rounded-bl-sm shadow-sm text-slate-900 dark:text-slate-100'
            )}
          >
            {/* 引用回复：被引用消息摘要（P1-5） */}
            {repliedMessage && (
              <button
                type="button"
                onClick={onReply ? () => onReply() : undefined}
                className="w-full flex items-start gap-1.5 mb-2 px-2.5 py-1.5 rounded-lg bg-tavern-bg-soft/80 border border-tavern-border-soft text-left hover:bg-tavern-bg-hover transition-colors"
                title="点击引用这条消息"
              >
                <Reply className="w-3 h-3 text-tavern-accent shrink-0 mt-0.5" />
                <span className="min-w-0 flex-1 text-xs">
                  <span className="text-tavern-accent font-medium">
                    {repliedMessage.role === 'user' ? (settings.userName || '用户') : (character?.name ?? '角色')}:
                  </span>
                  <span className="text-tavern-text-muted ml-1 line-clamp-2">
                    {repliedMessage.content.slice(0, 80)}
                    {repliedMessage.content.length > 80 ? '...' : ''}
                  </span>
                </span>
              </button>
            )}
            {message.images?.length > 0 && (
              <div className={cn('flex flex-wrap gap-2', (displayContent || thought) && 'mb-2')}>
                {message.images.map((img, i) => (
                  imgErrors.has(i) ? (
                    <button
                      key={i}
                      onClick={() => setImgErrors(prev => { const next = new Set(prev); next.delete(i); return next })}
                      className="w-24 h-24 rounded-lg bg-tavern-bg-hover flex flex-col items-center justify-center text-tavern-text-muted text-xs gap-1 cursor-pointer hover:bg-tavern-bg-hover/80 transition-colors"
                      title="点击重新加载"
                    >
                      <RefreshCw className="w-3.5 h-3.5" />
                      <span>加载失败</span>
                    </button>
                  ) : (
                    <img
                      key={i}
                      src={img}
                      alt=""
                      className="max-w-48 max-h-48 rounded-lg object-cover cursor-pointer hover:opacity-80 transition-opacity"
                      onClick={() => setZoomImage(img)}
                      onError={() => setImgErrors((prev) => new Set(prev).add(i))}
                    />
                  )
                ))}
              </div>
            )}
            {/* 心理描写折叠区块 */}
            {thought && !isSystem && (
              <div className="mb-2 rounded-lg bg-tavern-bg-soft border border-tavern-border-soft px-3 py-2">
                <button
                  onClick={() => setThoughtExpanded(!thoughtExpanded)}
                  className="text-xs text-tavern-text-muted flex items-center gap-1 hover:text-tavern-text-soft"
                >
                  <span>💭 内心想法</span>
                  <span>{thoughtExpanded ? '▼' : '▶'}</span>
                </button>
                {thoughtExpanded && (
                  <div className="mt-1.5 text-sm italic text-tavern-text-muted select-text whitespace-pre-wrap" style={{ userSelect: 'text' }}>
                    {thought}
                  </div>
                )}
              </div>
            )}
            {/* system 消息只显示图片，不渲染对话文本 */}
            {!isSystem && (
            <div className={cn('markdown-body', isStreamingThis && 'typing-cursor')} onClick={handleMarkdownClick}>
              <ReactMarkdown
                remarkPlugins={[remarkGfm, remarkRoleplay]}
                remarkRehypeOptions={{ allowDangerousHtml: true }}
                rehypePlugins={[rehypeRaw, rehypeHighlight]}
                components={markdownComponents}
              >
                {displayContent || (isStreamingThis ? '' : (thought ? '💭 内容已在"内心想法"中展开' : '（空消息）'))}
              </ReactMarkdown>
            </div>
            )}
            {/* 翻译状态指示 */}
            {isTranslating && !transState?.content && (
              <div className="mt-2 flex items-center gap-1.5 text-xs text-tavern-accent">
                <Loader2 className="w-3 h-3 animate-spin" />
                翻译中...
              </div>
            )}
            {showTranslation && transState?.status === 'error' && (
              <div className="mt-2 text-xs text-tavern-danger">
                翻译失败: {transState.errorMsg || '未知错误'}
              </div>
            )}
            {showTranslation && transState?.content && (
              <div className="mt-1 pt-1 border-t border-tavern-border-soft/50 flex items-center gap-1 text-xs text-tavern-accent">
                <Languages className="w-3 h-3" />
                已翻译 (点击翻译按钮可切回原文)
              </div>
            )}
          </div>

          {/* 操作栏 */}
          {!isStreaming && (
            <div className={cn('flex items-center gap-1 mt-1 opacity-0 group-hover:opacity-100 transition-opacity', isUser && 'flex-row-reverse')}>
              <button
                className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors"
                onClick={() => setEditing(true)}
                title="编辑"
              >
                <Edit2 className="w-3.5 h-3.5" />
              </button>
              <button
                className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors"
                onClick={handleCopy}
                title="复制"
              >
                <Copy className="w-3.5 h-3.5" />
              </button>
              {!isUser && !isSystem && character && (
                <button
                  className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors"
                  onClick={async () => {
                    const chatStore = useChatStore.getState()
                    let preset: any = null
                    if (chatStore.activePresetId) {
                      const presets = await window.api.preset.list()
                      preset = presets.find((p: any) => p.id === chatStore.activePresetId) ?? null
                    }
                    const activeLorebooks: any[] = []
                    if (chatStore.activeLorebookIds.length > 0) {
                      const lorebooks = await window.api.lorebook.list()
                      for (const id of chatStore.activeLorebookIds) {
                        const lb = lorebooks.find((lb: any) => lb.id === id)
                        if (lb && lb.enabled) activeLorebooks.push(lb)
                      }
                    }
                    await regenerateMessage(message.id, character, preset, activeLorebooks)
                  }}
                  title="重新生成"
                  disabled={isStreaming}
                >
                  <RotateCcw className="w-3.5 h-3.5" />
                </button>
              )}
              {!isUser && !isSystem && (
                <>
                  <button
                    className={cn(
                      'p-1.5 rounded transition-colors',
                      ttsState !== 'idle'
                        ? 'text-tavern-accent bg-tavern-accent-soft'
                        : 'text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover'
                    )}
                    onClick={handleSpeak}
                    title={ttsState === 'speaking' ? '暂停' : ttsState === 'paused' ? '继续' : '朗读'}
                  >
                    {ttsState === 'speaking' ? <Pause className="w-3.5 h-3.5" /> : ttsState === 'paused' ? <Play className="w-3.5 h-3.5" /> : <Volume2 className="w-3.5 h-3.5" />}
                  </button>
                  {ttsState !== 'idle' && (
                    <button
                      className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-danger hover:bg-tavern-bg-hover transition-colors"
                      onClick={handleStopSpeak}
                      title="停止朗读"
                    >
                      <VolumeX className="w-3.5 h-3.5" />
                    </button>
                  )}
                  <button
                    className={cn(
                      'p-1.5 rounded transition-colors',
                      showTranslation ? 'text-tavern-accent bg-tavern-accent-soft' : (isTranslating ? 'text-tavern-accent animate-pulse' : 'text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover')
                    )}
                    onClick={handleTranslate}
                    title={showTranslation ? '切回原文' : isTranslating ? '翻译中...' : '翻译'}
                    disabled={isTranslating}
                  >
                    <Languages className="w-3.5 h-3.5" />
                  </button>
                </>
              )}
              <button
                className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors"
                onClick={handleBranch}
                title="从此处分支"
              >
                <GitBranch className="w-3.5 h-3.5" />
              </button>
              {/* 重新生图（仅 system 生图消息） */}
              {isSystem && message.content && (
                <button
                  className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-accent hover:bg-tavern-bg-hover transition-colors disabled:opacity-50"
                  disabled={regenerating}
                  onClick={async () => {
                    setRegenerating(true)
                    try {
                      const result = await window.api.imageGen.generate(message.content)
                      if (result.success && result.images?.length) {
                        await updateMessageImages(message.id, result.images)
                      }
                    } catch { /* 忽略 */ }
                    setRegenerating(false)
                  }}
                  title="重新生图"
                >
                  {regenerating ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RefreshCw className="w-3.5 h-3.5" />}
                </button>
              )}
              <button
                className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-danger hover:bg-tavern-bg-hover transition-colors"
                onClick={() => character && deleteMessage(message.id, character)}
                title="删除"
              >
                <Trash2 className="w-3.5 h-3.5" />
              </button>
            </div>
          )}

          {/* 继续续写按钮 — 始终可见，仅最后一条 assistant 消息 */}
          {isLast && !isUser && !isSystem && !isStreaming && character && (
            <div className="flex justify-center mt-1.5">
              <button
                className={cn(
                  'px-2.5 py-1.5 rounded-lg text-xs font-medium border transition-all flex items-center gap-1.5',
                  continuing
                    ? 'border-tavern-border-soft bg-tavern-bg-card text-tavern-text-muted cursor-not-allowed'
                    : 'border-tavern-accent/40 bg-tavern-accent/5 text-tavern-accent hover:bg-tavern-accent/10 hover:border-tavern-accent/60 hover:shadow-sm',
                )}
                onClick={async () => {
                  setContinuing(true)
                  try {
                    const chatStore = useChatStore.getState()
                    let preset: any = null
                    if (chatStore.activePresetId) {
                      const presets = await window.api.preset.list()
                      preset = presets.find((p: any) => p.id === chatStore.activePresetId) ?? null
                    }
                    const activeLorebooks: any[] = []
                    if (chatStore.activeLorebookIds.length > 0) {
                      const lorebooks = await window.api.lorebook.list()
                      for (const id of chatStore.activeLorebookIds) {
                        const lb = lorebooks.find((lb: any) => lb.id === id)
                        if (lb && lb.enabled) activeLorebooks.push(lb)
                      }
                    }
                    await continueMessage(message.id, character, preset, activeLorebooks)
                  } catch (e) {
                    // 提示错误，避免静默失败
                    useChatStore.setState({ error: `续写失败: ${e instanceof Error ? e.message : String(e)}` })
                  }
                  setContinuing(false)
                }}
                disabled={continuing}
                title="让 AI 从上一次回复的结尾继续生成"
              >
                {continuing ? (
                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                ) : (
                  <ChevronsDown className="w-3.5 h-3.5" />
                )}
                继续续写
              </button>
            </div>
          )}
        </div>
      </div>
    </div>

    {/* 图片放大查看器 */}
    {zoomImage && (
      <div
        className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm cursor-zoom-out animate-fade-in"
        onClick={() => setZoomImage(null)}
      >
        <img
          src={zoomImage}
          alt=""
          className="max-w-[90vw] max-h-[90vh] object-contain rounded-lg shadow-2xl"
        />
        <button
          className="absolute top-4 right-4 p-2 rounded-full bg-black/50 text-white hover:bg-black/70 transition-colors"
          onClick={(e) => { e.stopPropagation(); setZoomImage(null) }}
        >
          <X className="w-6 h-6" />
        </button>
      </div>
    )}
    </>
  )
})

import { useState, useEffect, useMemo, useRef } from 'react'
import { X, Sliders, BookOpen, Cpu, Thermometer, Hash, Sparkles, Search, ChevronDown, Wand2, Lock, RefreshCw, Info, Plug, Loader2, CheckCircle2, XCircle } from 'lucide-react'
import type { Preset, Lorebook } from '../../../shared/types'
import { useChatStore } from '../../store/useChatStore'
import { useSettingsStore } from '../../store/useSettingsStore'
import { useCharacterStore } from '../../store/useCharacterStore'
import { lorebookCache, getEffectiveLorebookIds } from '../../utils/lorebook'
import { cn } from '../../lib/utils'
import { logError } from '../../lib/logger'

interface QuickSettingsPanelProps {
  open: boolean
  onClose: () => void
}

const IMAGE_GEN_SIZES = [
  '512x512', '768x768', '1024x1024',
  '512x768', '768x512',
]

export function QuickSettingsPanel({ open, onClose }: QuickSettingsPanelProps) {
  const { activePresetId, activeLorebookIds, setActivePreset, setActiveLorebooks, saveLorebookBinding } = useChatStore()
  const { settings, updateSettings } = useSettingsStore()
  const currentCharacter = useCharacterStore(s => s.currentCharacter)
  const currentCharId = currentCharacter?.id
  const [presets, setPresets] = useState<Preset[]>([])
  const [lorebooks, setLorebooks] = useState<Lorebook[]>([])
  const [lorebookExpanded, setLorebookExpanded] = useState(false)
  const [lorebookSearch, setLorebookSearch] = useState('')
  // 模型列表
  const [modelList, setModelList] = useState<string[]>([])
  const [modelListLoading, setModelListLoading] = useState(false)
  const [modelListError, setModelListError] = useState(false)
  const [modelExpanded, setModelExpanded] = useState(false)
  const [modelSearch, setModelSearch] = useState('')
  // 连接测试
  const [testing, setTesting] = useState(false)
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null)

  // 计算角色绑定的世界书 ID 列表
  const boundLorebookIds = useMemo(() => {
    return getEffectiveLorebookIds(currentCharacter)
  }, [currentCharacter?.boundLorebookIds, currentCharacter?.lorebookId])

  // 区分绑定和手动选择的世界书
  const manualLorebookIds = useMemo(
    () => activeLorebookIds.filter(id => !boundLorebookIds.includes(id)),
    [activeLorebookIds, boundLorebookIds],
  )

  // 组件挂载时预加载世界书（确保绑定芯片始终有名称）
  useEffect(() => {
    window.api.lorebook.list().then((lbs) => {
      setLorebooks(lbs)
      for (const lb of lbs) { lorebookCache.set(lb.id, lb) }
    }).catch((e) => logError('QuickSettings:loadModels', e))
  }, [])

  // 面板打开时刷新预设和世界书（获取最新数据）
  useEffect(() => {
    if (!open) return
    window.api.preset.list().then(setPresets)
    window.api.lorebook.list().then((lbs) => {
      setLorebooks(lbs)
      for (const lb of lbs) { lorebookCache.set(lb.id, lb) }
      // 移除已禁用的世界书从激活列表
      const disabledIds = lbs.filter(lb => !lb.enabled).map(lb => lb.id)
      if (disabledIds.some(id => activeLorebookIds.includes(id))) {
        setActiveLorebooks(activeLorebookIds.filter(id => !disabledIds.includes(id)), currentCharId)
      }
    })
  }, [open])

  // 面板打开时获取模型列表
  useEffect(() => {
    if (!open) return
    const p = useSettingsStore.getState().getActiveProfile()
    if (!p) {
      setModelListError(true)
      setModelList([])
      return
    }
    setModelListLoading(true)
    setModelListError(false)
    window.api.ai.listModels(p.provider, p.baseUrl, p.apiKey)
      .then((res) => {
        if (res.success && res.models && res.models.length > 0) {
          setModelList(res.models)
          setModelListError(false)
        } else {
          setModelListError(true)
          setModelList([])
        }
      })
      .catch(() => {
        setModelListError(true)
        setModelList([])
      })
      .finally(() => setModelListLoading(false))
  }, [open])

  // 从 API 获取模型列表的手动刷新
  const refreshModels = () => {
    const p = useSettingsStore.getState().getActiveProfile()
    if (!p) return
    setModelListLoading(true)
    setModelListError(false)
    window.api.ai.listModels(p.provider, p.baseUrl, p.apiKey)
      .then((res) => {
        if (res.success && res.models && res.models.length > 0) {
          setModelList(res.models)
        } else {
          setModelListError(true)
        }
      })
      .catch(() => setModelListError(true))
      .finally(() => setModelListLoading(false))
  }

  /** 测试当前 API 连接 */
  const handleTestConnection = async () => {
    const p = useSettingsStore.getState().getActiveProfile()
    if (!p) return
    setTesting(true)
    setTestResult(null)
    try {
      const res = await window.api.ai.testConnection({
        type: p.provider,
        baseUrl: p.baseUrl,
        apiKey: p.apiKey,
        model: p.model || settings.activeModel || 'gpt-4o-mini',
      })
      setTestResult({
        success: res.success,
        message: res.success
          ? (res.models && res.models.length > 0 ? `连接成功，${res.models.length} 个模型可用` : '连接成功')
          : (res.error ?? '连接失败'),
      })
    } catch (e) {
      setTestResult({ success: false, message: e instanceof Error ? e.message : String(e) })
    } finally {
      setTesting(false)
    }
  }

  const profile = useSettingsStore.getState().getActiveProfile()
  const activePreset = presets.find((p) => p.id === activePresetId)

  return (
    <>
      {/* 遮罩 */}
      {open && <div className="fixed inset-0 z-30" onClick={onClose} />}

      {/* 面板 */}
      <div className={cn(
        'fixed right-0 top-0 w-80 bg-tavern-bg-card border-l border-tavern-border z-40 transition-transform duration-300 overflow-y-auto',
        open ? 'translate-x-0' : 'translate-x-full'
      )} style={{ top: 0, height: '100vh' }}>
        {/* 头部 */}
        <div className="flex items-center justify-between px-4 h-14 border-b border-tavern-border-soft sticky top-0 bg-tavern-bg-card/95 backdrop-blur z-10">
          <h3 className="font-display font-bold flex items-center gap-2 text-sm">
            <Sliders className="w-4 h-4 text-tavern-accent" />
            快捷设置
          </h3>
          <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-tavern-bg-hover transition-colors">
            <X className="w-4 h-4" />
          </button>
        </div>

        <div className="p-4 space-y-5">

          {/* ===== 模型 ===== */}
          <Section icon={Cpu} title="模型">
            {/* API 模型下拉框 */}
            {!modelListError && modelList.length > 0 ? (
              <div className="space-y-1.5">
                {/* 已选中 + 展开按钮 */}
                <div className="flex items-center gap-1.5">
                  <button
                    onClick={() => setModelExpanded(!modelExpanded)}
                    className="flex items-center gap-1.5 flex-1 min-w-0 px-2 py-1 rounded-md text-xs bg-tavern-bg-soft border border-tavern-border-soft hover:border-tavern-border transition-colors text-left"
                  >
                    <span className="truncate flex-1">{settings.activeModel || '选择模型'}</span>
                    <ChevronDown className={cn('w-3 h-3 shrink-0 text-tavern-text-muted transition-transform', modelExpanded && 'rotate-180')} />
                  </button>
                  <button
                    onClick={refreshModels}
                    disabled={modelListLoading}
                    className="p-1 rounded-md hover:bg-tavern-bg-hover text-tavern-text-muted transition-colors shrink-0"
                    title="刷新模型列表"
                  >
                    <RefreshCw className={cn('w-3.5 h-3.5', modelListLoading && 'animate-spin')} />
                  </button>
                  <button
                    onClick={handleTestConnection}
                    disabled={testing || !profile}
                    className="p-1 rounded-md hover:bg-tavern-bg-hover text-tavern-text-muted transition-colors shrink-0 disabled:opacity-50 disabled:cursor-not-allowed"
                    title="测试连接"
                  >
                    {testing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Plug className="w-3.5 h-3.5" />}
                  </button>
                </div>
                {/* 展开的搜索+列表 */}
                {modelExpanded && (
                  <div className="space-y-1 animate-fade-in">
                    {modelList.length > 8 && (
                      <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-tavern-bg-soft border border-tavern-border-soft">
                        <Search className="w-3 h-3 text-tavern-text-muted shrink-0" />
                        <input
                          className="bg-transparent text-xs flex-1 outline-none placeholder:text-tavern-text-muted"
                          placeholder="搜索模型..."
                          value={modelSearch}
                          onChange={e => setModelSearch(e.target.value)}
                        />
                        {modelSearch && (
                          <button className="text-tavern-text-muted hover:text-tavern-text" onClick={() => setModelSearch('')}>
                            <X className="w-3 h-3" />
                          </button>
                        )}
                      </div>
                    )}
                    <div className="max-h-40 overflow-y-auto -mx-0.5 px-0.5 space-y-0.5">
                      {modelList
                        .filter(m => !modelSearch || m.toLowerCase().includes(modelSearch.toLowerCase()))
                        .map((m) => {
                          const isActive = (settings.activeModel || profile?.model) === m
                          return (
                            <button
                              key={m}
                              onClick={() => {
                                updateSettings({ activeModel: m })
                                setModelExpanded(false)
                                setModelSearch('')
                              }}
                              className={cn(
                                'w-full flex items-center gap-2 px-2 py-1.5 rounded-lg text-left text-xs transition-colors truncate',
                                isActive
                                  ? 'bg-tavern-accent-soft text-tavern-accent'
                                  : 'hover:bg-tavern-bg-hover text-tavern-text-soft'
                              )}
                            >
                              <span className={cn('w-1.5 h-1.5 rounded-full shrink-0', isActive ? 'bg-tavern-accent' : 'bg-tavern-border')} />
                              <span className="truncate">{m}</span>
                              {isActive && <span className="ml-auto text-[11px] text-tavern-accent/70 shrink-0">当前</span>}
                            </button>
                          )
                        })}
                    </div>
                  </div>
                )}
              </div>
            ) : modelListLoading ? (
              <div className="flex items-center gap-2 py-1.5 text-xs text-tavern-text-muted">
                <RefreshCw className="w-3 h-3 animate-spin" />
                获取模型列表...
              </div>
            ) : (
              /* 兜底：无可用模型列表时显示文本输入 */
              <div className="flex items-center gap-1.5">
                <input
                  type="text"
                  className="input text-xs flex-1 min-w-0"
                  value={settings.activeModel}
                  onChange={(e) => updateSettings({ activeModel: e.target.value })}
                  placeholder="输入模型名称"
                />
                <button
                  onClick={handleTestConnection}
                  disabled={testing || !profile}
                  className="p-1.5 rounded-md hover:bg-tavern-bg-hover text-tavern-text-muted transition-colors shrink-0 disabled:opacity-50 disabled:cursor-not-allowed"
                  title="测试连接"
                >
                  {testing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Plug className="w-3.5 h-3.5" />}
                </button>
              </div>
            )}
            {profile?.baseUrl && (
              <p className="text-xs text-tavern-text-muted mt-1.5 truncate">{profile.baseUrl}</p>
            )}
            {testResult && (
              <p className={cn('text-xs mt-1.5 flex items-start gap-1', testResult.success ? 'text-tavern-success' : 'text-tavern-danger')}>
                {testResult.success ? <CheckCircle2 className="w-3 h-3 shrink-0 mt-px" /> : <XCircle className="w-3 h-3 shrink-0 mt-px" />}
                <span className="break-all">{testResult.message}</span>
              </p>
            )}
          </Section>

          {/* ===== 预设 ===== */}
          <Section icon={Sparkles} title="预设">
            <select
              className="input text-xs"
              value={activePresetId ?? ''}
              onChange={(e) => setActivePreset(e.target.value || null, currentCharId)}
            >
              <option value="">默认</option>
              {presets.map((p) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
            {activePreset && (
              <div className="mt-2 grid grid-cols-3 gap-1.5 text-xs text-tavern-text-muted">
                <ParamChip label="温度" value={activePreset.temperature} />
                <ParamChip label="Top P" value={activePreset.topP} />
                <ParamChip label="最大Token" value={activePreset.maxTokens} />
              </div>
            )}
          </Section>

          {/* ===== 采样参数 ===== */}
          <Section icon={Thermometer} title="采样参数">
            <div className="space-y-3">
              <SliderRow
                label="温度"
                value={activePreset?.temperature ?? 0.8}
                min={0} max={2} step={0.1}
                disabled
                hint={
                  <>
                    <p>控制输出的<strong className="text-tavern-text-soft">随机性 / 创造性</strong>：</p>
                    <ul className="mt-1 list-disc pl-3 space-y-0.5">
                      <li>低（0.2~0.5）：稳定、严谨、可预测，适合事实性回复</li>
                      <li>高（1.0+）：发散、有创意、更“活”，但可能偏离设定</li>
                      <li>角色扮演常用 0.7~1.0</li>
                    </ul>
                  </>
                }
              />
              <SliderRow
                label="Top P"
                value={activePreset?.topP ?? 0.95}
                min={0} max={1} step={0.05}
                disabled
                hint={
                  <>
                    <p><strong className="text-tavern-text-soft">核采样</strong>：只从累计概率达到 P 的高概率 token 中采样。</p>
                    <p className="mt-1.5">与温度配合使用，一般保持 0.9~1.0。微调时与温度二选一即可，不必同时反复调。</p>
                  </>
                }
              />
              <div className="space-y-1.5">
                <div className="flex items-center justify-between gap-3">
                  <label className="text-xs text-tavern-text-muted shrink-0">最大Token</label>
                  <div className="flex items-center gap-1.5">
                    {[512, 1024, 2048, 4096].map((n) => (
                      <button
                        key={n}
                        disabled={!activePreset}
                        onClick={async () => {
                          if (!activePreset) return
                          const updated = { ...activePreset, maxTokens: n }
                          await window.api.preset.save(updated)
                          setPresets(prev => prev.map(p => p.id === updated.id ? updated : p))
                        }}
                        className={cn(
                          'px-2 py-0.5 rounded text-xs border transition-colors',
                          !activePreset && 'opacity-50 cursor-not-allowed',
                          (activePreset?.maxTokens ?? 1024) === n
                            ? 'border-tavern-accent/40 bg-tavern-accent-soft text-tavern-accent'
                            : 'border-tavern-border-soft text-tavern-text-muted hover:border-tavern-border hover:text-tavern-text'
                        )}
                      >
                        {n >= 1024 ? `${n / 1024}k` : n}
                      </button>
                    ))}
                    <input
                      type="number"
                      min={1}
                      disabled={!activePreset}
                      value={activePreset?.maxTokens ?? 1024}
                      onChange={async (e) => {
                        if (!activePreset) return
                        const val = Number(e.target.value) || 1
                        const updated = { ...activePreset, maxTokens: val }
                        setPresets(prev => prev.map(p => p.id === updated.id ? updated : p))
                      }}
                      onBlur={async (e) => {
                        if (!activePreset) return
                        const val = Number(e.target.value) || 1
                        const updated = { ...activePreset, maxTokens: val }
                        await window.api.preset.save(updated)
                        setPresets(prev => prev.map(p => p.id === updated.id ? updated : p))
                      }}
                      className="w-16 px-1.5 py-0.5 rounded text-xs border border-tavern-border-soft bg-tavern-bg text-tavern-text text-center focus:outline-none focus:border-tavern-accent/40 disabled:opacity-50"
                      title="自定义 Token 数"
                    />
                  </div>
                </div>
              </div>
            </div>
          </Section>

          {/* ===== 世界书 ===== */}
          <Section icon={BookOpen} title="世界书">
            {lorebooks.length === 0 ? (
              <p className="text-xs text-tavern-text-muted py-1">暂无世界书</p>
            ) : (
              <>
                {/* 已选中芯片 + 展开按钮 */}
                <div className="flex flex-wrap items-center gap-1.5">
                  {/* 角色绑定的世界书 - 始终显示，不受 activeLorebookIds 影响 */}
                  {boundLorebookIds.map(id => {
                    const lb = lorebooks.find(l => l.id === id)
                    if (!lb) return null
                    const isActive = activeLorebookIds.includes(id)
                    return (
                      <span
                        key={id}
                        className={cn(
                          'inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md text-xs border transition-colors',
                          isActive
                            ? 'bg-tavern-accent-soft text-tavern-accent border-tavern-accent/20'
                            : 'bg-tavern-bg-soft text-tavern-text-muted border-tavern-border-soft'
                        )}
                      >
                        <Lock className="w-2.5 h-2.5 shrink-0" />
                        <span className="max-w-[80px] truncate">{lb.name}</span>
                        {!isActive && (
                          <button
                            className="text-tavern-text-muted hover:text-tavern-accent transition-colors"
                            onClick={() => setActiveLorebooks([...activeLorebookIds, id], currentCharId)}
                            title="激活此世界书"
                          >
                            <ChevronDown className="w-2.5 h-2.5 rotate-[-90deg]" />
                          </button>
                        )}
                      </span>
                    )
                  })}
                  {/* 手动选择的世界书 */}
                  {manualLorebookIds.map(id => {
                    const lb = lorebooks.find(l => l.id === id)
                    return lb ? (
                      <span key={id} className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md text-xs bg-tavern-bg-soft text-tavern-text-soft border border-tavern-border-soft">
                        {lb.name}
                        <button
                          className="hover:text-tavern-danger transition-colors"
                          onClick={() => setActiveLorebooks(activeLorebookIds.filter(i => i !== id), currentCharId)}
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </span>
                    ) : null
                  })}
                  <button
                    onClick={() => setLorebookExpanded(!lorebookExpanded)}
                    className="text-xs text-tavern-text-muted hover:text-tavern-text transition-colors ml-0.5"
                  >
                    {lorebookExpanded ? '收起' : `选择世界书${activeLorebookIds.length > 0 ? ` (+${lorebooks.filter(lb => lb.enabled).length - activeLorebookIds.length})` : ` (${lorebooks.filter(lb => lb.enabled).length})`}`}
                    <ChevronDown className={cn('w-3 h-3 ml-0.5 inline transition-transform', lorebookExpanded && 'rotate-180')} />
                  </button>
                </div>

                {/* 展开的搜索+列表 */}
                {lorebookExpanded && (
                  <div className="mt-2 space-y-1.5 animate-fade-in">
                    {lorebooks.length > 6 && (
                      <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-tavern-bg-soft border border-tavern-border-soft">
                        <Search className="w-3 h-3 text-tavern-text-muted shrink-0" />
                        <input
                          className="bg-transparent text-xs flex-1 outline-none placeholder:text-tavern-text-muted"
                          placeholder="搜索..."
                          value={lorebookSearch}
                          onChange={e => setLorebookSearch(e.target.value)}
                        />
                        {lorebookSearch && (
                          <button className="text-tavern-text-muted hover:text-tavern-text" onClick={() => setLorebookSearch('')}>
                            <X className="w-3 h-3" />
                          </button>
                        )}
                      </div>
                    )}
                    <div className="max-h-40 overflow-y-auto -mx-0.5 px-0.5 space-y-0.5">
                      {lorebooks.filter(lb => lb.enabled && (!lorebookSearch || lb.name.toLowerCase().includes(lorebookSearch.toLowerCase()))).map(lb => {
                        const checked = activeLorebookIds.includes(lb.id)
                        const isBound = boundLorebookIds.includes(lb.id)
                        return (
                          <button
                            key={lb.id}
                            onClick={() => {
                              if (checked) {
                                setActiveLorebooks(activeLorebookIds.filter(id2 => id2 !== lb.id), currentCharId)
                              } else {
                                setActiveLorebooks([...activeLorebookIds, lb.id], currentCharId)
                              }
                            }}
                            className={cn(
                              'w-full flex items-center gap-2 px-2 py-1.5 rounded-lg text-left text-xs transition-colors',
                              checked ? 'bg-tavern-accent-soft text-tavern-accent' : 'hover:bg-tavern-bg-hover text-tavern-text-soft'
                            )}
                          >
                            <span className={cn('w-1.5 h-1.5 rounded-full shrink-0', checked ? 'bg-tavern-accent' : 'bg-tavern-border')} />
                            <span className="truncate flex-1">{lb.name}</span>
                            {isBound && <Lock className="w-2.5 h-2.5 text-tavern-accent/60 shrink-0" />}
