/* ===== 子组件 ===== */

function Section({ icon: Icon, title, children }: { icon: React.ElementType; title: string; children: React.ReactNode }) {
  return (
    <div>
      <div className="flex items-center gap-1.5 mb-2">
        <Icon className="w-3.5 h-3.5 text-tavern-text-muted" />
        <span className="text-xs font-semibold text-tavern-text-soft uppercase tracking-wide">{title}</span>
      </div>
      {children}
    </div>
  )
}

function ParamChip({ label, value }: { label: string; value: number | undefined }) {
  return (
    <div className="px-2 py-1 rounded-md bg-tavern-bg-soft border border-tavern-border-soft text-center">
      <div className="text-[11px] uppercase tracking-wide opacity-60">{label}</div>
      <div className="font-mono font-medium text-xs">{value ?? '-'}</div>
    </div>
  )
}

function SliderRow({ label, value, min, max, step, disabled, hint }: {
  label: string; value: number; min: number; max: number; step: number; disabled?: boolean; hint?: React.ReactNode
}) {
  return (
    <div>
      <div className="flex items-center justify-between mb-1">
        <label className="flex items-center gap-0.5 text-xs text-tavern-text-muted">
          <span>{label}</span>
          {hint && <HintIcon hint={hint} />}
        </label>
        <span className="text-xs font-mono text-tavern-text-soft tabular-nums">{value}</span>
      </div>
      <input
        type="range"
        min={min} max={max} step={step}
        value={value}
        readOnly={disabled}
        className={cn(
          'w-full h-1.5 rounded-full appearance-none cursor-pointer',
          'bg-tavern-bg-hover',
          '[&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3.5 [&::-webkit-slider-thumb]:h-3.5 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-tavern-accent [&::-webkit-slider-thumb]:shadow-sm',
          disabled && 'opacity-60 cursor-not-allowed [&::-webkit-slider-thumb]:cursor-not-allowed'
        )}
      />
    </div>
  )
}

/** ⓘ 点击弹出提示（说明气泡）
 * 关闭机制：document 级点击监听（不依赖 fixed 遮罩，规避面板 transform 导致 fixed 定位失效的问题）
 */
function HintIcon({ hint }: { hint: React.ReactNode }) {
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLSpanElement>(null)

  useEffect(() => {
    if (!open) return
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    // 捕获阶段监听，确保先于面板其他点击处理
    document.addEventListener('click', handler)
    return () => document.removeEventListener('click', handler)
  }, [open])

  return (
    <span ref={ref} className="relative inline-flex">
      <button
        type="button"
        onClick={(e) => { e.stopPropagation(); setOpen((v) => !v) }}
        className="p-0.5 rounded text-tavern-text-muted hover:text-tavern-accent transition-colors"
      >
        <Info className="w-3.5 h-3.5" />
      </button>
      {open && (
        <div className="absolute left-0 top-full mt-1 w-56 p-2.5 rounded-lg bg-tavern-bg-card border border-tavern-border shadow-xl z-50 text-[10px] leading-relaxed text-tavern-text-muted">
          {hint}
        </div>
      )}
    </span>
  )
}

function ToggleRow({ checked, onChange, children }: { checked: boolean; onChange: (v: boolean) => void; children: React.ReactNode }) {
  return (
    <label className="flex items-center justify-between gap-2 cursor-pointer py-0.5">
      <span className="text-xs text-tavern-text-soft select-none">{children}</span>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        onClick={() => onChange(!checked)}
        className={cn(
          'relative inline-flex h-5 w-9 shrink-0 rounded-full border-2 border-transparent transition-colors',
          'focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-tavern-accent',
          checked ? 'bg-tavern-accent' : 'bg-tavern-bg-hover'
        )}
      >
        <span className={cn(
          'pointer-events-none inline-block h-4 w-4 rounded-full bg-white shadow transition-transform',
          checked ? 'translate-x-4' : 'translate-x-0'
        )} />
      </button>
    </label>
  )
}

import { useState, useEffect, useMemo } from 'react'
import { Heart, MapPin, Smile, BookOpen, Lock } from 'lucide-react'
import { useChatStore } from '../../store/useChatStore'
import { useCharacterStore } from '../../store/useCharacterStore'
import { getEffectiveLorebookIds } from '../../utils/lorebook'
import { logError } from '../../lib/logger'
import type { Character, Message, Lorebook } from '../../../shared/types'

interface StatusBarProps {
  character: Character
  messages: Message[]
}

interface StatusItem {
  label: string
  value: string
  icon: typeof Heart
}

/**
 * 从 AI 回复中解析状态更新
 * 格式: [Status: key=value] 或 【状态: key=value】
 */
function parseStatusFromMessages(messages: Message[]): StatusItem[] {
  const statusMap = new Map<string, string>()

  for (const msg of messages) {
    if (msg.role !== 'assistant') continue
    // 匹配 [Status: key=value] 或 【状态: key=value】
    // 拆分为两个正则：【状态:】格式用 [^】] 排除字符，使 value 可含 ]
    const regexBracket = /\[Status:\s*([^=]+?)\s*=\s*([^\]]+?)\s*\]/gi
    const regexCJK = /【状态:\s*([^=]+?)\s*=\s*([^】]+?)\s*】/gi
    let match
    while ((match = regexBracket.exec(msg.content)) !== null) {
      statusMap.set(match[1].trim(), match[2].trim())
    }
    while ((match = regexCJK.exec(msg.content)) !== null) {
      statusMap.set(match[1].trim(), match[2].trim())
    }
  }

  const iconMap: Record<string, typeof Heart> = {
    '好感': Heart,
    '好感度': Heart,
    '心情': Smile,
    '位置': MapPin,
    '地点': MapPin,
  }

  return Array.from(statusMap.entries()).map(([label, value]) => ({
    label,
    value,
    icon: iconMap[label] || Heart,
  }))
}

export function StatusBar({ character, messages }: StatusBarProps) {
  const [statusItems, setStatusItems] = useState<StatusItem[]>([])
  const [lorebooks, setLorebooks] = useState<Lorebook[]>([])
  const activeLorebookIds = useChatStore(s => s.activeLorebookIds)
  const currentCharacter = useCharacterStore(s => s.currentCharacter)

  useEffect(() => {
    setStatusItems(parseStatusFromMessages(messages))
  }, [messages])

  // 加载世界书列表：角色切换 或 激活数量变化时重新加载
  useEffect(() => {
    window.api.lorebook.list().then(setLorebooks).catch((e) => logError('StatusBar:loadLorebooks', e))
  }, [character.id, activeLorebookIds.length])

  // 角色绑定的世界书 ID
  const boundLorebookIds = useMemo(() => {
    return getEffectiveLorebookIds(currentCharacter)
  }, [currentCharacter?.boundLorebookIds, currentCharacter?.lorebookId])

  // 解析激活的世界书名称
  const activeLorebookNames = useMemo(() => {
    return activeLorebookIds
      .map(id => {
        const lb = lorebooks.find(l => l.id === id)
        return lb ? { id, name: lb.name, isBound: boundLorebookIds.includes(id) } : null
      })
      .filter(Boolean) as { id: string; name: string; isBound: boolean }[]
  }, [activeLorebookIds, boundLorebookIds, lorebooks])

  if (statusItems.length === 0 && activeLorebookNames.length === 0) return null

  return (
    <div className="flex items-center gap-3 px-4 py-2 border-b border-tavern-border-soft bg-tavern-bg-soft overflow-x-auto">
      {/* 激活的世界书 — 直接可见，绑定世界书带锁图标 */}
      {activeLorebookNames.map(lb => (
        <div key={lb.id} className="flex items-center gap-1 text-xs whitespace-nowrap">
          {lb.isBound ? (
            <Lock className="w-3 h-3 text-tavern-accent" />
          ) : (
            <BookOpen className="w-3 h-3 text-tavern-text-muted" />
          )}
          <span className={lb.isBound ? 'text-tavern-accent font-medium' : 'text-tavern-text-muted'}>
            {lb.name}
          </span>
        </div>
      ))}
      {/* 状态项分隔符 */}
      {activeLorebookNames.length > 0 && statusItems.length > 0 && (
        <span className="w-px h-4 bg-tavern-border-soft" />
      )}
      {statusItems.map((item, i) => {
        const Icon = item.icon
        return (
          <div key={i} className="flex items-center gap-1.5 text-sm whitespace-nowrap">
            <Icon className="w-3.5 h-3.5 text-tavern-accent" />
            <span className="text-tavern-text-muted">{item.label}:</span>
            <span className="text-tavern-text-soft font-medium">{item.value}</span>
          </div>
        )
      })}
    </div>
  )
}

