// ---- 全局错误捕获（测试环境终端输出）----
// 未捕获的错误会在此收集，afterEach 时检查并使测试失败

const unhandledErrors: string[] = []

window.addEventListener('error', (e: ErrorEvent) => {
  const msg = e.error instanceof Error
    ? `${e.error.message}\n${e.error.stack ?? ''}`
    : e.message
  console.error('\n━━━ 未捕获异常 ━━━')
  console.error(msg)
  console.error('━━━━━━━━━━━━━━━\n')
  unhandledErrors.push(msg)
})

window.addEventListener('unhandledrejection', (e: PromiseRejectionEvent) => {
  const reason = e.reason instanceof Error
    ? `${e.reason.message}\n${e.reason.stack ?? ''}`
    : String(e.reason)
  console.error('\n━━━ 未处理 Promise rejection ━━━')
  console.error(reason)
  console.error('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n')
  unhandledErrors.push(`[unhandled rejection] ${reason}`)
})

afterEach(() => {
  clearCollectedLogs()
  if (unhandledErrors.length > 0) {
    const count = unhandledErrors.length
    const errors = unhandledErrors.join('\n  ')
    unhandledErrors.length = 0
    throw new Error(`测试期间发生 ${count} 个未捕获错误:\n  ${errors}`)
  }
})

/**
 * Instruct 模板单元测试
 *
 * 覆盖：内置模板解析、消息包装、模板优先级解析。
 */
import { describe, it, expect } from 'vitest'
import {
  getTemplateByName,
  resolveEffectiveTemplate,
  applyInstructTemplate,
  BUILTIN_TEMPLATE_NAMES,
  type InstructTemplate,
} from '../chatTemplates'

const MESSAGES = [
  { role: 'system', content: '你是助手' },
  { role: 'user', content: '你好' },
  { role: 'assistant', content: '嗨' },
]

describe('getTemplateByName', () => {
  it('ChatML 模板存在且格式正确', () => {
    const t = getTemplateByName('chatml')
    expect(t).toBeDefined()
    expect(t!.userPrefix).toBe('<|im_start|>user\n')
    expect(t!.stopSequences).toContain('<|im_end|>')
  })

  it('大小写不敏感', () => {
    expect(getTemplateByName('ChatML')).toBeDefined()
    expect(getTemplateByName('LLAMA3')).toBeDefined()
  })

  it('未知模板返回 undefined', () => {
    expect(getTemplateByName('nonexistent')).toBeUndefined()
    expect(getTemplateByName(undefined)).toBeUndefined()
    expect(getTemplateByName('')).toBeUndefined()
  })

  it('内置模板覆盖常用格式', () => {
    for (const name of ['chatml', 'llama3', 'alpaca', 'mistral', 'qwen', 'deepseek', 'gemma']) {
      expect(BUILTIN_TEMPLATE_NAMES).toContain(name)
    }
  })
})

describe('applyInstructTemplate', () => {
  it('ChatML 包装 system/user/assistant 消息', () => {
    const t = getTemplateByName('chatml')!
    const { text } = applyInstructTemplate(MESSAGES, t)

    expect(text).toBe(
      '<|im_start|>system\n你是助手<|im_end|>\n'
      + '<|im_start|>user\n你好<|im_end|>\n'
      + '<|im_start|>assistant\n嗨<|im_end|>\n'
      + '<|im_start|>assistant\n', // appendAssistantPrefix
    )
  })

  it('返回模板停止序列', () => {
    const t = getTemplateByName('chatml')!
    const { stopSequences } = applyInstructTemplate(MESSAGES, t)
    expect(stopSequences).toEqual(['<|im_end|>', '<|im_start|>'])
  })

  it('Alpaca 格式（无 appendAssistantPrefix）', () => {
    const t = getTemplateByName('alpaca')!
    const { text } = applyInstructTemplate(MESSAGES, t)

    expect(text).toContain('### Instruction:\n你好\n\n### Response:\n嗨')
    // Alpaca 不追加额外的 assistant 前缀（末尾是 assistant 内容本身）
  })

  it('空消息数组：appendAssistantPrefix 模板返回 assistant 前缀，否则空', () => {
    const chatml = getTemplateByName('chatml')!
    expect(applyInstructTemplate([], chatml).text).toBe('<|im_start|>assistant\n')

    const alpaca = getTemplateByName('alpaca')!
    expect(applyInstructTemplate([], alpaca).text).toBe('')
  })
})

describe('resolveEffectiveTemplate', () => {
  it('预设指定模板优先于 profile 开关', () => {
    const t = resolveEffectiveTemplate('chatml', 'ollama', 'qwen2.5', true)
    expect(t?.userPrefix).toContain('<|im_start|>user')
  })

  it('无预设指定时跟随 profile 自动推断', () => {
    const t = resolveEffectiveTemplate(undefined, 'ollama', 'llama3', true)
    expect(t?.userPrefix).toContain('llama3'.includes('llama3') ? '<|start_header_id|>user' : '')
  })

  it('预设指定未知模板名时回退 profile 推断', () => {
    const t = resolveEffectiveTemplate('not-a-template', 'ollama', 'mistral', true)
    expect(t?.userPrefix).toContain('[INST]')
  })

  it('两者都不启用时返回 undefined', () => {
    expect(resolveEffectiveTemplate(undefined, 'ollama', 'qwen2.5', false)).toBeUndefined()
    expect(resolveEffectiveTemplate('', 'ollama', 'qwen2.5', undefined)).toBeUndefined()
  })
})

import { describe, it, expect } from 'vitest'
import { parseDialogue, type DialogueSegment } from '../dialogue-parser'

describe('parseDialogue', () => {
  describe('plain text / narration', () => {
    it('plain text without any dialogue/action markers returns a single plain segment', () => {
      const result = parseDialogue('Hello world')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('plain')
      expect(result[0].content).toBe('Hello world')
      expect(result[0].speaker).toBeUndefined()
    })

    it('plain Chinese text without markers returns a single plain segment', () => {
      const result = parseDialogue('今天天气不错')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('plain')
      expect(result[0].content).toBe('今天天气不错')
    })
  })

  describe('dialogue', () => {
    it('double-quoted "Hello" returns a dialogue segment', () => {
      const result = parseDialogue('"Hello"')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('dialogue')
      expect(result[0].content).toBe('Hello')
      expect(result[0].speaker).toBeUndefined()
    })

    it('curly-quoted \u201CHello\u201D returns a dialogue segment', () => {
      const result = parseDialogue('\u201CHello\u201D')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('dialogue')
      expect(result[0].content).toBe('Hello')
      expect(result[0].speaker).toBeUndefined()
    })

    it('Speaker: "text" returns dialogue with speaker (half-width colon)', () => {
      const result = parseDialogue('Alice: "Hello there"')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('dialogue')
      expect(result[0].speaker).toBe('Alice')
      expect(result[0].content).toBe('Hello there')
    })

    it('Speaker\uff1a "text" returns dialogue with speaker (full-width colon)', () => {
      const result = parseDialogue('Alice\uff1a "Hello there"')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('dialogue')
      expect(result[0].speaker).toBe('Alice')
      expect(result[0].content).toBe('Hello there')
    })

    it("Speaker: 'text' returns dialogue with speaker (single quotes)", () => {
      const result = parseDialogue("Bob: 'Hi there'")
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('dialogue')
      expect(result[0].speaker).toBe('Bob')
      expect(result[0].content).toBe('Hi there')
    })

    it('Chinese corner brackets \u300Ctext\u300D are normalized and return dialogue', () => {
      const result = parseDialogue('\u300C\u4F60\u597D\u300D')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('dialogue')
      expect(result[0].content).toBe('\u4F60\u597D')
    })
  })

  describe('action', () => {
    it('*does something* returns an action segment', () => {
      const result = parseDialogue('*does something*')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('action')
      expect(result[0].content).toBe('does something')
      expect(result[0].speaker).toBeUndefined()
    })

    it('*walks away* returns an action segment', () => {
      const result = parseDialogue('*walks away*')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('action')
      expect(result[0].content).toBe('walks away')
    })
  })

  describe('mixed content', () => {
    it('mixed content with dialogue, action, and narration returns multiple segments', () => {
      const result = parseDialogue('He said "hello" and *walked away*')
      expect(result.length).toBeGreaterThanOrEqual(3)

      const types = result.map((s) => s.type)
      expect(types).toContain('plain')
      expect(types).toContain('dialogue')
      expect(types).toContain('action')

      const dialogueSeg = result.find((s) => s.type === 'dialogue')
      expect(dialogueSeg?.content).toBe('hello')

      const actionSeg = result.find((s) => s.type === 'action')
      expect(actionSeg?.content).toBe('walked away')

      const plainSegs = result.filter((s) => s.type === 'plain')
      expect(plainSegs.length).toBeGreaterThanOrEqual(1)
    })

    it('preserves correct ordering of segments in mixed content', () => {
      const result = parseDialogue('He said "hello" and *walked away*')
      expect(result).toEqual([
        { type: 'plain', content: 'He said' },
        { type: 'dialogue', content: 'hello' },
        { type: 'plain', content: 'and' },
        { type: 'action', content: 'walked away' },
      ])
    })
  })

  describe('empty / edge cases', () => {
    it('empty string returns empty array', () => {
      const result = parseDialogue('')
      expect(result).toEqual([])
    })

    it('whitespace-only text with no markers returns a single plain segment', () => {
      // A plain space does not contain any marker characters, so it falls through
      // the precheck and returns a single plain segment (not trimmed by the precheck path).
      const result = parseDialogue('   ')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('plain')
    })
  })

  describe('markdown protection', () => {
    it('**bold** is protected and not parsed as an action', () => {
      const result = parseDialogue('**bold text**')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('plain')
      expect(result[0].content).toBe('**bold text**')
    })

    it('***bold italic*** is protected and not parsed as an action', () => {
      const result = parseDialogue('***bold italic***')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('plain')
      expect(result[0].content).toBe('***bold italic***')
    })

    it('inline code with quotes is protected', () => {
      const result = parseDialogue('Use `"quote"` for code')
      // The `"quote"` inside backticks is protected, so no dialogue segment
      const hasDialogue = result.some((s) => s.type === 'dialogue')
      expect(hasDialogue).toBe(false)
    })

    it("English contractions like don't are protected (not parsed as single-quote dialogue)", () => {
      const result = parseDialogue("I don't know")
      const hasDialogue = result.some((s) => s.type === 'dialogue')
      expect(hasDialogue).toBe(false)
    })

    it('HTML tags are protected (attributes with quotes not parsed as dialogue)', () => {
      const result = parseDialogue('<a href="http://example.com">link</a>')
      const hasDialogue = result.some((s) => s.type === 'dialogue')
      expect(hasDialogue).toBe(false)
    })

    it('fenced code block with backticks is protected as plain text', () => {
      const result = parseDialogue('```\nconst x = "hello"\n```')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('plain')
      const hasDialogue = result.some((s) => s.type === 'dialogue')
      expect(hasDialogue).toBe(false)
    })

    it('code block with asterisks inside is not parsed as action', () => {
      const result = parseDialogue('```\n*this is code, not action*\n```')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('plain')
      expect(result[0].content).toContain('*this is code, not action*')
    })

    it('code block with quotes inside is not parsed as dialogue', () => {
      const result = parseDialogue('```python\nprint("hello world")\n```')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('plain')
      const hasDialogue = result.some((s) => s.type === 'dialogue')
      expect(hasDialogue).toBe(false)
    })

    it('tilde-fenced code block is protected as plain text', () => {
      const result = parseDialogue('~~~\nconst x = *not action*\n~~~')
      expect(result).toHaveLength(1)
      expect(result[0].type).toBe('plain')
    })

    it('code block alongside dialogue and action is parsed correctly', () => {
      const result = parseDialogue('"Hello" she said\n```\ncode here\n```\n*waves*')
      const types = result.map((s) => s.type)
      expect(types).toContain('dialogue')
      expect(types).toContain('plain')
      expect(types).toContain('action')

      const dialogueSeg = result.find((s) => s.type === 'dialogue')
      expect(dialogueSeg?.content).toBe('Hello')

      const actionSeg = result.find((s) => s.type === 'action')
      expect(actionSeg?.content).toBe('waves')

      const plainSegs = result.filter((s) => s.type === 'plain')
      expect(plainSegs.length).toBeGreaterThanOrEqual(1) // " she said" + code block（合并在一个 plain 段）
    })
  })

  describe('multiple dialogue blocks', () => {
    it('multiple dialogue blocks are parsed correctly', () => {
      const result = parseDialogue('"Hello" she said. "How are you?"')
      expect(result.length).toBeGreaterThanOrEqual(3)

      const dialogueSegs = result.filter((s) => s.type === 'dialogue')
      expect(dialogueSegs).toHaveLength(2)
      expect(dialogueSegs[0].content).toBe('Hello')
      expect(dialogueSegs[1].content).toBe('How are you?')

      const plainSeg = result.find((s) => s.type === 'plain')
      expect(plainSeg?.content).toBe('she said.')
    })

    it('alternating speakers are parsed correctly', () => {
      const result = parseDialogue('Alice: "Hi" Bob: "Hey"')
      const dialogueSegs = result.filter((s) => s.type === 'dialogue')
      expect(dialogueSegs).toHaveLength(2)
      expect(dialogueSegs[0].speaker).toBe('Alice')
      expect(dialogueSegs[0].content).toBe('Hi')
      expect(dialogueSegs[1].speaker).toBe('Bob')
      expect(dialogueSegs[1].content).toBe('Hey')
    })
  })

  describe('return type', () => {
    it('returns an array of DialogueSegment objects', () => {
      const result = parseDialogue('test "dialogue" *action*')
      expect(Array.isArray(result)).toBe(true)
      for (const seg of result) {
        expect(['dialogue', 'action', 'plain']).toContain(seg.type)
        expect(typeof seg.content).toBe('string')
      }
    })
  })
})

import { describe, it, expect } from 'vitest'
import {
  expandMacros,
  registerMacro,
  unregisterMacro,
  listMacros,
  hasMacro,
  buildMacroContext,
  type MacroContext,
} from '../macros'

function makeCtx(overrides: Partial<MacroContext> = {}): MacroContext {
  return {
    userName: '小明',
    charName: '爱丽丝',
    originalCharName: 'Alice',
    groupName: '冒险小队',
    lastMessage: '最后一条内容',
    lastUserMessage: '用户最后一条',
    ...overrides,
  }
}

describe('内置宏', () => {
  it('{{time}} 输出 HH:mm 格式', () => {
    expect(expandMacros('现在{{time}}', makeCtx())).toMatch(/现在\d{2}:\d{2}/)
  })

  it('{{date}} 输出 YYYY/MM/DD 格式', () => {
    expect(expandMacros('{{date}}', makeCtx())).toMatch(/^\d{4}\/\d{2}\/\d{2}$/)
  })

  it('{{datetime}} 输出日期时间', () => {
    expect(expandMacros('{{datetime}}', makeCtx())).toMatch(/^\d{4}\/\d{2}\/\d{2} \d{2}:\d{2}$/)
  })

  it('{{random:A|B|C}} 随机取一个选项', () => {
    for (let i = 0; i < 20; i++) {
      const result = expandMacros('{{random:早安|晚安|你好}}', makeCtx())
      expect(['早安', '晚安', '你好']).toContain(result)
    }
  })

  it('{{random:}} 空参数返回空', () => {
    expect(expandMacros('{{random:}}', makeCtx())).toBe('')
  })

  it('{{newline}} 输出换行', () => {
    expect(expandMacros('a{{newline}}b', makeCtx())).toBe('a\nb')
  })

  it('{{group}} 输出群聊名（单聊为空）', () => {
    expect(expandMacros('{{group}}', makeCtx())).toBe('冒险小队')
    expect(expandMacros('{{group}}', makeCtx({ groupName: '' }))).toBe('')
  })

  it('{{lastMessage}} / {{lastUserMessage}} 输出对应消息', () => {
    expect(expandMacros('{{lastMessage}}', makeCtx())).toBe('最后一条内容')
    expect(expandMacros('{{lastUserMessage}}', makeCtx())).toBe('用户最后一条')
  })

  it('{{char}} / {{user}} / {{original}} 委托上下文', () => {
    expect(expandMacros('{{char}} {{user}} {{original}}', makeCtx())).toBe('爱丽丝 小明 Alice')
  })

  it('{{id}} 输出短随机 id', () => {
    expect(expandMacros('{{id}}', makeCtx())).toMatch(/^[a-z0-9]{6}$/)
  })

  it('未注册宏原样保留', () => {
    expect(expandMacros('未知宏 {{unknown}} 保留', makeCtx())).toBe('未知宏 {{unknown}} 保留')
  })

  it('大小写不敏感', () => {
    expect(expandMacros('{{TIME}} {{Random:甲|乙}}', makeCtx())).toMatch(/^\d{2}:\d{2} [甲乙]$/)
  })

  it('参数中 \| 转义为字面竖线', () => {
    // \| 输出字面竖线（不参与分隔）：选项为 [a|b] 与 [c]
    const result = expandMacros('{{random:a\\|b|c}}', makeCtx())
    expect(['a|b', 'c']).toContain(result)
  })

  it('空文本原样返回', () => {
    expect(expandMacros('', makeCtx())).toBe('')
    expect(expandMacros('无宏文本', makeCtx())).toBe('无宏文本')
  })
})

describe('宏注册表', () => {
  it('registerMacro 后立即可用，unregisterMacro 后回退为原样', () => {
    registerMacro('double', (args) => String(Number(args[0] ?? 0) * 2), { name: 'double', description: 'x2', example: '{{double:21}}' })
    expect(expandMacros('{{double:21}}', makeCtx())).toBe('42')
    expect(listMacros().some((m) => m.name === 'double')).toBe(true)
    unregisterMacro('double')
    expect(expandMacros('{{double:21}}', makeCtx())).toBe('{{double:21}}')
    expect(listMacros().some((m) => m.name === 'double')).toBe(false)
  })

  it('宏抛错时保留原文', () => {
    registerMacro('boom', () => { throw new Error('boom') })
    expect(expandMacros('{{boom}}', makeCtx())).toBe('{{boom}}')
    unregisterMacro('boom')
  })
})

describe('hasMacro / buildMacroContext', () => {
  it('hasMacro 检测宏语法', () => {
    expect(hasMacro('{{time}}')).toBe(true)
    expect(hasMacro('{{ random: a }}')).toBe(true)
    expect(hasMacro('普通文本')).toBe(false)
  })

  it('buildMacroContext 提取最后一条消息', () => {
    const ctx = buildMacroContext([
      { role: 'user', content: '第一条' },
      { role: 'assistant', content: '' },
      { role: 'assistant', content: '第二条' },
    ], { userName: 'u', charName: 'c', groupName: 'g' })
    expect(ctx.lastMessage).toBe('第二条')
    expect(ctx.lastUserMessage).toBe('第一条')
    expect(ctx.groupName).toBe('g')
  })

  it('buildMacroContext 空消息列表', () => {
    const ctx = buildMacroContext(undefined, { userName: 'u', charName: 'c' })
    expect(ctx.lastMessage).toBe('')
    expect(ctx.lastUserMessage).toBe('')
  })
})

