/**
 * 对话片段解析器
 * 将角色对话消息拆分为：引用对话、动作描述、旁白叙述 三类片段
 *
 * ## 支持的对话格式
 *
 * ### 双引号对话（中文/English）
 * - `Speaker: "text"` / `Speaker："text"` → dialogue（半角/全角冒号）
 * - `"text"` → dialogue（无说话人）
 *
 * ### 单引号对话
 * - `Speaker: 'text'` / `Speaker：'text'` → dialogue
 *
 * ### 中文特有
 * - `「text」` / `『text』` / `〝text〞` -> 归一化为 "text" 后匹配
 *
 * ### 动作/场景描述
 * - `*action*` → action（支持内含 * 的复杂动作描述）
 *
 * ### 保护机制
 * - 围栏代码块 ```...``` / ~~~...~~~ → protected（不被解析）
 * - Markdown 粗体/粗斜体/删除线 → protected（不被解析）
 * - HTML 标签 → protected
 * - Markdown 图片/链接 → protected
 * - 行内代码 `code` → protected
 * - 英文缩写 don't / can't / it's → protected
 *
 * @param text 原始消息文本
 * @returns 结构化片段数组
 */

export interface DialogueSegment {
  /** 片段类型 */
  type: 'dialogue' | 'action' | 'plain'
  /** 说话人名称（如有，如 Flora: "..."） */
  speaker?: string
  /** 片段文本内容 */
  content: string
}

/** 占位符标记（使用 Unicode 私用区字符，避免空字节 \x00 在渲染管道中被破坏） */
const PH_MARKER = 'PH'

export function parseDialogue(text: string): DialogueSegment[] {
  if (!text) return []

  // 快速预检：如果文本不含任何对话/动作标记字符，直接返回纯文本
  // 注意：必须包含所有 Unicode 引号变体（""「」〝〞等），否则中文引号文本会被误判为纯文本
  if (!/[*":：'\u201C\u201D\-~()\[\]「」『』〝〞]/.test(text)) {
    return [{ type: 'plain', content: text }]
  }

  // 预处理：用占位符保护 HTML 标签和 markdown 图片/链接
  // 避免 HTML 属性值中的引号被 "[^"]*" 误匹配为对话
  // 避免 URL 中的 * 被 \*...\* 误匹配为动作描写
  const placeholders: string[] = []
  const protect = (m: string): string => {
    placeholders.push(m)
    return `${PH_MARKER}${placeholders.length - 1}${PH_MARKER}`
  }

  const protectedText = text
    // B-05: 归一化 Unicode 引号变体为 ASCII 引号
    // B-07: 先处理转义引号 \" -> "
    // B-08: 新增 CJK 双引号 〝〞 (U+301D/E)、直角引号表示形式 ﹁﹃﹂﹄ (U+FE41-44)
    // 修复：中文弯引号 \u201C\u201D（最常见的中文双引号）此前误写为两个 ASCII "，导致从未被归一化
    .replace(/\\"/g, '"')
    .replace(/[\u201C\u201D„‟＂「『‹«〝﹁﹃]/g, '"')
    .replace(/[」』›»〞﹂﹄]/g, '"')
    // 保护围栏代码块（```...``` / ~~~...~~~），避免代码块内的 *、" 等字符触发误匹配
    // 必须在 bold/italic 保护之前，否则代码块内的 ** 会被误保护
    .replace(/```[\s\S]*?```/g, protect)
    .replace(/~~~[\s\S]*?~~~/g, protect)
    // B-08: 保护英文缩写（don't, can't, it's 等），避免被单引号对话正则误匹配
    .replace(/\b[A-Za-z]+'[A-Za-z]+\b/g, protect)
    // B-06: 保护 markdown 粗体/粗斜体/删除线，避免被动作正则 *...* 误匹配
    // B-08: 改用 [\s\S]+? 非贪婪匹配，解决 **bold *italic* text** 内含 * 时保护失败
    .replace(/\*{3}[\s\S]+?\*{3}/g, protect)          // 粗斜体 ***...***
    .replace(/_{3}[\s\S]+?_{3}/g, protect)             // 粗斜体 ___...___
    .replace(/\*\*[\s\S]+?\*\*/g, protect)             // 粗体 **...**
    .replace(/__[\s\S]+?__/g, protect)                 // 粗体 __...__
    .replace(/~~[\s\S]+?~~/g, protect)                 // 删除线 ~~...~~
    .replace(/<\/?[a-zA-Z][^>]*\/?>/g, protect)       // HTML 标签 <...>
    .replace(/!\[[^\]]*\]\([^)]*\)/g, protect)         // markdown 图片 ![alt](url)
    .replace(/\[[^\]]*\]\([^)]*\)/g, protect)          // markdown 链接 [text](url)
    .replace(/`[^`\n]+`/g, protect)                   // 行内代码 `code`

  /** 将占位符还原为原始内容（循环处理嵌套占位符） */
  const restore = (s: string): string => {
    const pattern = new RegExp(`${PH_MARKER}(\\d+)${PH_MARKER}`, 'g')
    let result = s
    // 循环替换直到没有更多占位符，处理 don't → **don't** 这样的嵌套保护
    for (let i = 0; i < 10; i++) {
      const prev = result
      result = result.replace(pattern, (_, idx) => placeholders[Number(idx)])
      if (result === prev) break // 没有更多占位符可替换
    }
    return result
  }

  const segments: DialogueSegment[] = []

  // 核心解析正则（硬编码，避免 new RegExp 字符串拼接导致运行时开销和转义问题）
  // 组1: *动作描述* — [\s\S]+? 非贪婪，支持内含 *（如 *does *this* too*）
  // 组2: Name: "dialogue" / Name："dialogue" — 半角/全角冒号双引号对话
  // 组3: "dialogue" — 无说话人双引号对话
  // 组4: Name: 'dialogue' / Name：'dialogue' - 单引号对话
  const pattern = /(\*[\s\S]+?\*)|(\S+[:：]\s*"[^"]*")|("[^"]*")|(\S+[:：]\s*'[^']*')/g

  let lastIndex = 0
  let match: RegExpExecArray | null

  while ((match = pattern.exec(protectedText)) !== null) {
    // 匹配之前的纯文本
    if (match.index > lastIndex) {
      const plainText = protectedText.slice(lastIndex, match.index).trim()
      if (plainText) {
        segments.push({ type: 'plain', content: restore(plainText) })
      }
    }

    const fullMatch = match[0]

    if (match[1]) {
      // *动作描述*
      const inner = fullMatch.slice(1, -1).trim()
      if (inner) {
        segments.push({ type: 'action', content: restore(inner) })
      }
    } else if (match[2]) {
      // Speaker: "对话" / Speaker："对话"
      const colonIdx = /[:：]/.exec(fullMatch)!.index
      const speaker = fullMatch.slice(0, colonIdx).trim()
      const rawInner = fullMatch.slice(colonIdx + 1).trim()
      const inner = rawInner.startsWith('"') && rawInner.endsWith('"')
        ? rawInner.slice(1, -1)
        : rawInner
      if (speaker && inner) {
        segments.push({ type: 'dialogue', speaker: restore(speaker), content: restore(inner) })
      }
    } else if (match[3]) {
      // "对话"
      const inner = fullMatch.slice(1, -1).trim()
      if (inner) {
        segments.push({ type: 'dialogue', content: restore(inner) })
      }
    } else if (match[4]) {
      // Speaker: 'dialogue' / Speaker：'dialogue'
      const colonIdx = /[:：]/.exec(fullMatch)!.index
      const speaker = fullMatch.slice(0, colonIdx).trim()
      const rawInner = fullMatch.slice(colonIdx + 1).trim()
      const inner = rawInner.startsWith("'") && rawInner.endsWith("'")
        ? rawInner.slice(1, -1)
        : rawInner
      if (speaker && inner) {
        segments.push({ type: 'dialogue', speaker: restore(speaker), content: restore(inner) })
      }
    }

    lastIndex = match.index + fullMatch.length
  }

  // 末尾剩余纯文本
  if (lastIndex < protectedText.length) {
    const remainingText = protectedText.slice(lastIndex).trim()
    if (remainingText) {
      segments.push({ type: 'plain', content: restore(remainingText) })
    }
  }

  return segments
}

/**
 * 消息后处理工具
 *
 * 解决连续相同角色消息导致的 API 格式错误问题。
 * 例如：[user: "你好"], [user: "我是小明"] → [user: "你好\n\n我是小明"]
 */

interface ChatMessage {
  role: 'system' | 'user' | 'assistant'
  content: string
  /** 标记为需保持独立的注入消息（如 at_depth 世界书、作者注释），跳过合并 */
  keepSeparate?: boolean
  [key: string]: any
}

/**
 * 合并连续相同角色的消息
 *
 * SillyTavern 的 MERGE 模式实现：
 * - 连续的 system 消息合并为一条
 * - 连续的 user 消息合并为一条
 * - 连续的 assistant 消息合并为一条
 * - system 消息穿插在 user/assistant 之间时，合并到前一条消息
 *
 * @param messages 原始消息数组
 * @returns 合并后的消息数组
 */
export function mergeConsecutiveMessages(messages: ChatMessage[]): ChatMessage[] {
  if (!messages || messages.length === 0) return []

  const merged: ChatMessage[] = []

  for (const msg of messages) {
    const lastMsg = merged[merged.length - 1]

    if (!lastMsg) {
      // 第一条消息直接加入
      merged.push({ ...msg })
      continue
    }

    // keepSeparate：按深度注入的 system 消息保持独立，不被合并进相邻消息
    // （否则 at_depth 世界书 / 作者注释会被并入前一条消息，深度注入失效）
    if (msg.keepSeparate || lastMsg.keepSeparate) {
      merged.push({ ...msg })
      continue
    }

    // 如果角色相同，合并内容
    if (lastMsg.role === msg.role) {
      lastMsg.content = `${lastMsg.content}\n\n${msg.content}`
    }
    // 如果当前是 system 且上一条是 user/assistant，合并到上一条
    // （system 穿插在对话中时，追加到前一条消息）
    else if (msg.role === 'system' && (lastMsg.role === 'user' || lastMsg.role === 'assistant')) {
      lastMsg.content = `${lastMsg.content}\n\n${msg.content}`
    }
    // 其他情况，直接加入
    else {
      merged.push({ ...msg })
    }
  }

  return merged
}

/**
 * 严格模式：保持角色交替
 *
 * SillyTavern 的 STRICT 模式实现：
 * - 强制 user/assistant 交替出现
 * - 连续相同角色消息合并
 * - system 消息使用占位符替换
 *
 * @param messages 原始消息数组
 * @param placeholder system 消息的占位符文本
 * @returns 处理后的消息数组
 */
export function strictAlternatingMessages(
  messages: ChatMessage[],
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  _placeholder = '[System message]'
): ChatMessage[] {
  if (!messages || messages.length === 0) return []

  // 第一步：合并连续相同角色
  const result = mergeConsecutiveMessages(messages)

  // 第二步：确保 user/assistant 交替
  const final: ChatMessage[] = []

  for (const msg of result) {
    if (msg.role === 'system') {
      // system 消息保持原样
      final.push({ ...msg })
      continue
    }

    const lastMsg = final[final.length - 1]

    if (!lastMsg || lastMsg.role === msg.role) {
      // 角色相同，合并
      final.push({ ...msg })
    } else if (lastMsg.role === 'system') {
      // 上一条是 system，当前是 user/assistant，直接加入
      final.push({ ...msg })
    } else {
      // 正常交替，直接加入
      final.push({ ...msg })
    }
  }

  return final
}

/**
 * Semi 模式：允许连续 system，但 user/assistant 必须交替
 *
 * @param messages 原始消息数组
 * @returns 处理后的消息数组
 */
export function semiStrictMessages(messages: ChatMessage[]): ChatMessage[] {
  if (!messages || messages.length === 0) return []

  const result: ChatMessage[] = []

  for (const msg of messages) {
    const lastMsg = result[result.length - 1]

    if (!lastMsg) {
      result.push({ ...msg })
      continue
    }

    // system 消息可以连续
    if (msg.role === 'system' && lastMsg.role === 'system') {
      lastMsg.content = `${lastMsg.content}\n\n${msg.content}`
    }
    // user/assistant 相同角色合并
    else if (msg.role === lastMsg.role && msg.role !== 'system') {
      lastMsg.content = `${lastMsg.content}\n\n${msg.content}`
    }
    // 其他情况直接加入
    else {
      result.push({ ...msg })
    }
  }

  return result
}

/**
 * 思考标签（<thought> / <thinking>）处理工具
 *
 * 部分 AI 模型（如 DeepSeek）使用 <thinking> 而非 <thought>，
 * 以下函数统一归一化并提取/剥离思考内容。
 */

/** 将 <thinking> 标签归一化为 <thought> */
export function normalizeThoughtTags(text: string): string {
  if (!text) return text
  return text
    .replace(/<thinking([\s>])/gi, '<thought$1')
    .replace(/<\/thinking>/gi, '</thought>')
}

/**
 * 提取所有 <thought> 块内容
 * @returns thought: 拼接的思考内容（无则为 null）; content: 剥离 thought 后的正文（为空时回退到思考内容）; isFallback: 是否触发了回退
 */
export function extractThought(text: string): { thought: string | null; content: string; isFallback: boolean } {
  if (!text) return { thought: null, content: '', isFallback: false }
  const normalized = normalizeThoughtTags(text)
  const thoughtRegex = /<thought>([\s\S]*?)<\/thought>/gi
  const thoughts: string[] = []
  let m: RegExpExecArray | null
  while ((m = thoughtRegex.exec(normalized)) !== null) {
    thoughts.push(m[1].trim())
  }
  const stripped = normalized.replace(/<thought>[\s\S]*?<\/thought>/gi, '').trim()
  const thought = thoughts.length > 0 ? thoughts.join('\n\n') : null
  // 剥离后为空则回退到思考内容，避免显示"空消息"
  const isFallback = !stripped && !!thought
  const content = stripped || (thought ?? '')
  return { thought, content, isFallback }
}

/** 剥离 <thought> 块，返回剩余正文（不做空回退） */
export function stripThought(text: string): string {
  if (!text) return text
  return normalizeThoughtTags(text).replace(/<thought>[\s\S]*?<\/thought>/gi, '').trim()
}

/** 去掉 <thought> 标签本身但保留内容（用于 TTS 朗读内心想法等场景） */
export function stripThoughtTags(text: string): string {
  if (!text) return text
  return normalizeThoughtTags(text).replace(/<\/?thought>/gi, '').trim()
}

/** 续写重叠去重的最小重叠长度（字符） */
const MIN_CONTINUATION_OVERLAP = 8

/**
 * 续写复述前缀去重
 *
 * 模型续写时常会复述原消息的结尾（如把最后一句重打一遍再接新内容）。
 * 此函数检测 next 开头与 prev 结尾的最长重叠（≥ MIN_CONTINUATION_OVERLAP 字符），
 * 剪掉 next 的重叠前缀并清理首部空白。
 *
 * 不做智能改写/段落重排，衔接语义由续写指令负责。
 *
 * @param prev 原消息内容
 * @param next 模型返回的续写内容
 * @returns 去重后的续写内容
 */
export function trimContinuationOverlap(prev: string, next: string): string {
  if (!prev || !next) return next
  // 最长可能重叠不超过两者较短长度
  const maxOverlap = Math.min(prev.length, next.length)
  for (let len = maxOverlap; len >= MIN_CONTINUATION_OVERLAP; len--) {
    if (prev.endsWith(next.slice(0, len))) {
      // 剪掉重叠前缀，并清理剪切处残留的首部空白
      return next.slice(len).replace(/^\s+/, '')
    }
  }
  return next
}

/**
 * Prompt 格式转换器
 *
 * 不同 AI 提供商的消息格式要求不同：
 * - OpenAI: 标准 ChatML 格式 (system/user/assistant)
 * - Claude: system 单独处理，消息必须 user/assistant 交替
 * - Gemini: 类似 OpenAI，但有一些差异
 *
 * 参考 SillyTavern 的 prompt-converters.js 实现
 */

interface ChatMessage {
  role: 'system' | 'user' | 'assistant'
  content: string
  [key: string]: any
}

interface PromptNames {
  charName: string
  userName: string
}

/**
 * OpenAI 格式（默认）
 * 直接使用原始消息格式，无需转换
 */
export function convertToOpenAI(messages: ChatMessage[]): ChatMessage[] {
  return messages
}

/**
 * Claude 格式转换
 *
 * Claude 的要求：
 * 1. system 消息必须放在最前面，且只能有一条
 * 2. 消息必须 user/assistant 交替出现
 * 3. 不能有连续的 user 或 assistant 消息
 * 4. 最后一条应该是 user 消息（或者使用 assistant prefill）
 *
 * @param messages 原始消息数组
 * @param names 角色名信息
 * @returns 转换后的消息数组
 */
// eslint-disable-next-line @typescript-eslint/no-unused-vars
export function convertToClaude(messages: ChatMessage[], _names: PromptNames): ChatMessage[] {
  if (!messages || messages.length === 0) return []

  const result: ChatMessage[] = []
  let systemContent = ''

  // 第一步：收集所有 system 消息并合并
  for (const msg of messages) {
    if (msg.role === 'system') {
      if (systemContent) {
        systemContent += '\n\n'
      }
      systemContent += msg.content
    }
  }

  // 添加合并后的 system 消息
  if (systemContent) {
    result.push({ role: 'system', content: systemContent })
  }

  // 第二步：处理非 system 消息，确保交替
  let lastRole: string | null = null

  for (const msg of messages) {
    if (msg.role === 'system') continue

    if (msg.role === lastRole) {
      // 连续相同角色，合并到上一条
      const lastMsg = result[result.length - 1]
      if (lastMsg) {
        lastMsg.content += '\n\n' + msg.content
      }
    } else {
      // 不同角色，直接添加
      result.push({ ...msg })
      lastRole = msg.role
    }
  }

  // 第三步：确保最后一条是 user 消息（Claude 要求）
  if (result.length > 0 && result[result.length - 1].role === 'assistant') {
    // 如果最后是 assistant，添加一个空的 user 消息
    result.push({ role: 'user', content: '[Continue]' })
  }

  return result
}

/**
 * Gemini 格式转换
 *
 * Gemini 的要求：
 * 1. 支持 system 消息（作为 system_instruction）
 * 2. 消息格式类似 OpenAI
 * 3. 不支持连续的相同角色消息
 *
 * @param messages 原始消息数组
 * @returns 转换后的消息数组
 */
export function convertToGemini(messages: ChatMessage[]): ChatMessage[] {
  if (!messages || messages.length === 0) return []

  const result: ChatMessage[] = []
  let lastRole: string | null = null

  for (const msg of messages) {
    if (msg.role === lastRole) {
      // 连续相同角色，合并
      const lastMsg = result[result.length - 1]
      if (lastMsg) {
        lastMsg.content += '\n\n' + msg.content
      }
    } else {
      result.push({ ...msg })
      lastRole = msg.role
    }
  }

  return result
}

/**
 * 根据提供商选择合适的格式转换器
 *
 * @param provider 提供商类型
 * @param messages 原始消息数组
 * @param names 角色名信息
 * @returns 转换后的消息数组
 */
export function convertMessages(
  provider: string,
  messages: ChatMessage[],
  names: PromptNames = { charName: '', userName: '' }
): ChatMessage[] {
  const lowerProvider = provider.toLowerCase()

  if (lowerProvider.includes('claude')) {
    return convertToClaude(messages, names)
  }

  if (lowerProvider.includes('gemini')) {
    return convertToGemini(messages)
  }

  // 默认使用 OpenAI 格式
  return convertToOpenAI(messages)
}

/**
 * 添加 Assistant Prefix（续写模式）
 *
 * 在消息末尾添加空的 assistant 消息，引导模型继续生成
 *
 * @param messages 消息数组
 * @param prefix 可选的前缀文本
 * @returns 添加 prefix 后的消息数组
 */
export function addAssistantPrefix(
  messages: ChatMessage[],
  prefix?: string
): ChatMessage[] {
  if (!messages || messages.length === 0) return messages

  // 检查最后一条是否已经是 assistant
  const lastMsg = messages[messages.length - 1]
  if (lastMsg.role === 'assistant') {
    // 已经是 assistant，不需要添加
    return messages
  }

  // 添加空的 assistant 消息
  return [
    ...messages,
    { role: 'assistant', content: prefix || '' }
  ]
}
